INSERT INTO "Course" ("id", "slug", "title", "subtitle", "description", "isPublished", "createdAt", "updatedAt") VALUES ('m35n2u60pubvs9t826p6l3fk', 'transplant-alchemy-101', 'Transplant Alchemy 101', 'Save7 Organ Donation & Transplantation Awareness Course', 'A three-level learning pathway. Some people join Save7 already understanding the transplant landscape in South Africa; others have never been exposed to the organ donation crisis. What everyone has in common is a passion for educating others.', 1, '2026-08-18T19:36:16.730+00:00', '2026-08-18T19:36:16.730+00:00');
INSERT INTO "Level" ("id", "courseId", "order", "slug", "tier", "title", "strapline", "goal", "estMinMinutes", "estMaxMinutes", "accentToken", "certificateTitle", "certificateCode", "passMarkPct") VALUES ('r2c3xtv3fjygs84lo5odbkv7', 'm35n2u60pubvs9t826p6l3fk', 1, 'beginner', 'BEGINNER', 'Start the Conversation', 'For anyone who wants to understand the basics of organ donation.', 'Give you enough knowledge to confidently talk about organ donation with family, friends and the public.', 30, 45, 'beginner', 'Conversation Starter', 'B', 70);
INSERT INTO "Level" ("id", "courseId", "order", "slug", "tier", "title", "strapline", "goal", "estMinMinutes", "estMaxMinutes", "accentToken", "certificateTitle", "certificateCode", "passMarkPct") VALUES ('kgbnni0rydlpooi38l348tp4', 'm35n2u60pubvs9t826p6l3fk', 2, 'intermediate', 'INTERMEDIATE', 'Understand the Journey', 'For learners who want to understand how donation and transplantation actually work.', 'Move beyond basic awareness and understand how organ donation actually works in South Africa.', 45, 60, 'intermediate', 'Donation Advocate', 'I', 70);
INSERT INTO "Level" ("id", "courseId", "order", "slug", "tier", "title", "strapline", "goal", "estMinMinutes", "estMaxMinutes", "accentToken", "certificateTitle", "certificateCode", "passMarkPct") VALUES ('ddtjesv8e0f2lou2i4jbf81t', 'm35n2u60pubvs9t826p6l3fk', 3, 'advanced', 'ADVANCED', 'Become a Transplant Advocate', 'For Save7 volunteers and motivated learners who want a deeper understanding of the transplant landscape.', 'Develop a deeper understanding of the clinical, ethical, legal and communication landscape surrounding transplantation.', 60, 90, 'advanced', 'Transplant Advocate', 'A', 70);
INSERT INTO "Module" ("id", "levelId", "order", "slug", "title", "coreQuestion", "introMarkdown", "estMinutes", "isMandatory", "createdAt", "updatedAt") VALUES ('o4uhyh92co3dakkj9jkz66ra', 'r2c3xtv3fjygs84lo5odbkv7', 1, 'who-needs-organs', 'Who Needs Organs?', 'Why do people need donated organs and tissues?', 'Transplantation is easy to think about in the abstract. It is much harder to ignore once you know who is actually waiting.
INSERT INTO "Module" ("id", "levelId", "order", "slug", "title", "coreQuestion", "introMarkdown", "estMinutes", "isMandatory", "createdAt", "updatedAt") VALUES ('fy5gk5lj0glyc8cimfs0iamm', 'r2c3xtv3fjygs84lo5odbkv7', 2, 'why-are-we-losing-organs', 'Why Are We Losing Organs?', 'If so many people need organs, why aren''t more organs reaching them?', 'This is the most important module in the course.
INSERT INTO "Module" ("id", "levelId", "order", "slug", "title", "coreQuestion", "introMarkdown", "estMinutes", "isMandatory", "createdAt", "updatedAt") VALUES ('utdb2izuy72czxajhg7r2o23', 'r2c3xtv3fjygs84lo5odbkv7', 3, 'basics-of-organ-donation', 'The Basics of Organ Donation', 'What actually happens when someone becomes a donor?', 'You now know who is waiting, and where donations are lost. This module fills in the mechanism in between.
INSERT INTO "Module" ("id", "levelId", "order", "slug", "title", "coreQuestion", "introMarkdown", "estMinutes", "isMandatory", "createdAt", "updatedAt") VALUES ('q65o68xry6cy2gq2zuqz7aru', 'r2c3xtv3fjygs84lo5odbkv7', 4, 'having-the-conversation', 'Having the Conversation', 'How do I actually talk to someone about organ donation?', 'This is where the Beginner level pays off.
INSERT INTO "Module" ("id", "levelId", "order", "slug", "title", "coreQuestion", "introMarkdown", "estMinutes", "isMandatory", "createdAt", "updatedAt") VALUES ('pn0m2s6lc0yqqeb8jvf9k3hn', 'kgbnni0rydlpooi38l348tp4', 1, 'journey-of-a-gift', 'The Journey of a Gift', 'What is the full journey from a potential donor to a recipient''s new life?', 'In Module 2 you walked this pathway looking for the places it breaks. Now you walk it properly, end to end, as the people living through it experience it.
INSERT INTO "Module" ("id", "levelId", "order", "slug", "title", "coreQuestion", "introMarkdown", "estMinutes", "isMandatory", "createdAt", "updatedAt") VALUES ('dupcdrukzkq2wdzrh2ehhee8', 'kgbnni0rydlpooi38l348tp4', 2, 'what-does-death-mean', 'What Does Death Mean?', 'How can someone be declared dead while their heart is still beating?', 'This is the question that stops donation conversations dead, and the one most advocates feel least equipped to answer.
INSERT INTO "Module" ("id", "levelId", "order", "slug", "title", "coreQuestion", "introMarkdown", "estMinutes", "isMandatory", "createdAt", "updatedAt") VALUES ('igmbm623gsgsydnrkwvvht7l', 'kgbnni0rydlpooi38l348tp4', 3, 'who-makes-it-happen', 'Who Makes It Happen?', 'Who are all the people involved in a single donation?', 'Donation is often imagined as something two surgeons do. It is closer to a relay involving a dozen roles, several of which most people have never heard of.
INSERT INTO "Module" ("id", "levelId", "order", "slug", "title", "coreQuestion", "introMarkdown", "estMinutes", "isMandatory", "createdAt", "updatedAt") VALUES ('fdyb9a50o4n2x8pqvks17blp', 'kgbnni0rydlpooi38l348tp4', 4, 'who-can-donate', 'Who Can Donate?', 'Can I donate if I''m old, sick, or have another medical condition?', 'More potential donors are lost to self-exclusion than most people realise. Someone decides privately that they would not be eligible, and never mentions it again.
INSERT INTO "Module" ("id", "levelId", "order", "slug", "title", "coreQuestion", "introMarkdown", "estMinutes", "isMandatory", "createdAt", "updatedAt") VALUES ('tnvu4480yubmdf54pi8nhoie', 'ddtjesv8e0f2lou2i4jbf81t', 1, 'the-law', 'The Law', 'What does South African law actually say about organ donation?', 'Advocates get asked legal questions constantly. *Can my family override my wishes? Who has to consent? Does it cost anything?*
INSERT INTO "Module" ("id", "levelId", "order", "slug", "title", "coreQuestion", "introMarkdown", "estMinutes", "isMandatory", "createdAt", "updatedAt") VALUES ('gkh2ea7yygxftemfrwmx9nac', 'ddtjesv8e0f2lou2i4jbf81t', 2, 'transplant-landscape', 'The Transplant Landscape', 'How are transplant candidates actually selected and assessed?', 'This is the most clinical module in the course, and it is here rather than in Beginner for a reason: nobody needs it to start a conversation.
INSERT INTO "Module" ("id", "levelId", "order", "slug", "title", "coreQuestion", "introMarkdown", "estMinutes", "isMandatory", "createdAt", "updatedAt") VALUES ('rqbcwtid9j9vbik6cabq6v8p', 'ddtjesv8e0f2lou2i4jbf81t', 3, 'life-after-donation', 'Life After Donation', 'What happens to the recipient after the transplant?', 'Public conversation about donation tends to stop at the operating theatre, as though transplantation were an ending.
INSERT INTO "Module" ("id", "levelId", "order", "slug", "title", "coreQuestion", "introMarkdown", "estMinutes", "isMandatory", "createdAt", "updatedAt") VALUES ('auptjr9yc0gqtaxqy34509lv', 'ddtjesv8e0f2lou2i4jbf81t', 4, 'art-of-the-conversation', 'The Art of the Conversation', 'How do I handle the hardest conversations, with people in real distress?', 'Module 4 taught you to talk to a friend over coffee. This module is about the conversations that are genuinely difficult: grief, family disagreement, deep mistrust, and beliefs you do not share.
INSERT INTO "Module" ("id", "levelId", "order", "slug", "title", "coreQuestion", "introMarkdown", "estMinutes", "isMandatory", "createdAt", "updatedAt") VALUES ('xz0cbqav6esbaiht4u74dsj6', 'ddtjesv8e0f2lou2i4jbf81t', 5, 'become-a-save7-advocate', 'Become a Save7 Advocate', 'What do I do with all of this?', 'You have reached the end of the pathway. This module is not new material — it is the point where everything you have learned becomes something you can use.
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('fymkomgjvjmtb3r9sff37vfl', 'o4uhyh92co3dakkj9jkz66ra', 1, 'intro', 'Why this matters', 'INTRO', 'Most conversations about organ donation start in the wrong place — with death. This one starts with the people who are still alive, and waiting.
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('vxj24555rhuf9viwnmlsi5aw', 'o4uhyh92co3dakkj9jkz66ra', 2, 'explore-organs-and-tissues', 'What can be donated, and who needs it', 'PRIMARY', NULL, 'OrganExplorer', '{"intro":"Select any organ or tissue to see why someone might need it, and what a transplant gives them back. Notice how wide the list is — donation is not only about hearts.","groups":[{"id":"solid-organs","label":"Solid organs","caption":"Recovered and transplanted within hours, and only from a clinical setting. These are the donations most people picture.","items":[{"id":"kidney","name":"Kidneys","category":"Solid organ","whyNeeded":"End-stage renal disease — chronic kidney disease stage 5, where the kidneys can no longer filter the blood well enough to sustain life.","restores":"Freedom from dialysis, and protection from early death. This is the most commonly transplanted organ in South Africa: 2 416 kidney transplants between 2010 and 2019.","note":"A kidney can also come from a living donor."},{"id":"liver","name":"Liver","category":"Solid organ","whyNeeded":"Hepatocellular carcinoma, decompensated cirrhosis, or fulminant hepatic failure — liver disease that has passed the point of recovery.","restores":"Life itself. 593 South African patients were helped with liver transplants between 2010 and 2019.","note":"A segment of liver can also come from a living donor."},{"id":"heart","name":"Heart","category":"Solid organ","whyNeeded":"End-stage heart failure — typically NYHA class IV, with an ejection fraction below 20%. The heart can no longer pump enough blood to sustain ordinary activity.","restores":"Years of active living. 292 hearts were transplanted in South Africa between 2010 and 2019."},{"id":"lungs","name":"Lungs","category":"Solid organ","whyNeeded":"Advanced lung disease such as COPD or cystic fibrosis, where the risk of death exceeds 50% over the next two years.","restores":"The ability to breathe unaided. Lung transplantation remains rare here: 101 lungs transplanted between 2010 and 2019."},{"id":"pancreas","name":"Pancreas","category":"Solid organ","whyNeeded":"Diabetes severe enough that insulin can no longer manage it well, often alongside kidney failure.","restores":"An end to insulin dependency."}]},{"id":"tissue","label":"Tissue","caption":"Often left out of public conversation, and by volume the largest part of what donation achieves. In excess of 150 000 South Africans received tissue transplants between 2010 and 2019.","items":[{"id":"corneas","name":"Corneas","category":"Tissue","whyNeeded":"Corneal damage or disease causing blindness. Note that poor eyesight or cataracts in the donor do not disqualify a cornea.","restores":"Sight. 1 911 patients had their sight restored by corneal transplants between 2010 and 2019.","note":"Cornea donors are generally between 6 and 65 years old."},{"id":"bone-ligaments","name":"Bone and ligaments","category":"Tissue","whyNeeded":"Bone loss or ligament damage from injury, disease or surgery.","restores":"Mobility, and relief from pain.","note":"Bone donors are typically healthy individuals between 16 and 80, without infectious disease or cancer."},{"id":"skin","name":"Skin","category":"Tissue","whyNeeded":"Severe burn injury.","restores":"Survival. Donated skin is what keeps a badly burned patient alive.","note":"Skin donors are typically healthy individuals between 16 and 80, without infectious disease or cancer."},{"id":"heart-valves","name":"Heart valves","category":"Tissue","whyNeeded":"Valve disease, including in children born with heart defects.","restores":"Heart function.","note":"Heart valve donors are eligible from 6 months up to 55 years of age."}]}]}', '2026-08-18T19:36:16.736+00:00', '2026-08-18T19:36:16.736+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('a3rnn5ruylrmfsf5qr0jhe02', 'o4uhyh92co3dakkj9jkz66ra', 3, 'takeaways', 'Key takeaways', 'TAKEAWAYS', NULL, 'TakeawayList', '{"takeaways":[{"id":"t1","text":"Transplantation is not an enhancement. For people in end-stage organ failure it saves or significantly improves life, and for some conditions it is the only remaining option."},{"id":"t2","text":"Thousands of South Africans are on waiting lists for organ and tissue transplants right now."},{"id":"t3","text":"One donor can give seven or more life-saving organs — and their tissues and corneas can improve 65 or more lives.","detail":"This is where Save7''s name comes from. The tissue figure is the part most people have never heard."},{"id":"t4","text":"Donation is far wider than hearts: kidneys, liver, heart, lungs and pancreas, plus corneas, bone, ligaments, skin and heart valves."},{"id":"t5","text":"By volume, tissue is the largest part of what donation achieves — in excess of 150 000 South Africans received tissue transplants between 2010 and 2019."}]}', '2026-08-18T19:36:16.737+00:00', '2026-08-18T19:36:16.737+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('wnzhhw7i0s7wlmn13u4ukyb0', 'o4uhyh92co3dakkj9jkz66ra', 4, 'check', 'Check your understanding', 'CHECK', NULL, NULL, NULL, '2026-08-18T19:36:16.738+00:00', '2026-08-18T19:36:16.738+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('lcy4baovnvujrcr99leplnlx', 'o4uhyh92co3dakkj9jkz66ra', 5, 'study-guide', 'Study guide', 'STUDY_GUIDE', NULL, NULL, '{"summary":"Objective 1 of the Save7 study guide: understand who needs organs.","sections":[{"id":"s1","heading":"End-stage organ failure","body":"Organ and tissue transplantation is required by patients with end-stage organ failure, to save or significantly improve their lives. Thousands of patients are currently on national waiting lists for lifesaving organ and tissue transplants.\n\nRecipients include people needing hearts for years of active living, lungs to allow unaided breathing, and kidneys to save them from dialysis or early death. Patients with liver failure require transplants to restore life, and those needing a pancreas can eliminate insulin dependency."},{"id":"s2","heading":"Specific indications","bullets":["Kidney — end-stage renal disease (CKD 5)","Liver — hepatocellular carcinoma, decompensated cirrhosis, fulminant hepatic failure","Heart — end-stage heart failure (NYHA class IV) with an ejection fraction below 20%","Lung — advanced lung disease such as COPD or cystic fibrosis, with a risk of death exceeding 50% over the next two years","Pancreas — to eliminate insulin dependency"]},{"id":"s3","heading":"Tissue transplantation","body":"Tissue transplants restore sight (corneas), increase mobility and reduce pain (bone and ligaments), save lives after severe burn injury (skin), and improve heart function (heart valves)."},{"id":"s4","heading":"The impact of one donor","body":"One donor can provide seven or more life-saving organs, and tissues and corneas that can improve 65 or more lives.","bullets":["2 416 kidneys transplanted (2010–2019)","593 patients helped with liver transplants (2010–2019)","292 hearts transplanted (2010–2019)","101 lungs transplanted (2010–2019)","1 911 patients had sight restored by corneal transplants (2010–2019)","In excess of 150 000 South Africans received tissue transplants (2010–2019)"],"pendingReview":true}]}', '2026-08-18T19:36:16.739+00:00', '2026-08-18T19:36:16.739+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('jaiyg09ohpmlb6zrxjy12qaw', 'o4uhyh92co3dakkj9jkz66ra', 6, 'further-reading', 'Further reading', 'FURTHER_READING', NULL, 'ResourceList', '{"intro":"Optional. The course is complete without these — they are here for learners who want the clinical detail behind the indications.","note":"Anything marked \"Opens here\" is the document Save7 supplied."}', '2026-08-18T19:36:16.740+00:00', '2026-08-18T19:36:16.740+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('jfbuwdiyzmrhm64qhqm7hde8', 'o4uhyh92co3dakkj9jkz66ra', 7, 'complete', 'Complete module', 'COMPLETE', NULL, NULL, NULL, '2026-08-18T19:36:16.740+00:00', '2026-08-18T19:36:16.740+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('r66f4m4fwy5al040k7u29kjq', 'fy5gk5lj0glyc8cimfs0iamm', 1, 'intro', 'Why this matters', 'INTRO', 'It is tempting to explain the shortage with a single cause. The reality is a chain, and a chain fails at whichever link gives way first.
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('yli7kwe4hltfli2o6wf361rb', 'fy5gk5lj0glyc8cimfs0iamm', 2, 'where-donations-are-lost', 'Where donations are lost', 'PRIMARY', NULL, 'PathwayJourney', '{"intro":"Walk the pathway a potential donation follows. At each step, open the loss points to see how a donation can be lost there.","showLossPoints":true,"steps":[{"id":"potential-donor","label":"Potential donor","summary":"Someone whose circumstances mean donation may become possible.","detail":"Organ donation can only take place in a clinical setting — most often an intensive care unit, where a patient is on a mechanical ventilator. Tissue donation is broader, and can occur irrespective of the manner of death.","lossPoints":[{"id":"no-awareness","label":"Lack of awareness and ignorance of the process","detail":"If people have never considered donation, their families have nothing to go on when they are asked."},{"id":"never-discussed","label":"Registered donors never told their family","detail":"This is the loss point Save7 exists to address. Consent from next of kin is always required — so a registration nobody knows about cannot be acted on."}]},{"id":"identification","label":"Identification","summary":"A clinical team recognises that donation may be possible.","detail":"Identification and referral are the responsibility of the primary treatment team — the doctors and nurses already caring for the patient — as part of end-of-life care.","lossPoints":[{"id":"not-identified","label":"Potential donors are never identified","detail":"Three triggers should prompt a referral in any ventilated patient: a decision has been made to perform brain death tests; there is a catastrophic brain injury with GCS 3–4 not explained by sedation, after a period of observation; or there is an intention to discuss withdrawal of life-sustaining treatment that is expected to result in circulatory death."}]},{"id":"referral","label":"Referral","summary":"The potential donor is referred to a transplant coordinator.","detail":"There is no legal requirement to refer a potential donor. Referral happens because a clinician chooses to make it happen — which is exactly why awareness among clinical staff matters so much. Early referral lets the coordinator screen the patient, identify when donation is not feasible, and avoid delays for the family.","lossPoints":[{"id":"not-referred","label":"Failure to refer before death, or before treatment is withdrawn","detail":"Once the window closes it cannot be reopened. A referral made too late is the same as no referral at all."}]},{"id":"determination-of-death","label":"Determination of death","summary":"Death is formally determined, according to established criteria.","detail":"Two independent doctors are legally required to certify brain death, and neither may be part of the transplant team. Module 6 covers the process in detail.","lossPoints":[{"id":"brain-death-misunderstood","label":"Brain death is misunderstood","detail":"Families may believe their relative is still alive because a ventilator is providing oxygen and the heart is still beating. If a family believes recovery is possible, no consent conversation can succeed."}]},{"id":"family-conversation","label":"Family conversation","summary":"The family is approached about donation.","detail":"The diagnosis of death and the question of donation are deliberately kept apart. The family is told about the death first, and must understand and accept it, before donation is raised at all — usually by a transplant coordinator rather than the treating doctor. This separation is called decoupling.","lossPoints":[{"id":"fear","label":"Fear-based understandings","detail":"Fear does not respond to information delivered impatiently. It responds to being taken seriously."},{"id":"myths","label":"Myths and misunderstandings within communities","detail":"Covered in the next lesson, with what is actually true."},{"id":"cultural","label":"Cultural and religious barriers","detail":"Donation is possible from all communities and cultures in South Africa. It should never be assumed that because a patient or family comes from a particular ethnic, cultural or spiritual background, a referral should not be made — that assumption removes the family''s choice before they are given it."},{"id":"timing","label":"Being approached at an inappropriate time","detail":"Families who are approached before they have accepted the death, or who are rushed, are far more likely to refuse."}]},{"id":"consent","label":"Consent","summary":"Consent for donation is given or withheld by next of kin.","detail":"Informed consent must be obtained from next of kin — a spouse, parent, child, brother or sister — or from a legal guardian. There is an ethical obligation to give every family the opportunity to make a fully informed decision, whichever way they decide.","lossPoints":[{"id":"family-refusal","label":"Family refusal","detail":"Families often say no because they never received factual information, or because they were asked at the wrong moment. A family that already knows their relative''s wishes is not being asked to guess."},{"id":"rushing","label":"Rushing the decision","detail":"A study of 107 brain-dead potential donors found that families who took longer than 48 hours to decide consented at 73%, compared with 55% among those who decided sooner. A slower decision was not a worse one — which is a strong argument for continuing to support a family rather than pressing them."}]},{"id":"recovery","label":"Recovery","summary":"Organs and tissues are surgically recovered.","detail":"Recovery is performed in an operating theatre by trained teams, ethically and respectfully. Anaesthesia is given to the deceased to reduce the remaining physiologic response to surgery, and the body is restored to its original state afterwards.","lossPoints":[{"id":"logistics","label":"Logistical and resource constraints","detail":"Theatre availability, staffing and transport all have to align within a narrow window."}]},{"id":"transplantation","label":"Transplantation","summary":"A recipient receives the transplant.","detail":"Long-term outcomes across the whole system improve when there is a larger pool of donors to allocate from — so every donation that is lost affects more than one person.","lossPoints":[]}]}', '2026-08-18T19:36:16.743+00:00', '2026-08-18T19:36:16.743+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('hale3zjqar550g0zslywqreq', 'fy5gk5lj0glyc8cimfs0iamm', 3, 'common-myths', 'The myths that cost lives', 'PRIMARY', NULL, 'MythFlip', '{"intro":"These are the beliefs that most often end a donation conversation. Turn each card over. You will meet all of them again in Module 4, where you practise responding.","cards":[{"id":"m1","myth":"Doctors won''t try as hard to save me if I''m a registered organ donor.","fact":"Two independent registered medical doctors are legally required to certify brain death, and neither of them may be part of the transplant team. The people caring for you and the people who would recover organs are deliberately kept separate — that separation is built into the law, not left to good intentions.","whyItPersists":"It taps a real and reasonable fear: that someone else''s interests could outweigh your own while you cannot speak for yourself."},{"id":"m2","myth":"I don''t want doctors cutting me up after I''m dead.","fact":"Recovery is a surgical procedure carried out in an operating theatre with the same care as any other operation, and the body is restored to its original state afterwards. Anaesthesia is given to the deceased to reduce the remaining physiologic response to the surgery.","whyItPersists":"This is rarely a factual objection. It is usually about dignity, and about protecting the body of someone loved."},{"id":"m3","myth":"My religion doesn''t allow organ donation.","fact":"Donation is possible from all communities and cultures in South Africa, and a faith representative or hospital chaplain can be included to support a family during these discussions. What is not appropriate is for anyone else to decide what a person''s faith permits on their behalf — including you.","whyItPersists":"Assumptions about a faith''s position are often inherited rather than checked. The honest response is to help someone find out, not to tell them what their faith says."},{"id":"m4","myth":"I''m too old or too sick to be a donor.","fact":"There is no age restriction for solid organ donation. Donors with conditions such as hypertension, diabetes or HIV may still be eligible if individual organs are assessed as transplantable. Module 8 covers this properly.","whyItPersists":"People rule themselves out privately, and never mention it — so nobody ever gets the chance to correct them."},{"id":"m5","myth":"Brain death isn''t really death — people wake up from comas.","fact":"There is no documented case of a person who met the preconditions and criteria for brain death ever subsequently regaining any brain function. A coma is a different state entirely, and recovery from a coma is possible. Module 6 separates the two carefully.","whyItPersists":"Coma and brain death look similar from a bedside, and are constantly conflated in film and news reporting."},{"id":"m6","myth":"Donation will cost my family money.","fact":"By law, once brain death has been declared and consent obtained, the donor''s medical aid, estate and next of kin are not responsible for any costs related to the donation.","whyItPersists":"Families facing a sudden death are often already frightened about money, and nobody has told them otherwise."}]}', '2026-08-18T19:36:16.744+00:00', '2026-08-18T19:36:16.744+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('kjird7kr8z3iiir6qly68x8l', 'fy5gk5lj0glyc8cimfs0iamm', 4, 'takeaways', 'Key takeaways', 'TAKEAWAYS', NULL, 'TakeawayList', '{"takeaways":[{"id":"t1","text":"Consent from next of kin is always required. Registering records your wishes; telling your family is what makes them actionable."},{"id":"t2","text":"The shortage is a pathway problem. A donation can be lost at any step between a potential donor and a recipient, and most of those steps are human rather than medical."},{"id":"t3","text":"Families often refuse because they never received factual information, or because they were approached at the wrong moment — not because they are against donation."},{"id":"t4","text":"There is no legal requirement to refer a potential donor. Referral happens because someone chooses to make it happen."},{"id":"t5","text":"Taking longer to decide does not mean refusing. Families who took more than 48 hours consented at a higher rate, not a lower one."},{"id":"t6","text":"Never assume someone''s culture, religion or background means donation shouldn''t be raised. That assumption takes the choice away before it is offered."}]}', '2026-08-18T19:36:16.744+00:00', '2026-08-18T19:36:16.744+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('uyf74baj8hh2jwev3dgcw0nh', 'fy5gk5lj0glyc8cimfs0iamm', 5, 'check', 'Check your understanding', 'CHECK', NULL, NULL, NULL, '2026-08-18T19:36:16.746+00:00', '2026-08-18T19:36:16.746+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('dssilxvn36e80qkvr8w00b7u', 'fy5gk5lj0glyc8cimfs0iamm', 6, 'study-guide', 'Study guide', 'STUDY_GUIDE', NULL, NULL, '{"summary":"Objective 2 of the Save7 study guide: know where and why we are losing organs.","sections":[{"id":"s1","heading":"Where and why organs are lost","bullets":["Lack of awareness and ignorance regarding the donation process","Fear-based understandings, cultural barriers, myths and misunderstandings within communities","Families automatically saying \"no\" because they never received factual information, or were approached at an inappropriate time","Registered donors not sharing their intentions with loved ones — consent from next of kin is always required","Misunderstanding brain death, such as believing a patient is still alive because a ventilator is providing oxygen","Concerns about body disfigurement during recovery surgery, despite the body being restored to its original state afterwards","In the clinical setting, failure to identify and refer a potential donor to a coordinator before death or before treatment is withdrawn"]},{"id":"s2","heading":"Referral triggers","body":"In any mechanically ventilated patient, a referral should be considered where a decision has been made to perform brain death tests; where there is a catastrophic brain injury with GCS 3–4 that cannot be explained by sedation, after a period of observation to allow prognostication; or where there is an intention to discuss withdrawal of life-sustaining treatment expected to result in circulatory death."},{"id":"s3","heading":"Decoupling","body":"The diagnosis of death and the request for donation are separated. The family is informed of the death and must understand and accept it before donation is raised, and the donation conversation is usually led by a transplant coordinator rather than the treating team."},{"id":"s4","heading":"Time is not the enemy","body":"Han et al. (2017) reviewed 107 brain-dead potential donors. The overall consent rate was 58%. Families deciding within 48 hours consented at 55%; those taking longer consented at 73%. Delay did not reduce consent, which supports continuing to counsel and support a family rather than pressing for an immediate answer."}]}', '2026-08-18T19:36:16.747+00:00', '2026-08-18T19:36:16.747+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('yrjyfwmx0o0wyyy909x2u4yr', 'fy5gk5lj0glyc8cimfs0iamm', 7, 'further-reading', 'Further reading', 'FURTHER_READING', NULL, 'ResourceList', '{"intro":"The evidence behind this module.","note":"Anything marked \"Opens here\" is the document Save7 supplied."}', '2026-08-18T19:36:16.748+00:00', '2026-08-18T19:36:16.748+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('xz9uei7td22skmfj8lrbmm9j', 'fy5gk5lj0glyc8cimfs0iamm', 8, 'complete', 'Complete module', 'COMPLETE', NULL, NULL, NULL, '2026-08-18T19:36:16.749+00:00', '2026-08-18T19:36:16.749+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('f2uww2uolnl06i3js1ohuud5', 'utdb2izuy72czxajhg7r2o23', 1, 'intro', 'Why this matters', 'INTRO', 'People do not usually ask advocates technical questions. They ask practical ones: *How does it actually work? Do you have to be dead? Can you donate while you''re alive? What''s the difference between organs and tissue?*
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('su3rfq2h4jiuacb97ppbedii', 'utdb2izuy72czxajhg7r2o23', 2, 'routes-to-donation', 'The routes to donation', 'PRIMARY', NULL, 'ComparePanel', '{"intro":"There are four routes to donation, and the differences matter. Compare them side by side.","columns":[{"id":"dbd","label":"After brain death","caption":"Donation after brain death (DBD)","emphasis":true},{"id":"dcd","label":"After circulatory death","caption":"Donation after circulatory death (DCD)"},{"id":"living","label":"Living donation","caption":"From a living donor"},{"id":"tissue","label":"Tissue donation","caption":"Tissue rather than solid organs"}],"rows":[{"id":"when","label":"When it happens","cells":{"dbd":"A patient on a mechanical ventilator is declared brain dead by two doctors.","dcd":"In palliative care settings, where treatment is withdrawn and death is imminent.","living":"While the donor is alive and well, by their own conscious decision.","tissue":"Irrespective of the manner of death — and even after the body has been moved to a mortuary."}},{"id":"what","label":"What can be donated","cells":{"dbd":"Heart, lungs, liver, kidneys and pancreas, plus tissue.","dcd":"Depends on the circumstances and how quickly recovery can follow death.","living":"A kidney, or a segment of liver.","tissue":"Corneas, bone and ligaments, skin, heart valves."}},{"id":"who-consents","label":"Who gives consent","cells":{"dbd":"Next of kin — spouse, parent, child, brother or sister — or a legal guardian.","dcd":"Next of kin or a legal guardian, as above.","living":"The donor themselves.","tissue":"Next of kin. A tissue donation coordinator is specifically trained to counsel next of kin and obtain consent for tissue-only donations."}},{"id":"setting","label":"Where it happens","cells":{"dbd":"Intensive care, then an operating theatre.","dcd":"Intensive care or a palliative setting, then an operating theatre.","living":"A planned operation, with the donor fully assessed beforehand.","tissue":"Wider range of settings, including after transfer to a mortuary."}}],"bottomLine":"Most deceased organ donation in South Africa follows one of two routes — after brain death, or after circulatory death — and both require consent from next of kin. Tissue donation is possible far more widely than most people assume."}', '2026-08-18T19:36:16.751+00:00', '2026-08-18T19:36:16.751+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('oxqluokahd757507etobkfep', 'utdb2izuy72czxajhg7r2o23', 3, 'takeaways', 'Key takeaways', 'TAKEAWAYS', NULL, 'TakeawayList', '{"takeaways":[{"id":"t1","text":"Deceased organ donation follows two routes: donation after brain death (DBD), and donation after circulatory death (DCD)."},{"id":"t2","text":"Living donation is possible for a kidney or a segment of liver, by the donor''s own conscious decision."},{"id":"t3","text":"Tissue donation is much broader: it can occur irrespective of the manner of death, and even after the body has been moved to a mortuary."},{"id":"t4","text":"Organ donation can only take place in a clinical setting. Early identification and good donor management are what make it possible."},{"id":"t5","text":"Every deceased donation route requires consent from next of kin — which is why the family conversation is never optional."}]}', '2026-08-18T19:36:16.751+00:00', '2026-08-18T19:36:16.751+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('k6g2ptbyms7x9hpbvpy34frj', 'utdb2izuy72czxajhg7r2o23', 4, 'check', 'Check your understanding', 'CHECK', NULL, NULL, NULL, '2026-08-18T19:36:16.752+00:00', '2026-08-18T19:36:16.752+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('k9e5hki7rsftzw9sldo1e0g2', 'utdb2izuy72czxajhg7r2o23', 5, 'study-guide', 'Study guide', 'STUDY_GUIDE', NULL, NULL, '{"summary":"The routes to donation, drawn from study guide Objective 5 and the SATCS Red File.","sections":[{"id":"s1","heading":"Donation after brain death (DBD)","body":"Occurs when a patient on a mechanical ventilator is declared brain dead by two doctors. Any patient declared brain dead — irreversible structural brain damage with total loss of brainstem function — is a potential organ donor."},{"id":"s2","heading":"Donation after circulatory death (DCD)","body":"Possible in palliative care settings where treatment is withdrawn and death is imminent."},{"id":"s3","heading":"Living donation","body":"Living organ donors are eligible if they make a conscious decision to donate a kidney or a segment of liver."},{"id":"s4","heading":"Tissue donation","body":"Tissue donation eligibility is broader than organ donation. It can occur irrespective of the manner of death, and even after the body has been moved to a mortuary. A tissue donation coordinator is specifically trained to counsel next of kin and obtain consent for tissue-only donations."}]}', '2026-08-18T19:36:16.752+00:00', '2026-08-18T19:36:16.752+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('rv80tocpmoqlm07n28qrs9kx', 'utdb2izuy72czxajhg7r2o23', 6, 'further-reading', 'Further reading', 'FURTHER_READING', NULL, 'ResourceList', '{"intro":"The SATCS Red File is the practical handbook behind this module.","note":"Anything marked \"Opens here\" is the document Save7 supplied."}', '2026-08-18T19:36:16.753+00:00', '2026-08-18T19:36:16.753+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('glnm5h0yw17rhpskzj2ovf08', 'utdb2izuy72czxajhg7r2o23', 7, 'complete', 'Complete module', 'COMPLETE', NULL, NULL, NULL, '2026-08-18T19:36:16.754+00:00', '2026-08-18T19:36:16.754+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('u4wm7rrbtrnyron0uyvk1nqf', 'q65o68xry6cy2gq2zuqz7aru', 1, 'intro', 'Why this matters', 'INTRO', 'The purpose of this module is **not** to teach you to win arguments.
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('mgq2winvdraq6qf6x52qwxcp', 'q65o68xry6cy2gq2zuqz7aru', 2, 'practise-responding', 'Practise responding', 'PRIMARY', NULL, 'ScenarioDialogue', '{"intro":"Four conversations you are likely to have. Read what the person says, think about what is really behind it, then choose how you would respond. There is often more than one reasonable answer.","scenarios":[{"id":"s1","speaker":"A friend","quote":"If I''m an organ donor, doctors won''t try as hard to save me.","whatsReallyHappening":"This is a fear about being abandoned when you are most vulnerable. It is not really a question about hospital policy.","reflectPrompt":"Before you look at the options — what would you actually say to a friend who said this?","options":[{"id":"o1","text":"That''s a myth. It''s completely untrue and there''s no evidence for it.","quality":"poor","feedback":"Accurate in substance, but it dismisses the fear rather than addressing it. Being told you are wrong rarely changes what you believe — and your friend will simply stop raising it with you."},{"id":"o2","text":"That''s a really common worry, and it makes sense — nobody wants to feel like a number. Can I tell you how the teams are actually kept separate?","quality":"strong","feedback":"This acknowledges the emotion first, normalises the worry so your friend does not feel foolish, and then asks permission before offering information. Permission matters: it turns a correction into a conversation. And the fact you are about to give is a strong one — two independent doctors must certify brain death, and neither may be part of the transplant team."},{"id":"o3","text":"Honestly, I had the same thought. What changed my mind was learning that the law requires two independent doctors to confirm death, and neither of them can be on the transplant team.","quality":"strong","feedback":"Sharing that you had the same doubt removes the hierarchy from the conversation, and you have given the specific safeguard rather than a general reassurance. This is the strongest single fact you have for this objection."},{"id":"o4","text":"Do you really think doctors would do that? They take an oath.","quality":"poor","feedback":"This makes your friend defend themselves, and appeals to professional character rather than explaining what actually prevents the conflict. The conversation is now an argument."}],"debrief":"Notice what the strong responses have in common: they name the emotion, they do not make the person feel stupid, and they offer a concrete safeguard rather than an assurance about good intentions. The separation of the two medical teams is written into the requirements for certifying death — it is not left to trust."},{"id":"s2","speaker":"A family member","quote":"I don''t want doctors cutting me up after I''m dead.","whatsReallyHappening":"Almost never a factual objection. This is about dignity, and about the body of someone loved being treated with respect.","reflectPrompt":"What is this person actually asking you to reassure them about?","options":[{"id":"o1","text":"Recovery is done in an operating theatre with the same care as any other surgery, and the body is restored to its original state afterwards. Would it help to know more about what actually happens?","quality":"strong","feedback":"Answers the real concern — dignity — with a specific fact, and offers detail without forcing it on them. That the body is restored afterwards is exactly the reassurance this objection is asking for."},{"id":"o2","text":"You won''t feel anything, you''ll be dead.","quality":"poor","feedback":"Technically responsive and emotionally tone-deaf. The objection was never about pain."},{"id":"o3","text":"I understand. Can I ask what worries you most about it — is it how you''d look, or something else?","quality":"strong","feedback":"A genuinely good move. You do not yet know whether this is about an open casket, religious washing rites, or something else entirely. Asking beats assuming."},{"id":"o4","text":"Think of it this way — you won''t need your organs any more, but seven other people will.","quality":"workable","feedback":"The reframe is memorable and true, and the number is right. But leading with it before acknowledging the concern can feel like being sold to. Try it after they feel heard, not instead."}],"debrief":"When an objection is about dignity, information alone will not resolve it — but the right information helps. Two specifics are worth knowing: the body is restored to its original state after recovery, and anaesthesia is given to the deceased to reduce the remaining physiologic response to the surgery. Both are the kind of concrete detail that reassures a family far more than a general promise of respect."},{"id":"s3","speaker":"Someone at a community event","quote":"My religion doesn''t allow organ donation.","whatsReallyHappening":"This may be accurate, or it may be an inherited assumption that has never been checked with their own faith leader. Either way, it is not yours to overrule.","reflectPrompt":"What is the line you should not cross here?","options":[{"id":"o1","text":"Actually most major religions do permit organ donation.","quality":"poor","feedback":"Even where broadly true, telling someone what their own faith permits is overstepping. You have made yourself an authority on their beliefs, and lost their trust."},{"id":"o2","text":"Thank you for telling me — that''s important, and I''d never want to push against it. Some people find it useful to ask their own faith leader directly, because positions vary. Would that be worth doing?","quality":"strong","feedback":"Respects their belief, stays inside your competence, and points them to the right authority — their faith leader, not you. In hospital, a faith representative or chaplain can be included to support a family for exactly this reason."},{"id":"o3","text":"That''s fine. Would you still be willing to talk to your family about what you''d want, so they aren''t left guessing?","quality":"strong","feedback":"Excellent. It accepts their position completely and still advances Save7''s actual goal: that families know each other''s wishes. Since consent from next of kin is always required, a clearly communicated ''no'' is genuinely useful — it spares a family an impossible guess."},{"id":"o4","text":"Which religion? I can look up what they say about it.","quality":"workable","feedback":"Well-intentioned, but it puts you in the position of interpreting their faith to them. Better to point them to someone inside their own tradition."}],"debrief":"Save7''s goal is not to convert anyone. Donation is possible from all communities and cultures in South Africa, and it should never be assumed that someone''s background means the subject shouldn''t be raised — but nor is it yours to settle. Someone who declines donation and has told their family is a success, not a failure."},{"id":"s4","speaker":"A colleague","quote":"I''d probably be turned down anyway — I''m in my sixties and I''m on medication for blood pressure.","whatsReallyHappening":"Self-exclusion. This person has quietly ruled themselves out and would never have raised it if you had not been talking about donation.","reflectPrompt":"Why is this one of the most valuable conversations you can have?","options":[{"id":"o1","text":"Please don''t rule yourself out — there''s actually no age restriction for solid organ donation, and conditions like high blood pressure don''t automatically exclude someone. It''s assessed organ by organ at the time.","quality":"strong","feedback":"Exactly right, and specific. There is no age limit for solid organ donation, and extended criteria donors with conditions such as hypertension, diabetes or HIV may still be eligible if individual organs are assessed as transplantable."},{"id":"o2","text":"Age and blood pressure don''t matter at all for donation.","quality":"poor","feedback":"Overcorrection. These factors are assessed rather than ignored, and claiming they are irrelevant damages your credibility when someone checks."},{"id":"o3","text":"That''s really common to assume. The decision isn''t yours or mine to make — it''s a medical assessment at the time, so the best thing is to register your wishes, tell your family, and let the doctors decide.","quality":"strong","feedback":"Puts the decision where it belongs and gives your colleague two concrete things to do."},{"id":"o4","text":"You could still donate your corneas, probably.","quality":"workable","feedback":"Tissue donation is a genuinely useful point, and cornea donors are generally accepted between 6 and 65 — so at 60-something this may well be accurate. But ''probably'' is speculation about a specific outcome; keep the framing general and let the assessment decide."}],"debrief":"Self-exclusion is invisible unless you start the conversation. The single most useful sentence here is that there is no age restriction for solid organ donation. Module 8 covers eligibility properly."}]}', '2026-08-18T19:36:16.756+00:00', '2026-08-18T19:36:16.756+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('a0796swrrw43vb48kf25un9d', 'q65o68xry6cy2gq2zuqz7aru', 3, 'takeaways', 'Key takeaways', 'TAKEAWAYS', NULL, 'TakeawayList', '{"takeaways":[{"id":"t1","text":"The goal is a conversation, not a conversion. Because consent from next of kin is always required, someone who decides against donation but tells their family has still done something valuable."},{"id":"t2","text":"Acknowledge the emotion before you correct the facts. People who feel dismissed stop listening."},{"id":"t3","text":"Ask permission before informing. It turns a correction into a conversation."},{"id":"t4","text":"Your strongest single fact: two independent doctors must certify brain death, and neither may be part of the transplant team."},{"id":"t5","text":"For dignity concerns: the body is restored to its original state after recovery, and anaesthesia is given to the deceased during it."},{"id":"t6","text":"Stay inside your competence. Never tell someone what their own religion permits — point them to their faith leader."},{"id":"t7","text":"\"I don''t know, let me find out\" protects your credibility and the next conversation."}]}', '2026-08-18T19:36:16.757+00:00', '2026-08-18T19:36:16.757+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('avksogc2n7hs0v96ej6i421l', 'q65o68xry6cy2gq2zuqz7aru', 4, 'check', 'Check your understanding', 'CHECK', NULL, NULL, NULL, '2026-08-18T19:36:16.757+00:00', '2026-08-18T19:36:16.757+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('e9o00dla7ojmymu6kc1pk493', 'q65o68xry6cy2gq2zuqz7aru', 5, 'study-guide', 'Study guide', 'STUDY_GUIDE', NULL, NULL, '{"summary":"Respectful conversation practice, and the facts that support it.","sections":[{"id":"s1","heading":"Why talking to your family matters","body":"Consent from next of kin is always required for donation to proceed. A registration your family has never heard about leaves them guessing at the worst possible moment. Evidence also suggests that discussing donation as part of end-of-life care helps families regardless of what they decide."},{"id":"s2","heading":"The four facts worth memorising","bullets":["Two independent doctors must certify brain death, and neither may be part of the transplant team","The body is restored to its original state after recovery surgery, and anaesthesia is given to the deceased during it","There is no age restriction for solid organ donation","The donor''s medical aid, estate and next of kin bear no costs for the donation once death is declared and consent obtained"]},{"id":"s3","heading":"How to approach the subject","body":"Acknowledge the emotion first. Ask permission before offering information. Do not overcorrect — claiming a factor is irrelevant is as inaccurate as claiming it disqualifies. Stay inside your competence, particularly on matters of faith. And say when you do not know."},{"id":"s4","heading":"What counts as success","body":"A family that has talked. Not a signature."}]}', '2026-08-18T19:36:16.758+00:00', '2026-08-18T19:36:16.758+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('pvh43t7vm1hp3qewkg9z1dlb', 'q65o68xry6cy2gq2zuqz7aru', 6, 'further-reading', 'Further reading', 'FURTHER_READING', NULL, 'ResourceList', '{"intro":"Save7''s own referral pathway, and the evidence on family decisions.","note":"Anything marked \"Opens here\" is the document Save7 supplied."}', '2026-08-18T19:36:16.759+00:00', '2026-08-18T19:36:16.759+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('za4dqtrd5x74a4mczx4nly5w', 'q65o68xry6cy2gq2zuqz7aru', 7, 'complete', 'Complete module', 'COMPLETE', NULL, NULL, NULL, '2026-08-18T19:36:16.759+00:00', '2026-08-18T19:36:16.759+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('e4b6xeo14e0d0vw7ai04qlx4', 'pn0m2s6lc0yqqeb8jvf9k3hn', 1, 'intro', 'Why this matters', 'INTRO', 'A donation is not an event. It is a chain of decisions and actions, running over hours, involving dozens of people, most of whom never meet each other and none of whom meet the recipient.
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('cklhw9ug8wuv4o5jugjervah', 'pn0m2s6lc0yqqeb8jvf9k3hn', 2, 'watch-the-journey', 'The Journey of a Gift', 'PRIMARY', NULL, 'ChapterVideo', '{"title":"The Journey of a Gift","src":"/media/journey-of-a-gift.mp4","durationSeconds":419,"awaitingAsset":false,"chapters":[{"id":"c1","label":"Why transplantation is needed","startSeconds":0,"summary":"One donor can save seven or more lives."},{"id":"c2","label":"Who is waiting for a transplant","startSeconds":0},{"id":"c3","label":"Identification and referral","startSeconds":0},{"id":"c4","label":"Determination of death","startSeconds":0},{"id":"c5","label":"The family approach and consent","startSeconds":0},{"id":"c6","label":"Donor management","startSeconds":0},{"id":"c7","label":"Recovery and allocation","startSeconds":0},{"id":"c8","label":"Transplantation","startSeconds":0},{"id":"c9","label":"A life after transplant","startSeconds":0}]}', '2026-08-18T19:36:16.763+00:00', '2026-08-18T19:36:16.763+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('c5vptptr4qegzpxayi0yq59n', 'pn0m2s6lc0yqqeb8jvf9k3hn', 3, 'the-full-journey', 'The full journey, step by step', 'PRIMARY', NULL, 'PathwayJourney', '{"intro":"The complete pathway, including the stages Module 2 did not cover: donor management, allocation, and what happens to the recipient afterwards.","showLossPoints":false,"steps":[{"id":"potential-donor","label":"Potential donor","summary":"Where the journey begins.","detail":"Organ donation can only happen in a clinical setting, almost always an intensive care unit with the patient on a mechanical ventilator. The most common routes to becoming a potential donor are traumatic head injury, stroke, or cerebral hypoxia following drowning or drug overdose."},{"id":"identification","label":"Identification","summary":"A clinical team recognises that donation may be possible.","detail":"Three triggers should prompt consideration in any mechanically ventilated patient: a decision has been made to perform brain death tests; there is a catastrophic brain injury with GCS 3–4 that cannot be explained by sedation, after a period of observation to allow prognostication; or there is an intention to discuss withdrawal of life-sustaining treatment expected to result in circulatory death.\n\nIdentification is the responsibility of the primary treatment team — the doctors and nurses already caring for the patient — as part of end-of-life care."},{"id":"referral","label":"Referral","summary":"A transplant or tissue donation coordinator is contacted.","detail":"The earliest possible discussion with a transplant coordinator is recommended. It lets the coordinator screen the patient, identify when donation is not feasible, and mobilise support — which minimises delay for the family. Importantly, this first discussion with the coordinator happens *before* end-of-life matters are raised with the family.\n\nThere is no legal requirement to refer. Referral happens because a clinician chooses to make it happen."},{"id":"determination-of-death","label":"Determination of death","summary":"Death is formally determined by two independent clinicians.","detail":"Two registered medical doctors must certify brain death. Neither may be involved with a transplantation team, and one must have been registered with the HPCSA for at least five years. Legal death is the time at which both doctors have confirmed brain death after completing all required clinical tests.\n\nModule 6 covers this in full."},{"id":"family-approach","label":"Family approach","summary":"The family is told about the death — and donation is not yet mentioned.","detail":"This is the step people find most surprising. The family is informed of the diagnosis and must fully understand and accept that their relative has died, **before organ donation is raised at all**. The treating team does not raise it; a transplant coordinator does, afterwards.\n\nThis deliberate separation is called **decoupling**. It exists so that a family is never asked to absorb a death and make a donation decision in the same breath — and so that the diagnosis is never heard as a request.\n\nAccepting the diagnosis takes patience and empathy from everyone involved. Families are given a specific period to process it, and support is not withdrawn immediately."},{"id":"consent","label":"Consent","summary":"Informed consent is sought from next of kin.","detail":"Consent must come from next of kin — spouse, parent, child, brother or sister — or from a legal guardian. There is an ethical obligation to give every family the chance to make a fully informed decision, and nobody should be excluded from being offered the option.\n\nIf the death was unnatural, additional consent is required from the state pathologist or district surgeon. Administrative permission to recover organs comes from the medical superintendent or hospital manager."},{"id":"donor-management","label":"Donor management","summary":"Active, skilled care that keeps the gift viable.","detail":"Care of the potential donor continues the support that began before death was declared, and actively manages the physiological deterioration that follows brain death. **Active management improves both the number of organs recovered and the outcomes for recipients** — this is not holding care, it is treatment with a purpose.\n\nIt includes gentle but effective ventilation and good pulmonary care, positioning the patient head-up at 30 to 45 degrees, and active temperature control, since the loss of hypothalamic function means the body can no longer regulate its own temperature. Fluid balance is kept deliberately restrictive, which improves lung viability without measurably harming kidney outcomes.\n\nFamilies may stay with their relative during this period, including up to the point of transfer to theatre."},{"id":"recovery","label":"Organ and tissue recovery","summary":"Surgery, performed with the same care and respect as any operation.","detail":"Recovery takes place in an operating theatre. Anaesthesia is given to the deceased in order to reduce the remaining physiological response to the surgery. Tissue is recovered by trained tissue recovery technicians, ethically and respectfully. The body is restored to its original state afterwards.\n\nFamilies commonly ask about the procedure itself, about anaesthesia, and about how their relative will be transferred to a funeral home. All three are reasonable questions with straightforward answers."},{"id":"allocation","label":"Allocation","summary":"Organs are matched to recipients — not handed out in order.","detail":"Allocation is a matching process. One concrete rule worth knowing: paediatric donors under 18 are preferentially allocated to paediatric recipients under 18.\n\nThere is also a system-level effect that is easy to miss. Long-term outcomes improve when there is a larger pool of donors to allocate from — so a donation that is lost does not only cost one recipient, it makes matching worse for everyone waiting."},{"id":"transplantation","label":"Transplantation","summary":"The transplant operation itself.","detail":"For the recipient this is the beginning rather than the end. Module 11 follows what happens next."},{"id":"life-after","label":"Life after transplant","summary":"A lifelong medical journey, not a completed repair.","detail":"A transplant restores something specific — sight, breathing, freedom from dialysis, years of active living — and it brings ongoing medication and monitoring with it. Describing both honestly is what makes an advocate credible."}]}', '2026-08-18T19:36:16.764+00:00', '2026-08-18T19:36:16.764+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('h51c10xdmnzo6ihcpdo821y7', 'pn0m2s6lc0yqqeb8jvf9k3hn', 4, 'takeaways', 'Key takeaways', 'TAKEAWAYS', NULL, 'TakeawayList', '{"takeaways":[{"id":"t1","text":"Donation is a coordinated chain of events over hours, not a single moment."},{"id":"t2","text":"The diagnosis conversation and the donation conversation are deliberately separated. This is called decoupling.","detail":"The family must understand and accept the death before donation is raised — and it is raised by a coordinator, not by the treating team."},{"id":"t3","text":"Donor management is active, skilled care after death has been determined. It measurably improves how many organs are recovered and how well recipients do."},{"id":"t4","text":"Recovery is surgery in an operating theatre. Anaesthesia is given to the deceased, and the body is restored to its original state afterwards."},{"id":"t5","text":"Allocation is matching, not queueing. Paediatric donors are preferentially allocated to paediatric recipients."},{"id":"t6","text":"A larger donor pool improves outcomes for everyone waiting — so a lost donation costs more than one transplant."}]}', '2026-08-18T19:36:16.765+00:00', '2026-08-18T19:36:16.765+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('rip41g62s8z403pe34s66fcb', 'pn0m2s6lc0yqqeb8jvf9k3hn', 5, 'check', 'Check your understanding', 'CHECK', NULL, NULL, NULL, '2026-08-18T19:36:16.766+00:00', '2026-08-18T19:36:16.766+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('f94y7gn7131m20erqdfytzi2', 'pn0m2s6lc0yqqeb8jvf9k3hn', 6, 'study-guide', 'Study guide', 'STUDY_GUIDE', NULL, NULL, '{"summary":"The donation pathway, end to end.","sections":[{"id":"s1","heading":"Identification and referral","body":"Three triggers should prompt consideration of donation in a mechanically ventilated patient: a decision to perform brain death tests; catastrophic brain injury with GCS 3–4 not explained by sedation, after observation for prognostication; or intended discussion of withdrawal of life-sustaining treatment expected to result in circulatory death. The earliest possible discussion with a transplant coordinator is recommended, and occurs before end-of-life matters are raised with the family."},{"id":"s2","heading":"Decoupling","body":"The family is informed of the death and must fully understand and accept it before donation is mentioned. The donation conversation is then initiated by a transplant coordinator. Families are given a defined period to process the diagnosis, and support is not withdrawn immediately."},{"id":"s3","heading":"Donor management","body":"Care continues the support begun before death was declared and actively manages the physiological deterioration that follows. Active management improves organ retrieval rates and transplant outcomes. Components include gentle effective ventilation with good pulmonary care, head-up positioning at 30–45 degrees, active temperature control following loss of hypothalamic function, and a restrictive fluid balance that improves lung viability without substantially affecting kidney outcomes."},{"id":"s4","heading":"Recovery","body":"Performed in an operating theatre. Anaesthesia is given to the deceased to decrease the remaining physiologic response to the procedures involved. Tissue is recovered by trained technicians. The body is restored to its original state."},{"id":"s5","heading":"Allocation","body":"A matching process. Paediatric donors under 18 are preferentially allocated to paediatric recipients under 18. Long-term outcomes are improved by having a large pool from which to allocate organs."}]}', '2026-08-18T19:36:16.766+00:00', '2026-08-18T19:36:16.766+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('tu81rqt2dahoxokesn4cefjz', 'pn0m2s6lc0yqqeb8jvf9k3hn', 7, 'further-reading', 'Further reading', 'FURTHER_READING', NULL, 'ResourceList', '{"intro":"The film, and the clinical manual behind the pathway.","note":"Anything marked \"Opens here\" is the document Save7 supplied."}', '2026-08-18T19:36:16.767+00:00', '2026-08-18T19:36:16.767+00:00');
