INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('cg6j42ahnjlk4vym7518zra7', 'dupcdrukzkq2wdzrh2ehhee8', 1, 'intro', 'Why this matters', 'INTRO', 'A family sitting beside a ventilated patient sees a warm body and a beating heart. Being told that person has died contradicts what their eyes are telling them.
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('sre850rodm5838sno0izm06e', 'dupcdrukzkq2wdzrh2ehhee8', 2, 'brain-death-vs-coma', 'Brain death is not a coma', 'PRIMARY', NULL, 'ComparePanel', '{"intro":"These three states are constantly confused, including in news reporting and film. Compare them carefully — this is the distinction you will be asked to explain most often.","columns":[{"id":"brain-death","label":"Brain death","caption":"Death by neurological criteria","emphasis":true},{"id":"coma","label":"Coma","caption":"Profound unconsciousness"},{"id":"vegetative","label":"Vegetative state","caption":"Wakefulness without awareness"}],"rows":[{"id":"what","label":"What it is","cells":{"brain-death":"Irreversible structural brain damage with total loss of brainstem function. The capacity for consciousness and the capacity to breathe are both irreversibly gone.","coma":"A state of profound unconsciousness. Brain function is impaired but not irreversibly and totally lost.","vegetative":"Cycles of wakefulness without awareness. Brainstem function is present."}},{"id":"brainstem","label":"Brainstem function","cells":{"brain-death":"Absent — this is what is tested for, and its total loss is the diagnosis.","coma":"Present.","vegetative":"Present."}},{"id":"breathing","label":"Capacity to breathe","cells":{"brain-death":"Irreversibly absent. This is directly tested by an apnoea test, and it is part of the definition of death.","coma":"Usually present, though breathing may need support.","vegetative":"Present."}},{"id":"recovery","label":"Possibility of recovery","cells":{"brain-death":"None. There is no documented case of anyone meeting the preconditions and criteria for brain death subsequently regaining any brain function.","coma":"Possible. People do recover from comas — which is exactly why the two must not be confused.","vegetative":"Limited and variable."}},{"id":"legal","label":"Legal status","cells":{"brain-death":"Dead. Legal death is the time at which two doctors have confirmed brain death after completing all required clinical tests.","coma":"Alive.","vegetative":"Alive."}},{"id":"heart","label":"Why the heart may still be beating","cells":{"brain-death":"A mechanical ventilator is supplying the oxygen the person can no longer obtain for themselves, so the heart continues to beat for a period after death.","coma":"The person is alive; the heart is beating for the ordinary reason.","vegetative":"The person is alive."}}],"bottomLine":"Brain death is death. A coma is not. Conflating them is the most common and most damaging misunderstanding in organ donation."}', '2026-08-18T19:36:16.770+00:00', '2026-08-18T19:36:16.770+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('is7wtrxppowtpx2mrp6d9nx3', 'dupcdrukzkq2wdzrh2ehhee8', 3, 'how-death-is-determined', 'How death is determined', 'PRIMARY', NULL, 'PathwayJourney', '{"intro":"Determination of death follows a defined process with deliberate safeguards. Open each step to see what it involves and why it exists.","showLossPoints":false,"steps":[{"id":"preconditions","label":"Preconditions","summary":"Establishing that the criteria can be applied at all.","detail":"There must be an established cause compatible with complete and irreversible loss of all brain function before testing begins. The patient must also be physiologically stable enough for the tests to mean anything: a temperature of at least 36°C, and a systolic blood pressure above 100 mmHg or a mean arterial pressure above 60 mmHg (with age-appropriate targets in children)."},{"id":"exclusions","label":"Excluding what could mimic it","summary":"Ruling out reversible causes before concluding anything.","detail":"The influence of drugs that depress the central nervous system must be excluded — for example by allowing five elimination half-lives to pass. Where severe alcohol intoxication may be the cause of the coma, the blood level should be shown to be below 80 mg/dL. Metabolic and endocrine disturbances are considered, though the guidelines stress that the most important factor is an unequivocal cause for the coma."},{"id":"observation","label":"Observation period","summary":"Time to be certain the injury is what it appears to be.","detail":"No single standard observation period is set — it is judged case by case. Two situations are specified: in anoxic brain injury the observation period should be 24 hours, and where therapeutic hypothermia has been used there should be 24 hours of normal temperature before examination. A cautious approach is advised in children, where confounders are common."},{"id":"clinical-assessment","label":"Clinical assessment","summary":"Structured examination of brainstem function.","detail":"It must be possible to examine the brainstem reflexes properly — at least one eye and one ear — and to perform an apnoea test safely.\n\nThe assessment of coma gives a sense of the rigour involved: deep pressure is applied to a nail bed on each limb and to the sternum. Noxious stimuli must produce no grimacing, no facial movement and no limb response other than reflexes mediated by the spinal cord. Any response that is not spinal in origin is incompatible with a diagnosis of brain death. Distinguishing the two requires expertise, and consultation is recommended where a response is unclear."},{"id":"apnoea-testing","label":"Apnoea testing","summary":"Testing directly for any capacity to breathe.","detail":"Because the irreversible loss of the capacity to breathe is part of the definition of death, it is tested directly rather than inferred. Where two doctors test separately there is no required delay between their examinations, but the guidelines strongly advocate that a single apnoea test be performed by both doctors together."},{"id":"ancillary","label":"Ancillary testing","summary":"For the situations where clinical testing is not possible.","detail":"An ancillary test is an additional investigation that assists the clinical diagnosis. It is used where clinical testing cannot be completed — for instance where apnoea testing is precluded by severe hypoxic respiratory failure or a high cervical cord injury — after confirming that brainstem reflexes are absent. It supplements the clinical diagnosis rather than replacing it."},{"id":"independent-assessment","label":"Two independent doctors","summary":"The safeguard that answers the most common public fear.","detail":"Two registered medical doctors must certify brain death. **Neither may be involved with a transplantation team.** One must have been registered with the HPCSA for at least five years, and may not be an intern. The two should ideally perform the testing together.\n\nLegal death is the time at which both doctors have confirmed brain death after completing all required clinical tests."},{"id":"children","label":"Children","summary":"The same standard, with one hard limit.","detail":"Determination of death in children is held to the same standard as in adults. It cannot be diagnosed in children below 36 weeks corrected gestation."},{"id":"accommodation","label":"Accommodation and somatic support","summary":"Two terms worth knowing, because they are humane ones.","detail":"**Somatic support** is the management of the body and organs, excluding the brain, after brain death has been confirmed.\n\n**Accommodation** is a period of somatic support provided specifically to allow a family time to process the diagnosis of death. The guidelines make recommendations on handling family requests for it — which tells you something about the spirit in which they were written."},{"id":"circulatory","label":"Circulatory determination of death","summary":"The other route by which death is determined.","detail":"Death may also be determined by circulatory criteria — the preferred term over older phrases like cardiac or cardiorespiratory death. This is the route relevant to donation after circulatory death, where treatment is withdrawn in a palliative setting and death is expected."}]}', '2026-08-18T19:36:16.770+00:00', '2026-08-18T19:36:16.770+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('prhiku3zhvv153opjxcvwdzt', 'dupcdrukzkq2wdzrh2ehhee8', 4, 'takeaways', 'Key takeaways', 'TAKEAWAYS', NULL, 'TakeawayList', '{"takeaways":[{"id":"t1","text":"Death is the irreversible loss of the capacity for consciousness together with the irreversible loss of the capacity to breathe. The definition does not mention the heart."},{"id":"t2","text":"Brain death is not a coma and not simply unconsciousness. Recovery from a coma is possible; there is no documented case of recovery of brain function after brain death was properly determined."},{"id":"t3","text":"The heart can keep beating because a ventilator is supplying oxygen the person can no longer obtain for themselves."},{"id":"t4","text":"Two registered doctors must certify brain death, neither of them involved with a transplant team, and one registered with the HPCSA for at least five years."},{"id":"t5","text":"The capacity to breathe is tested directly, by an apnoea test — it is not assumed."},{"id":"t6","text":"Legal death is the moment both doctors have confirmed brain death after completing all required tests."},{"id":"t7","text":"A family''s disbelief at the bedside is a reasonable human response, not ignorance. Accepting the diagnosis takes patience and empathy, and “accommodation” exists to give them time."}]}', '2026-08-18T19:36:16.773+00:00', '2026-08-18T19:36:16.773+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('mq99dd1u08r6npf4lal0qe72', 'dupcdrukzkq2wdzrh2ehhee8', 5, 'check', 'Check your understanding', 'CHECK', NULL, NULL, NULL, '2026-08-18T19:36:16.774+00:00', '2026-08-18T19:36:16.774+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('pop1qnf5sxis0yjll3z0cj2g', 'dupcdrukzkq2wdzrh2ehhee8', 6, 'study-guide', 'Study guide', 'STUDY_GUIDE', NULL, NULL, '{"summary":"Based on the South African Guidelines on the Determination of Death (Critical Care Society of Southern Africa, 2021).","sections":[{"id":"s1","heading":"The definition","body":"Death is the clinical point of irreversible loss of the capacity for consciousness and the irreversible loss of the capacity to breathe. Death is determined by either neurological or circulatory criteria, in accordance with accepted medical standards. A correctly performed clinical examination can determine the point of death with complete certainty; it is not necessary to wait for signs such as hypostasis, rigor mortis or decay in the healthcare setting."},{"id":"s2","heading":"Terminology","bullets":["Brain death, or death by neurological criteria — the preferred term, in place of brain-stem death","Circulatory death, or death by circulatory criteria — preferred over cardiac or cardiorespiratory death","Somatic support — management of the body and organs, excluding the brain, after brain death is confirmed","Accommodation — a period of somatic support to allow a family to process the diagnosis","Ancillary test — an additional test that assists the clinical diagnosis of brain death"]},{"id":"s3","heading":"Preconditions for brain death testing","bullets":["An established cause compatible with complete and irreversible loss of all brain function","Temperature of at least 36°C","Systolic blood pressure above 100 mmHg, or mean arterial pressure above 60 mmHg","Exclusion of CNS-depressing drugs, for example by allowing five elimination half-lives","Where severe alcohol intoxication is a concern, a blood level below 80 mg/dL","Ability to examine brainstem reflexes — at least one eye and one ear — and to perform apnoea testing safely"]},{"id":"s4","heading":"Observation periods","body":"No single standard period is set; it is judged case by case. In anoxic brain injury the observation period should be 24 hours. Where therapeutic hypothermia has been used, 24 hours of normothermia should pass before examination. A cautious approach is advised in paediatrics."},{"id":"s5","heading":"Who determines death","body":"Two registered medical doctors, neither involved with a transplantation team, one of whom must have been registered with the HPCSA for at least five years and may not be an intern. They should ideally test together, and a single apnoea test performed by both together is strongly advocated. Legal death is the time both have confirmed brain death after completing all required clinical tests."},{"id":"s6","heading":"Children","body":"Held to the same standard as adults, but brain death cannot be diagnosed in children below 36 weeks corrected gestation."}]}', '2026-08-18T19:36:16.774+00:00', '2026-08-18T19:36:16.774+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('hys44ll7rltdq8h4n3bfd9q5', 'dupcdrukzkq2wdzrh2ehhee8', 7, 'further-reading', 'Further reading', 'FURTHER_READING', NULL, 'ResourceList', '{"intro":"The authoritative source for this module, in both available versions.","note":"Cite the journal version in written material. Both open here."}', '2026-08-18T19:36:16.775+00:00', '2026-08-18T19:36:16.775+00:00');
