INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('x0h3dy2v4zzj19rcwa56yb9l', 'igmbm623gsgsydnrkwvvht7l', 1, 'intro', 'Why this matters', 'INTRO', 'Two things become obvious once you see the full team.
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('iayzynnunkiw2liucykvzzci', 'igmbm623gsgsydnrkwvvht7l', 2, 'meet-the-team', 'Meet the transplant team', 'PRIMARY', NULL, 'TeamRoster', '{"intro":"Select any role to see what that person or organisation actually does.","members":[{"id":"treating-team","role":"Primary treatment team","oneLiner":"Cares for the patient long before donation is considered — and identifies the possibility.","appearsAt":"Before and during identification","responsibilities":["Provides the critical care the patient is already receiving","Responsible for the initial identification of a potential donor, as part of end-of-life care","Makes the referral to a transplant coordinator","Counsels the family on prognosis, and later delivers the diagnosis of death — without raising donation at that point"]},{"id":"transplant-coordinator","role":"Transplant coordinator","oneLiner":"The central figure who coordinates the entire process.","appearsAt":"From referral through to recovery","responsibilities":["Performs donor assessments and screens for suitability","Oversees donor management","Coordinates the entire donation process","Leads the donation conversation with the family, after the death has been accepted"]},{"id":"tissue-coordinator","role":"Tissue donation coordinator","oneLiner":"Specifically trained to counsel families and obtain consent for tissue-only donation.","appearsAt":"Referral onwards","responsibilities":["Counsels next of kin about tissue donation","Obtains consent for tissue-only donations"]},{"id":"death-determining-doctors","role":"The two doctors who certify death","oneLiner":"Independent of the transplant team — a legal safeguard, not a courtesy.","appearsAt":"Determination of death","responsibilities":["Two registered medical doctors are legally required to certify brain death","Neither may be part of the transplant team","One must have been registered with the HPCSA for at least five years, and may not be an intern","Ideally perform the testing together, including a single shared apnoea test"]},{"id":"nurses","role":"Nurses","oneLiner":"Continuous care for the patient, and continuous presence for the family.","appearsAt":"Throughout","responsibilities":["Deliver the ongoing critical care the patient and then the donor requires","Part of the identification and referral responsibility of the treatment team","Often the team member a family speaks to most","A nursing sister is typically part of the team that meets with the family"]},{"id":"counsellors","role":"Trauma counsellor","oneLiner":"Supports the family through grief and decision-making.","appearsAt":"Family approach and after","responsibilities":["May form part of the team that approaches the family","Supports families through an acute bereavement","Note that routine grief counselling is generally not indicated — most bereaved people are resilient and grief is integrated with the support of family, friends and spiritual care. Counselling is valuable for complicated grief."]},{"id":"translators","role":"Translator","oneLiner":"Makes consent genuinely informed across a language barrier.","appearsAt":"Family approach and consent","responsibilities":["May form part of the team that approaches the family","Ensures the family understands the diagnosis and the decision they are being asked to make","Consent that is not understood is not informed consent — which makes this a safeguard, not a convenience"]},{"id":"faith-representatives","role":"Faith representative or hospital chaplain","oneLiner":"Supports families within their own religious tradition.","appearsAt":"Family approach and after","responsibilities":["May form part of the team that approaches the family","The responsible consultant and transplant coordinator may explore including a faith representative or hospital chaplain to support families during these discussions","Provides spiritual support, which is part of how most people actually integrate grief"]},{"id":"recovery-technicians","role":"Tissue recovery technicians","oneLiner":"Trained to recover tissue ethically and respectfully.","appearsAt":"Recovery","responsibilities":["Surgically recover tissues","Trained specifically to do so in an ethical and respectful manner"]},{"id":"odf","role":"Organ Donor Foundation (ODF)","oneLiner":"The national umbrella body for awareness and the donor database.","appearsAt":"Before the pathway begins","isOrganisation":true,"externalUrl":"https://odf.org.za","responsibilities":["Serves as the national umbrella body for promoting awareness of organ donation","Manages the national donor database","The right place to send anyone who wants to register, or who asks for current national figures"]},{"id":"satcs","role":"South African Transplant Coordinators Society (SATCS)","oneLiner":"Represents, unites and supports transplant coordinators nationally.","isOrganisation":true,"responsibilities":["Exists to represent, unite and support all transplant coordinators in the country","Publishes the Organ and Tissue Donation Reference File — the Red File — used throughout this course"]},{"id":"save7","role":"Save7","oneLiner":"Awareness, education and donor support — including the LifePod.","isOrganisation":true,"externalUrl":"https://save7.org","responsibilities":["Raises public awareness and enables donor registration","Runs the LifePod, a dedicated support unit for consented organ donors","Produced this course, the Journey of a Gift film, and the 7 Lives in 7 Steps referral pathway"]}]}', '2026-08-18T19:36:16.777+00:00', '2026-08-18T19:36:16.777+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('lsmd107aznrkegzulgcznbjx', 'igmbm623gsgsydnrkwvvht7l', 3, 'takeaways', 'Key takeaways', 'TAKEAWAYS', NULL, 'TakeawayList', '{"takeaways":[{"id":"t1","text":"The transplant coordinator is the central figure: donor assessment, donor management, and coordination of the whole process."},{"id":"t2","text":"The two doctors who certify brain death are independent of the transplant team by law. This is the structural answer to the most common public fear."},{"id":"t3","text":"The team that meets a family typically includes a doctor, a nursing sister and a transplant coordinator, and may include a trauma counsellor, a translator or a faith representative."},{"id":"t4","text":"Translators protect the validity of consent, not just the family''s comfort — consent that is not understood is not informed consent."},{"id":"t5","text":"Identification and referral belong to the primary treatment team, as part of ordinary end-of-life care."},{"id":"t6","text":"Two organisations hold the national picture together: the ODF for awareness and the donor database, and SATCS for the coordinators themselves."}]}', '2026-08-18T19:36:16.778+00:00', '2026-08-18T19:36:16.778+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('ysu04qmaqnsa3gus72gm1nyw', 'igmbm623gsgsydnrkwvvht7l', 4, 'check', 'Check your understanding', 'CHECK', NULL, NULL, NULL, '2026-08-18T19:36:16.778+00:00', '2026-08-18T19:36:16.778+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('d40tie5q49cllmdsyqtjj5wc', 'igmbm623gsgsydnrkwvvht7l', 5, 'study-guide', 'Study guide', 'STUDY_GUIDE', NULL, NULL, '{"summary":"Objective 3 of the Save7 study guide: know the team involved in transplant.","sections":[{"id":"s1","heading":"Clinical and coordinating roles","bullets":["The transplant coordinator performs donor assessments, oversees management, and coordinates the entire process","A tissue donation coordinator is specifically trained to counsel next of kin and obtain consent for tissue-only donations","Two independent registered medical doctors, who are not part of the transplant team, are legally required to certify brain death","Trained tissue recovery technicians surgically recover tissues in an ethical and respectful manner","The primary treatment team — physicians and nurses — is responsible for the initial identification and referral of potential donors as part of end-of-life care"]},{"id":"s2","heading":"The team that approaches the family","body":"Often includes a doctor, a nursing sister and a transplant coordinator, and may include a trauma counsellor, a translator, or a faith representative."},{"id":"s3","heading":"The organisations","bullets":["The Organ Donor Foundation (ODF) is the national umbrella body for promoting awareness and managing the donor database","The South African Transplant Coordinators Society (SATCS) represents, unites and supports all transplant coordinators in the country"]}]}', '2026-08-18T19:36:16.779+00:00', '2026-08-18T19:36:16.779+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('lh7f41xcmuc6bl8jqepty37e', 'igmbm623gsgsydnrkwvvht7l', 6, 'further-reading', 'Further reading', 'FURTHER_READING', NULL, 'ResourceList', '{"intro":"Where to find the roles described in full.","note":"Anything marked \"Opens here\" is the document Save7 supplied."}', '2026-08-18T19:36:16.779+00:00', '2026-08-18T19:36:16.779+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('snmac6fovwjamuvn6d2dm4jm', 'igmbm623gsgsydnrkwvvht7l', 7, 'complete', 'Complete module', 'COMPLETE', NULL, NULL, NULL, '2026-08-18T19:36:16.780+00:00', '2026-08-18T19:36:16.780+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('vh20aal3r259o9exazze8wpz', 'fdyb9a50o4n2x8pqvks17blp', 1, 'intro', 'Why this matters', 'INTRO', 'There is a strong temptation to hand advocates a simple checklist of who can and cannot donate. Mostly that is a bad idea: confident exclusion rules are frequently wrong, and a confident wrong answer from an advocate can permanently remove a potential donor.
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('c1l4q58ugfroark7v0m4f4m4', 'fdyb9a50o4n2x8pqvks17blp', 2, 'does-this-rule-me-out', '"Does this rule me out?"', 'PRIMARY', NULL, 'EligibilityMatrix', '{"intro":"The factors people most often rule themselves out for. Open each one to see the assumption people arrive with, and how the question is actually answered.","bottomLine":"There is no age restriction for solid organ donation, and conditions like hypertension, diabetes and HIV do not automatically exclude someone. Suitability is assessed organ by organ, at the time. Nobody should be excluded from being offered the option to donate.","factors":[{"id":"age-solid-organ","factor":"Age — solid organs","commonAssumption":"\"I''m too old to be a donor.\"","reality":"There is no age restriction for solid organ donation. This is one of the few places where the answer really is that clear.","verdict":"rarely-absolute"},{"id":"hypertension","factor":"High blood pressure","commonAssumption":"\"I''m on medication for hypertension, so I''d be turned down.\"","reality":"Donors with comorbidities such as hypertension are described as extended criteria donors, and may still be eligible if individual organs are assessed as transplantable. It is an assessment, not an exclusion.","verdict":"assessed-individually"},{"id":"diabetes","factor":"Diabetes","commonAssumption":"\"Diabetics can''t donate.\"","reality":"Diabetes is one of the comorbidities explicitly named in the extended criteria donor category. Individual organs are assessed for transplantability.","verdict":"assessed-individually"},{"id":"hiv","factor":"HIV","commonAssumption":"\"Being HIV positive automatically excludes donation.\"","reality":"HIV is named alongside hypertension and diabetes as a condition under which a donor may still be eligible if individual organs are assessed as transplantable. This surprises most people, including many clinicians.","verdict":"assessed-individually"},{"id":"cause-of-death","factor":"How the person died","commonAssumption":"\"You can only donate after a car accident.\"","reality":"Common routes to brain death include traumatic head injury, stroke, and cerebral hypoxia following drowning or drug overdose. For tissue donation, eligibility does not depend on the manner of death at all.","verdict":"depends"},{"id":"tissue-broadly","factor":"Tissue donation generally","commonAssumption":"\"If I can''t donate organs, I can''t donate anything.\"","reality":"Tissue donation eligibility is broader than organ donation. It can occur irrespective of the manner of death, and even after the body has been moved to a mortuary.","verdict":"rarely-absolute"},{"id":"corneas","factor":"Corneas","commonAssumption":"\"My eyesight is terrible, so my corneas are no use.\"","reality":"Cornea donors are generally between 6 and 65 years old. Poor eyesight and cataracts do not disqualify a donor.","verdict":"stated-criteria"},{"id":"skin-and-bone","factor":"Skin and bone","commonAssumption":"\"Surely there''s an age limit.\"","reality":"Skin and bone donors are typically healthy individuals between the ages of 16 and 80, without infectious diseases or cancer.","verdict":"stated-criteria"},{"id":"heart-valves","factor":"Heart valves","commonAssumption":"\"Only adults can donate heart valves.\"","reality":"Heart valve donors are eligible from the age of 6 months up to 55 years.","verdict":"stated-criteria"},{"id":"organ-specific","factor":"Organ-by-organ assessment","commonAssumption":"\"It''s all or nothing — either you can donate everything or nothing.\"","reality":"It is not all or nothing. Extended criteria donors may be eligible where individual organs are assessed as transplantable, so being unsuitable for one donation does not mean being unsuitable for all.","verdict":"depends"}]}', '2026-08-18T19:36:16.783+00:00', '2026-08-18T19:36:16.783+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('ni41ivcp4isxzzmvhi9usjeu', 'fdyb9a50o4n2x8pqvks17blp', 3, 'who-is-a-potential-donor', 'Who becomes a potential donor', 'PRIMARY', NULL, 'ComparePanel', '{"intro":"Eligibility depends partly on the route to donation. The same person can be eligible by one route and not another.","columns":[{"id":"dbd","label":"After brain death","emphasis":true},{"id":"dcd","label":"After circulatory death"},{"id":"living","label":"Living donation"},{"id":"tissue","label":"Tissue donation"}],"rows":[{"id":"who","label":"Who may be considered","cells":{"dbd":"Any patient declared brain dead — irreversible structural brain damage with total loss of brainstem function — on a mechanical ventilator.","dcd":"Patients in palliative care settings where treatment is withdrawn and death is imminent.","living":"Someone making a conscious decision to donate, who is assessed as fit to do so.","tissue":"Far wider. Eligibility does not depend on the manner of death, and donation is possible even after transfer to a mortuary."}},{"id":"typical-cause","label":"Typical route there","cells":{"dbd":"Traumatic head injury, stroke, or cerebral hypoxia from drowning or drug overdose.","dcd":"A decision to withdraw life-sustaining treatment, where death is expected to follow.","living":"A planned decision, often to help a relative.","tissue":"Any manner of death."}},{"id":"age","label":"Age","cells":{"dbd":"No age restriction for solid organ donation.","dcd":"No age restriction for solid organ donation.","living":"Assessed as part of the donor work-up.","tissue":"Stated ranges apply: corneas generally 6–65; skin and bone typically 16–80; heart valves 6 months to 55 years."}},{"id":"comorbidities","label":"Comorbidities","cells":{"dbd":"Extended criteria donors with hypertension, diabetes or HIV may still be eligible if individual organs are assessed as transplantable.","dcd":"Assessed individually, as above.","living":"Assessed thoroughly before any donation proceeds.","tissue":"Skin and bone donors are typically without infectious disease or cancer."}}],"bottomLine":"Different routes have different requirements, and none of them can be assessed in advance by a member of the public — or by the potential donor themselves."}', '2026-08-18T19:36:16.784+00:00', '2026-08-18T19:36:16.784+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('oskvyrt1c8v1zeu2bp4qin42', 'fdyb9a50o4n2x8pqvks17blp', 4, 'takeaways', 'Key takeaways', 'TAKEAWAYS', NULL, 'TakeawayList', '{"takeaways":[{"id":"t1","text":"There is no age restriction for solid organ donation."},{"id":"t2","text":"Extended criteria donors with hypertension, diabetes or HIV may still be eligible if individual organs are assessed as transplantable."},{"id":"t3","text":"Tissue donation is broader than organ donation: irrespective of the manner of death, and possible even after the body has been moved to a mortuary."},{"id":"t4","text":"Tissue does have stated ranges — corneas generally 6–65, skin and bone typically 16–80, heart valves 6 months to 55 years."},{"id":"t5","text":"Poor eyesight and cataracts do not disqualify a cornea donor."},{"id":"t6","text":"Self-exclusion is a real and invisible loss point. Do not rule anyone out on their behalf, and do not overcorrect by claiming a condition is irrelevant."},{"id":"t7","text":"Nobody should be excluded from being offered the option to donate."}]}', '2026-08-18T19:36:16.784+00:00', '2026-08-18T19:36:16.784+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('bokqrubp2upl4axb286s627f', 'fdyb9a50o4n2x8pqvks17blp', 5, 'check', 'Check your understanding', 'CHECK', NULL, NULL, NULL, '2026-08-18T19:36:16.785+00:00', '2026-08-18T19:36:16.785+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('laqf6g78mfmf0hsz6eqwqaoz', 'fdyb9a50o4n2x8pqvks17blp', 6, 'study-guide', 'Study guide', 'STUDY_GUIDE', NULL, NULL, '{"summary":"Objective 5 of the Save7 study guide: know when someone is eligible for organ donation.","sections":[{"id":"s1","heading":"Who is a potential organ donor","body":"Any patient who is declared brain dead — irreversible structural brain damage with total loss of brainstem function — is a potential organ donor. Common causes of eligibility through brain death include traumatic head injuries, strokes, and cerebral hypoxia from drowning or drug overdose."},{"id":"s2","heading":"By route","bullets":["Donation after brain death (DBD) — a patient on a mechanical ventilator declared brain dead by two doctors","Donation after circulatory death (DCD) — possible in palliative care settings where treatment is withdrawn and death is imminent","Living donation — a conscious decision to donate a kidney or a liver segment","Tissue donation — irrespective of the manner of death, and even after transfer to a mortuary"]},{"id":"s3","heading":"Age and comorbidities","bullets":["There is no age restriction for solid organ donation","Extended criteria donors with comorbidities such as hypertension, diabetes or HIV may still be eligible if individual organs are assessed as transplantable"]},{"id":"s4","heading":"Tissue-specific criteria","bullets":["Cornea donors are generally between 6 and 65 years old; poor eyesight and cataracts do not disqualify them","Skin and bone donors are typically healthy individuals between 16 and 80, without infectious diseases or cancer","Heart valve donors are eligible from 6 months up to 55 years"]}]}', '2026-08-18T19:36:16.785+00:00', '2026-08-18T19:36:16.785+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('ty2espo71kmdd6qbq12hoo94', 'fdyb9a50o4n2x8pqvks17blp', 7, 'further-reading', 'Further reading', 'FURTHER_READING', NULL, 'ResourceList', '{"intro":"Where the eligibility criteria come from.","note":"Current guidance matters here — older sources carry exclusion criteria that no longer reflect practice."}', '2026-08-18T19:36:16.786+00:00', '2026-08-18T19:36:16.786+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('cbrn2mhuu48we7ma7fzxmsv4', 'fdyb9a50o4n2x8pqvks17blp', 8, 'complete', 'Complete module', 'COMPLETE', NULL, NULL, NULL, '2026-08-18T19:36:16.786+00:00', '2026-08-18T19:36:16.786+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('dcyfytnjq4xbivubtccrlmqe', 'tnvu4480yubmdf54pi8nhoie', 1, 'intro', 'Why this matters', 'INTRO', 'Three kinds of statement get tangled together whenever donation is discussed, and an advocate who cannot separate them will eventually mislead someone:
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('wjmtow0qy7e6ig75nex1uj2u', 'tnvu4480yubmdf54pi8nhoie', 2, 'legal-framework', 'The legal framework', 'PRIMARY', NULL, 'PathwayJourney', '{"intro":"The legal touchpoints in a donation, in roughly the order they arise.","showLossPoints":false,"steps":[{"id":"national-health-act","label":"The National Health Act","summary":"Chapter 8 of Act No. 61 of 2003.","detail":"The primary legislation governing organ and tissue donation and transplantation in South Africa is Chapter 8 of the National Health Act No. 61 of 2003. The donation process itself is strictly regulated."},{"id":"referral","label":"Referral — no legal duty","summary":"The one place where the law is silent, and it matters.","detail":"There is **no legal requirement** for the referral of a potential donor. The process that follows a referral is tightly regulated, but whether a referral happens at all depends on a clinician choosing to make it.\n\nThis is why clinical awareness matters so much. A missed referral breaks no law, and still costs a life."},{"id":"brain-death-certification","label":"Brain-death certification","summary":"Who may certify, and what qualifies them.","detail":"Certification of brain death must be completed by **two registered medical doctors**, one of whom must have been registered with the HPCSA for **at least five years**. Neither may be part of the transplant team, and neither may be an intern.\n\n**Legal death** is defined as the time at which both doctors have confirmed brain death, after completing all required clinical tests."},{"id":"consent","label":"Informed consent","summary":"Who may give it.","detail":"Informed consent must be obtained from the **next of kin** — a spouse, parent, child, brother or sister — or from a **legal guardian**.\n\nHPCSA guidance on informed consent governs the standard: sufficient information, room for questions, and a genuinely voluntary decision. Consent that was not understood is not informed consent, which is why translators are treated as a safeguard rather than a convenience."},{"id":"unnatural-deaths","label":"Unnatural deaths","summary":"An additional authority enters the process.","detail":"Where death is due to unnatural causes — a motor vehicle accident, for example — **additional consent is required from the state pathologist or district surgeon**.\n\nIn practice this also brings paperwork and a forensic authority into the timeline. Save7''s own referral pathway records that an unnatural death requires an FPS 100 form to be completed, with the forensic pathology service contacted to determine which organs may be recovered, and a SAPS liaison available where there is uncertainty. A natural death instead requires the DHA1663-B1163 form, which must accompany the donor."},{"id":"hospital-authorisation","label":"Hospital authorisation","summary":"Institutional permission to recover.","detail":"Administrative permission to recover organs must be granted by the **medical superintendent or hospital manager** of the facility where the recovery occurs."},{"id":"costs","label":"Costs","summary":"The reassurance families most need, and it is a legal one.","detail":"**By law, the donor''s medical aid, estate and next of kin are not responsible for any costs related to the donation**, once brain death has been declared and consent has been obtained.\n\nThis is worth knowing precisely, because a frightened family asking about money is asking a legal question and deserves a legal answer."},{"id":"palliative-context","label":"Withdrawal of treatment","summary":"The ethical framework behind donation after circulatory death.","detail":"Donation after circulatory death arises in palliative settings where life-sustaining treatment is withdrawn. HPCSA ethical guidance on palliative care covers the withholding and withdrawal of treatment, patient autonomy, and advance care planning — the decision to withdraw is made on its own merits, entirely separately from any question of donation."}]}', '2026-08-18T19:36:16.790+00:00', '2026-08-18T19:36:16.790+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('o1pj90v0777e49p9ykfqcajd', 'tnvu4480yubmdf54pi8nhoie', 3, 'takeaways', 'Key takeaways', 'TAKEAWAYS', NULL, 'TakeawayList', '{"takeaways":[{"id":"t1","text":"Chapter 8 of the National Health Act No. 61 of 2003 is the governing legislation."},{"id":"t2","text":"There is no legal requirement to refer a potential donor — but the donation process itself is strictly regulated."},{"id":"t3","text":"Two registered doctors must certify brain death, one registered with the HPCSA for at least five years, neither on the transplant team, neither an intern."},{"id":"t4","text":"Legal death is the time both doctors confirmed brain death after completing all required clinical tests."},{"id":"t5","text":"Consent comes from next of kin — spouse, parent, child, brother or sister — or a legal guardian."},{"id":"t6","text":"Unnatural death requires additional consent from the state pathologist or district surgeon. Hospital authorisation comes from the medical superintendent or hospital manager."},{"id":"t7","text":"By law the donor''s medical aid, estate and next of kin bear no costs of the donation once death is declared and consent obtained."},{"id":"t8","text":"Separate educational explanation, legal requirement and clinical guidance whenever you speak — and refer what you cannot answer confidently."}]}', '2026-08-18T19:36:16.791+00:00', '2026-08-18T19:36:16.791+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('yt598w28t3gfxihkdj16r5zp', 'tnvu4480yubmdf54pi8nhoie', 4, 'check', 'Check your understanding', 'CHECK', NULL, NULL, NULL, '2026-08-18T19:36:16.792+00:00', '2026-08-18T19:36:16.792+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('uaprc0560a3dm8nsrfek9rku', 'tnvu4480yubmdf54pi8nhoie', 5, 'study-guide', 'Study guide', 'STUDY_GUIDE', NULL, NULL, '{"summary":"Objective 4 of the Save7 study guide: understand the basic legislation surrounding organ donation.","sections":[{"id":"s1","heading":"The legislation","bullets":["The primary legislation is Chapter 8 of the National Health Act No. 61 of 2003","There is no legal requirement for the referral of a potential donor, but the donation process itself is strictly regulated"]},{"id":"s2","heading":"Certification of death","bullets":["Two registered medical doctors must certify brain death","One must have been registered with the HPCSA for at least five years","Legal death is the time when both doctors have confirmed brain death after completing all required clinical tests"]},{"id":"s3","heading":"Consent and authorisation","bullets":["Informed consent must be obtained from next of kin — spouse, parent, child, brother or sister — or a legal guardian","For deaths due to unnatural causes, additional consent is required from the state pathologist or district surgeon","Administrative permission to recover organs must be granted by the medical superintendent or hospital manager where the recovery occurs"]},{"id":"s4","heading":"Costs","body":"By law, the donor''s medical aid, estate and next of kin are not responsible for any costs related to the donation after brain death has been declared and consent obtained."},{"id":"s5","heading":"Before Save7 publishes","body":"These provisions are transcribed from Save7''s study guide. Legislation is amended, and the wording above should be checked against the current consolidated text of the National Health Act, with a legal review of this module, before the course is published.","pendingReview":true}]}', '2026-08-18T19:36:16.792+00:00', '2026-08-18T19:36:16.792+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('wi1hltcasyopu7jfs07zepve', 'tnvu4480yubmdf54pi8nhoie', 6, 'further-reading', 'Further reading', 'FURTHER_READING', NULL, 'ResourceList', '{"intro":"The statute and the professional guidance that sits alongside it.","note":"Save7 should add a link to the current consolidated text of the Act."}', '2026-08-18T19:36:16.793+00:00', '2026-08-18T19:36:16.793+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('k69vkt5e2melvvtlu254uaup', 'tnvu4480yubmdf54pi8nhoie', 7, 'complete', 'Complete module', 'COMPLETE', NULL, NULL, NULL, '2026-08-18T19:36:16.794+00:00', '2026-08-18T19:36:16.794+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('i4wubczyf9g8f2qabwkz7sfk', 'gkh2ea7yygxftemfrwmx9nac', 1, 'intro', 'Why this matters', 'INTRO', 'Candidate selection is genuinely hard, genuinely contested, and genuinely changing. Mancini and Lietz put it plainly: *patients with comorbidities who in the past would not be suitable transplantation candidates are now often considered for transplantation.*
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('icqvfnp4hcz24g51b73c1jw8', 'gkh2ea7yygxftemfrwmx9nac', 2, 'heart-transplantation', 'Heart transplantation', 'PRIMARY', NULL, 'EligibilityMatrix', '{"intro":"Heart transplant candidacy, as an in-depth example of how recipient assessment works. Note how few factors are truly absolute — and remember these are criteria for *receiving* a heart, not for donating one.","bottomLine":"Most contraindications to heart transplantation are relative, not absolute, and have shifted as evidence has changed. Candidate selection is a specialist multidisciplinary judgement — which is exactly why an advocate should not attempt it.","factors":[{"id":"indications","factor":"Who is considered","commonAssumption":"\"A transplant is offered whenever the heart is failing.\"","reality":"Heart failure is progressive, and only a minority reach the point where transplantation is considered — around 5% to 10% of heart failure patients have advanced, stage D disease. In the most advanced phase, transplantation has been the only means of improving both quality of life and survival.","verdict":"depends"},{"id":"life-expectancy","factor":"Other systemic illness","commonAssumption":"\"Any other serious illness rules you out.\"","reality":"An absolute contraindication is a systemic illness with a life expectancy under two years *despite* a transplant — the question is whether the transplant would actually change the outcome.","verdict":"depends"},{"id":"malignancy","factor":"Cancer history","commonAssumption":"\"Any history of cancer is an absolute bar.\"","reality":"Active or recent solid organ or blood malignancy within five years is an absolute contraindication. A history beyond that window is assessed rather than assumed.","verdict":"depends"},{"id":"hiv","factor":"HIV","commonAssumption":"\"HIV is an absolute contraindication.\"","reality":"The absolute contraindication is stated specifically as AIDS with frequent opportunistic infections — not HIV as such. This is a good example of a criterion that is far narrower than the public assumption.","verdict":"rarely-absolute"},{"id":"renal","factor":"Renal dysfunction","commonAssumption":"\"Kidney problems make a heart transplant impossible.\"","reality":"Irreversible renal dysfunction is an absolute contraindication only for patients being considered for a heart transplant alone. Creatinine above 2.5 mg/dL, or creatinine clearance below 25 mL/min, is listed among the relative contraindications.","verdict":"depends"},{"id":"obesity","factor":"Body mass index","commonAssumption":"\"Weight is an automatic exclusion.\"","reality":"Morbid obesity — BMI above 35 — and cachexia, BMI below 18, are both listed as relative contraindications. Relative means weighed, not decided.","verdict":"rarely-absolute"},{"id":"pulmonary","factor":"Lung function","commonAssumption":"\"Only the heart matters for a heart transplant.\"","reality":"Significant obstructive pulmonary disease and fixed pulmonary hypertension appear among the absolute contraindications; severe pulmonary dysfunction with FEV1 below 40% of normal is relative. The rest of the body has to be able to support the new heart.","verdict":"depends"},{"id":"substance-use","factor":"Smoking, alcohol and drug use","commonAssumption":"\"They just won''t give organs to people who smoke.\"","reality":"Drug, tobacco or alcohol abuse within six months is a relative contraindication — a window, not a permanent bar. Psychosocial stability is assessed for the same reason: a transplant requires lifelong medication adherence.","verdict":"rarely-absolute"},{"id":"mcs","factor":"Mechanical circulatory support","commonAssumption":"\"It''s transplant or nothing.\"","reality":"Mechanical circulatory support means transplantation is not always the only option in advanced heart failure. It can bridge a patient toward transplantation, or serve as a destination therapy in its own right.","verdict":"depends"}]}', '2026-08-18T19:36:16.796+00:00', '2026-08-18T19:36:16.796+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('h41xtmxipz39z0chtxw9kbuc', 'gkh2ea7yygxftemfrwmx9nac', 3, 'other-solid-organs', 'Lung, kidney, liver and pancreas', 'PRIMARY', NULL, 'ComparePanel', '{"intro":"How recipient candidacy differs across organs. The lung column draws on the ISHLT consensus document, which is unusually direct about age.","columns":[{"id":"lung","label":"Lung","emphasis":true},{"id":"kidney","label":"Kidney"},{"id":"liver","label":"Liver"},{"id":"pancreas","label":"Pancreas"}],"rows":[{"id":"indications","label":"Main indications","cells":{"lung":"Advanced lung disease such as COPD or cystic fibrosis, with a risk of death exceeding 50% over two years.","kidney":"End-stage renal disease (CKD 5).","liver":"Hepatocellular carcinoma, decompensated cirrhosis, fulminant hepatic failure.","pancreas":"Diabetes no longer manageable with insulin, often alongside kidney failure."}},{"id":"age","label":"Age","cells":{"lung":"There is no endorsement of an upper age limit as an absolute contraindication, and age by itself is not considered a contraindication. Age over 65 with low physiologic reserve is relative; adults over 75 are unlikely to be candidates in most cases.","kidney":"Assessed as part of overall candidacy.","liver":"Assessed as part of overall candidacy.","pancreas":"Assessed as part of overall candidacy."},"pendingReview":true},{"id":"malignancy","label":"Cancer history","cells":{"lung":"A recent history of malignancy is an absolute contraindication. A 2-year disease-free interval may be reasonable where recurrence risk is low; 5 years is prudent in most cases, particularly for haematologic malignancy, sarcoma, melanoma, or cancers of the breast, bladder or kidney.","kidney":"Assessed individually.","liver":"Hepatocellular carcinoma can itself be an indication, within defined limits.","pancreas":"Assessed individually."},"pendingReview":true},{"id":"obesity","label":"Body mass index","cells":{"lung":"Class I obesity (BMI 30.0–34.9), particularly truncal, is a relative contraindication.","kidney":"Assessed individually.","liver":"Assessed individually.","pancreas":"Assessed individually."}},{"id":"living-donation","label":"Living donation possible?","cells":{"lung":"Not in routine South African practice.","kidney":"Yes — the most common form of living donation.","liver":"Yes — a liver segment.","pancreas":"No."}}],"bottomLine":"Age by itself is not a contraindication to transplantation. What matters is physiological reserve and the comorbidities that tend to accompany age — which is why these decisions are made by teams, at the time, and not by rules of thumb."}', '2026-08-18T19:36:16.797+00:00', '2026-08-18T19:36:16.797+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('s97pmcfrmkxdy8zde48jw8by', 'gkh2ea7yygxftemfrwmx9nac', 4, 'takeaways', 'Key takeaways', 'TAKEAWAYS', NULL, 'TakeawayList', '{"takeaways":[{"id":"t1","text":"Donor eligibility and recipient candidacy are different questions. This module is about who receives."},{"id":"t2","text":"Most contraindications are relative rather than absolute, and several have moved as evidence has moved."},{"id":"t3","text":"Age by itself is not considered a contraindication to transplantation — it is physiological reserve and accompanying comorbidities that matter."},{"id":"t4","text":"Public assumptions are often far broader than the actual criterion. The heart absolute contraindication is AIDS with frequent opportunistic infections, not HIV as such."},{"id":"t5","text":"Mechanical circulatory support means transplantation is not always the only option in advanced heart failure."},{"id":"t6","text":"Outcomes are good: one-year survival after cardiac transplantation approaches 90%, and half of recipients survive beyond 11 years."},{"id":"t7","text":"You are not expected to reproduce any of this in public. Understanding its shape is enough — and it is the reason to avoid confident exclusion claims."}]}', '2026-08-18T19:36:16.799+00:00', '2026-08-18T19:36:16.799+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('orzfm4gzgrzqldd2b6o6yyli', 'gkh2ea7yygxftemfrwmx9nac', 5, 'check', 'Check your understanding', 'CHECK', NULL, NULL, NULL, '2026-08-18T19:36:16.800+00:00', '2026-08-18T19:36:16.800+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('c6xciozv555duhd9ms9yzvnz', 'gkh2ea7yygxftemfrwmx9nac', 6, 'study-guide', 'Study guide', 'STUDY_GUIDE', NULL, NULL, '{"summary":"Recipient candidacy across the solid organs. Advanced reading — not required knowledge for an advocate.","sections":[{"id":"s1","heading":"Heart — the shape of the decision","body":"Around 5–10% of heart failure patients have advanced, stage D disease. One-year survival after cardiac transplantation approaches 90%, with 50% of patients surviving beyond 11 years. Patients with comorbidities who would previously have been unsuitable are now often considered."},{"id":"s2","heading":"Heart — absolute contraindications","bullets":["Systemic illness with a life expectancy under two years despite transplantation","Active or recent solid organ or blood malignancy within five years","AIDS with frequent opportunistic infections","Active multisystem systemic lupus erythematosus, sarcoid or amyloidosis","Irreversible renal or hepatic dysfunction, in patients considered for heart transplantation alone","Significant obstructive pulmonary disease; fixed pulmonary hypertension"],"pendingReview":true},{"id":"s3","heading":"Heart — examples of relative contraindications","bullets":["Morbid obesity (BMI above 35) or cachexia (BMI below 18)","Creatinine above 2.5 mg/dL or creatinine clearance below 25 mL/min","Severe pulmonary dysfunction with FEV1 below 40% of normal","Difficult-to-control hypertension","Active mental illness or psychosocial instability","Drug, tobacco or alcohol abuse within six months"],"pendingReview":true},{"id":"s4","heading":"Lung — age and malignancy","body":"There is no endorsement of an upper age limit as an absolute contraindication, and age by itself should not be considered a contraindication; increasing age is generally associated with comorbidities that are themselves absolute or relative contraindications. Age over 65 with low physiologic reserve is relative, and adults over 75 are unlikely to be candidates in most cases. A recent history of malignancy is an absolute contraindication; a two-year disease-free interval may be reasonable where recurrence risk is low, and five years is prudent in most cases.","pendingReview":true}]}', '2026-08-18T19:36:16.800+00:00', '2026-08-18T19:36:16.800+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('w9bdvc50b9gqvxlucam8lxui', 'gkh2ea7yygxftemfrwmx9nac', 7, 'further-reading', 'Further reading', 'FURTHER_READING', NULL, 'ResourceList', '{"intro":"The primary literature behind this module. Advanced reading — the course is complete without it.","note":"Anything marked \"Opens here\" is the paper Save7 supplied."}', '2026-08-18T19:36:16.801+00:00', '2026-08-18T19:36:16.801+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('e5thw49lym5lkhwd8tfxb4cd', 'gkh2ea7yygxftemfrwmx9nac', 8, 'complete', 'Complete module', 'COMPLETE', NULL, NULL, NULL, '2026-08-18T19:36:16.801+00:00', '2026-08-18T19:36:16.801+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('o0t1ytz36qvy3zzrs5951cub', 'rqbcwtid9j9vbik6cabq6v8p', 1, 'intro', 'Why this matters', 'INTRO', 'Overselling transplantation does the cause no favours. A transplant is not a cure and it is not a return to how things were before; it trades one serious medical situation for another, usually far better, one.
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('zxi6aojhsce0vk463n026aqm', 'rqbcwtid9j9vbik6cabq6v8p', 2, 'the-recipient-journey', 'The recipient''s journey', 'PRIMARY', NULL, 'PathwayJourney', '{"intro":"What follows a transplant, over days, months and years.","showLossPoints":false,"steps":[{"id":"transplantation","label":"The transplant operation","summary":"Major surgery, with a recovery period to match.","detail":"The operation itself is the part everyone pictures, and clinically it is the most predictable stage of the whole journey."},{"id":"immunosuppression","label":"Immunosuppression","summary":"Lifelong medication, with real trade-offs.","detail":"The recipient''s immune system will recognise the transplanted organ as foreign. Immunosuppressive medication prevents it from rejecting the graft — and by design leaves the recipient more vulnerable to infection.\n\nThis is the central trade of transplantation: a functioning organ in exchange for a managed, lifelong compromise of the immune system. Advances in immunosuppression are a large part of why survival figures have improved so much."},{"id":"rejection","label":"Rejection","summary":"Monitored for, and often treatable.","detail":"Rejection is why follow-up is lifelong rather than a courtesy. It is monitored for deliberately, and an episode of rejection does not automatically mean the graft is lost — it means treatment changes."},{"id":"early-complications","label":"Early complications","summary":"The first weeks and months.","detail":"Surgical and infectious complications are concentrated early, when immunosuppression is heaviest and the surgery is fresh."},{"id":"late-complications","label":"Late complications","summary":"Months and years later — the part nobody expects.","detail":"Complications do not stop once a recipient goes home. In liver transplantation, **biliary strictures and incisional hernias are the most common late surgical complications**.\n\nThe detail shows how ongoing this care is. Anastomotic biliary strictures can usually be managed endoscopically and rarely need surgery. A biliary stricture requires the hepatic artery to be checked, because the two are connected. Ischaemic-type intrahepatic strictures are a common reason for re-transplantation. And recipients of living-related grafts, or grafts donated after circulatory death, are at the highest risk of late biliary and vascular complications."},{"id":"graft-survival","label":"Long-term graft survival","summary":"Grafts last a long time. They do not last forever.","detail":"Survival varies by organ and by person. For hearts, half of recipients survive beyond eleven years. Some recipients will eventually need a second transplant — which is one reason the donor shortage compounds over time."},{"id":"follow-up","label":"Lifelong follow-up","summary":"Why the medical relationship never really ends.","detail":"Medication adherence, monitoring for rejection, and watching for late complications continue indefinitely. This is also why psychosocial stability appears in candidate selection: a transplant asks a great deal of the person who receives it."}]}', '2026-08-18T19:36:16.803+00:00', '2026-08-18T19:36:16.803+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('fncjaa2mnau7ou9stlwz4l8i', 'rqbcwtid9j9vbik6cabq6v8p', 3, 'takeaways', 'Key takeaways', 'TAKEAWAYS', NULL, 'TakeawayList', '{"takeaways":[{"id":"t1","text":"Transplantation is the start of a lifelong medical journey, not a cure."},{"id":"t2","text":"Immunosuppression prevents rejection and increases vulnerability to infection. It is a trade, not a fix."},{"id":"t3","text":"Rejection is monitored for and often treatable. An episode does not automatically mean losing the graft."},{"id":"t4","text":"Complications can appear years later. In liver transplantation, biliary strictures and incisional hernias are the most common late surgical complications."},{"id":"t5","text":"Recipients of living-related or circulatory-death grafts carry the highest risk of late biliary and vascular complications."},{"id":"t6","text":"Grafts do not last forever, and some recipients need a second transplant — so the shortage compounds."},{"id":"t7","text":"Describe transplantation honestly. Overselling it damages credibility and misrepresents recipients'' lives."}]}', '2026-08-18T19:36:16.805+00:00', '2026-08-18T19:36:16.805+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('fngw4jaro2kbegfc10ftadrj', 'rqbcwtid9j9vbik6cabq6v8p', 4, 'check', 'Check your understanding', 'CHECK', NULL, NULL, NULL, '2026-08-18T19:36:16.806+00:00', '2026-08-18T19:36:16.806+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('fzfmoody4szq10trv3c09lzm', 'rqbcwtid9j9vbik6cabq6v8p', 5, 'study-guide', 'Study guide', 'STUDY_GUIDE', NULL, NULL, '{"summary":"What follows a transplant.","sections":[{"id":"s1","heading":"Immunosuppression and rejection","body":"Immunosuppressive medication prevents the recipient''s immune system from rejecting the graft, at the cost of increased vulnerability to infection. It continues for life. Rejection is monitored for, and an episode does not automatically mean the graft is lost."},{"id":"s2","heading":"Late complications after liver transplantation","bullets":["Biliary strictures and incisional hernias are the most common late surgical complications","Anastomotic biliary strictures are amenable to endoscopic intervention and rarely require surgery","The presence of a biliary stricture mandates evaluation of hepatic artery patency","Ischaemic-type intrahepatic strictures are a common indication for re-transplantation","Recipients of living-related liver transplants and of grafts donated after circulatory death are at highest risk of late biliary and vascular complications"],"pendingReview":true},{"id":"s3","heading":"Graft survival","body":"Varies by organ and by individual. One-year survival after cardiac transplantation approaches 90%, with half of recipients surviving beyond eleven years. Some recipients will require re-transplantation."},{"id":"s4","heading":"Why this matters to an advocate","body":"Describing transplantation accurately — including its costs — is more persuasive than presenting it as a cure, and it respects the actual experience of recipients."}]}', '2026-08-18T19:36:16.806+00:00', '2026-08-18T19:36:16.806+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('n59hdavriuh0fbnucvbkre2l', 'rqbcwtid9j9vbik6cabq6v8p', 6, 'further-reading', 'Further reading', 'FURTHER_READING', NULL, 'ResourceList', '{"intro":"Advanced reading on late outcomes.","note":"Anything marked \"Opens here\" is the paper Save7 supplied."}', '2026-08-18T19:36:16.807+00:00', '2026-08-18T19:36:16.807+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('xu6ojrmbnf21ubtt1d8fo3gp', 'rqbcwtid9j9vbik6cabq6v8p', 7, 'complete', 'Complete module', 'COMPLETE', NULL, NULL, NULL, '2026-08-18T19:36:16.807+00:00', '2026-08-18T19:36:16.807+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('w1bwj5s6tbxfvkq4d7568d3j', 'auptjr9yc0gqtaxqy34509lv', 1, 'intro', 'Five things that hold under pressure', 'INTRO', 'Two rules carry most of the weight here.
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('sutnvc7feoeql6kmgvodt3cu', 'auptjr9yc0gqtaxqy34509lv', 2, 'hard-conversations', 'Five hard conversations', 'PRIMARY', NULL, 'ScenarioDialogue', '{"intro":"None of these has a clean answer. Choose the response you think does least harm and most good, then read why.","scenarios":[{"id":"s1","speaker":"A family at the bedside","quote":"She''s still warm. Her heart is beating. You''re asking us to give up on her.","whatsReallyHappening":"The family is being asked to accept something that contradicts what they can see and touch. This is the hardest moment in the entire donation pathway.","reflectPrompt":"What should you absolutely not do here?","options":[{"id":"o1","text":"Explain that brain death is legally and medically death, and that the ventilator is what is keeping her heart beating.","quality":"poor","feedback":"The facts are right and the timing is wrong. A family in this moment cannot absorb a clinical explanation, and leading with one reads as correcting their grief. This explanation belongs to the clinical team."},{"id":"o2","text":"\"I can''t imagine how impossible this feels. Nobody is asking you to give up on her.\" Then stop talking, and let them lead.","quality":"strong","feedback":"Correct. It acknowledges the reality of what they are experiencing, gently rejects the framing of ''giving up'', and then makes space. Silence is a legitimate and often the best contribution here."},{"id":"o3","text":"Ask whether they would like to talk to the doctors again, or have someone from their faith community with them.","quality":"strong","feedback":"Excellent, and it maps onto how this is actually done: the consultant and coordinator may involve a faith representative or hospital chaplain precisely to support families here. You are connecting them to the right people rather than substituting for them."},{"id":"o4","text":"Point out gently that she would want to help others if she could.","quality":"poor","feedback":"This puts words in the patient''s mouth at the family''s most vulnerable moment. It will be experienced as pressure, and it can permanently damage trust in everyone present."}],"debrief":"This is a clinical and counselling conversation, not an advocacy one. It is also why decoupling exists: the family must be allowed to absorb the death before donation is raised at all, and support is deliberately not withdrawn immediately. The guidelines even have a name for the time this takes — accommodation."},{"id":"s2","speaker":"Two siblings, disagreeing in front of you","quote":"He never said anything about this. — He did, he told me years ago. — Well he never told me.","whatsReallyHappening":"A family with no shared knowledge of the person''s wishes. The disagreement is often about far more than donation.","reflectPrompt":"Whose side are you on?","options":[{"id":"o1","text":"Support the sibling who says he wanted to donate — they have the relevant information.","quality":"poor","feedback":"Taking a side inside a grieving family is not your role, and it will fracture the conversation entirely."},{"id":"o2","text":"\"It sounds like this is something you need to work out together, and there''s no rush from me. Would it help to have someone from the team explain the options to you both at the same time?\"","quality":"strong","feedback":"Refuses to arbitrate, removes time pressure you have no business applying, and offers a shared source of information so both siblings hear the same thing. The evidence supports the patience: taking longer did not reduce consent."},{"id":"o3","text":"Explain who is legally entitled to consent, so they know where they stand.","quality":"workable","feedback":"The legal position is real — consent comes from next of kin: spouse, parent, child, brother or sister. But delivered by an advocate in a live family dispute it reads as picking a winner. This is better coming from the coordinator."},{"id":"o4","text":"Suggest they think about what he would have wanted.","quality":"workable","feedback":"Reasonable in principle, and it is exactly the question they are already fighting about. It rarely resolves anything in the moment."}],"debrief":"This scenario is the clearest possible argument for Save7''s whole premise. The disagreement exists because a conversation never happened — and because consent from next of kin is always required, that missing conversation is now doing real damage."},{"id":"s3","speaker":"A community member","quote":"People like us don''t get organs. We only give them.","whatsReallyHappening":"A statement about structural inequity and mistrust of the health system. It may well be grounded in real experience, and dismissing it would be both wrong and counterproductive.","reflectPrompt":"What makes this different from a factual misconception?","options":[{"id":"o1","text":"Reassure them that allocation is based on medical criteria, not on who you are.","quality":"workable","feedback":"It may be accurate, but offered as a first response it sounds like a denial of their experience. Trust has to come before information."},{"id":"o2","text":"\"That''s a fair thing to be suspicious about, and I''m not going to tell you your experience is wrong. Can I ask what you''ve seen that makes you say that?\"","quality":"strong","feedback":"Takes the concern seriously as a legitimate position rather than an error to be fixed, and listens before responding. This is the only route to a real conversation here."},{"id":"o3","text":"Acknowledge that equity of access is a real problem in South African healthcare, and be honest about it, while explaining how allocation itself is meant to work.","quality":"strong","feedback":"Honest on both counts — and it happens to align with how the professional guidance frames it: equity of access to donation support pathways is described as a crucial component of healthcare delivery. Conceding a real problem is what makes the rest of what you say believable."},{"id":"o4","text":"Point out that they might need a transplant themselves one day.","quality":"poor","feedback":"Self-interest framing on top of an equity concern will land as manipulative, and it sidesteps what they actually said."}],"debrief":"Mistrust grounded in real inequity is not a myth and cannot be corrected like one. Worth knowing: donation is possible from all communities and cultures in South Africa, and it should never be assumed that someone''s background means the subject shouldn''t be raised — the assumption itself is part of the inequity."},{"id":"s4","speaker":"An older relative","quote":"My body needs to be whole when it''s buried. That''s not negotiable for me.","whatsReallyHappening":"A religious or cultural conviction about bodily integrity. This is a settled belief, not an information gap.","reflectPrompt":"What outcome should you be aiming for here?","options":[{"id":"o1","text":"Explain that recovery is done surgically and the body is restored to its original state, so burial is not usually affected.","quality":"workable","feedback":"The fact is correct and genuinely reassuring to many people — the body is restored afterwards. But offered unprompted against a stated conviction, it reads as an attempt to talk them out of it. Offer it if they ask."},{"id":"o2","text":"\"I hear you, and I''m not going to try to change that. Thank you for telling me clearly.\"","quality":"strong","feedback":"Accepting a settled position gracefully is a legitimate and successful outcome. It also keeps the relationship intact for every future conversation."},{"id":"o3","text":"Accept their position, and ask whether they''ve told the rest of the family so nobody has to guess on their behalf.","quality":"strong","feedback":"The best available answer. It fully respects their decision and still achieves Save7''s actual goal — a family that knows. Since consent comes from next of kin, a clearly communicated ''no'' prevents an agonising guess later."},{"id":"o4","text":"Ask whether tissue donation might be more acceptable than organ donation.","quality":"poor","feedback":"Negotiating around a stated conviction about bodily integrity. It signals that you did not accept their answer the first time."}],"debrief":"A clearly communicated refusal is a good outcome for Save7. The failure mode is not ''no'' — it is a family left guessing. And there is evidence the conversation itself helps families regardless of the decision they reach."},{"id":"s5","speaker":"Someone at a Save7 event","quote":"So how many organs actually get transplanted in South Africa each year? What''s the real number?","whatsReallyHappening":"A direct factual question where a confident guess would be tempting — and where the honest answer requires you to know how old your figures are.","reflectPrompt":"What is the professional answer?","options":[{"id":"o1","text":"Give your best recollection of the figure, with a caveat that you''re not certain.","quality":"poor","feedback":"A half-remembered statistic becomes the thing they repeat to other people. The caveat does not travel with it."},{"id":"o2","text":"Give the figures you know with their date attached — \"between 2010 and 2019 there were 2 416 kidney transplants and 292 heart transplants\" — and offer to get the current numbers from the Organ Donor Foundation.","quality":"strong","feedback":"This is the professional answer. You have given real figures, dated them honestly so nobody mistakes a decade total for last year, and pointed to the body that maintains the current numbers."},{"id":"o3","text":"Redirect to the point that the number is far lower than the need, without quoting a figure.","quality":"workable","feedback":"Honest and usable, and it answers the underlying point. Better still if you follow up with dated figures."},{"id":"o4","text":"Explain that statistics vary by source and year, so a single number is misleading.","quality":"workable","feedback":"True, but it can sound evasive. Pair it with the dated figures you do have."}],"debrief":"Advocates are trusted because they are careful. Always date a statistic. The figures in this course are decade totals for 2010–2019 from the Organ Donor Foundation — useful, and not the same thing as current annual numbers."}]}', '2026-08-18T19:36:16.810+00:00', '2026-08-18T19:36:16.810+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('oluv7c4py5rr3eipdp0w9o42', 'auptjr9yc0gqtaxqy34509lv', 3, 'understanding-the-donation-conversation', 'Understanding the donation conversation', 'PRIMARY', NULL, 'PathwayJourney', '{"intro":"When a family in South Africa is asked about donation, the conversation usually follows a structured process called **FACTS** — the Family Approach to Consent for Transplant Strategy, developed at Wits Transplant and adapted from the UK''s NHS Blood and Transplant model.\n\n**Read this before you go any further.** FACTS is a clinical strategy for transplant procurement coordinators. Completing this course does not qualify you to approach a family or to request consent, and this lesson is not training to do either. You are here to understand *why* the professional conversation is built this way — because the reasoning behind it also makes you better at the conversations that genuinely are yours to have.\n\nWalk through the eight steps. For each one, note the principle underneath it.","steps":[{"id":"f1","label":"Planning","summary":"Before anyone speaks to the family, the approach is prepared.","detail":"Who should be in the room. When. Where. In which language. What the family already knows. None of this is left to the moment.\n\n**The principle:** the conversations that go worst are the ones nobody thought about first. Setting, timing and language are not details — they are most of the outcome."},{"id":"f2","label":"Breaking bad news","summary":"The family is told, and helped to understand, that the person has died.","detail":"This step is about the death and nothing else. Donation is not mentioned. A family that has not yet grasped that their person has died cannot meaningfully consider anything else.\n\n**The principle:** this is decoupling, and it is the reason it matters. It is not a technique for improving consent rates — it is what makes a decision a real decision."},{"id":"f3","label":"Time-out break","summary":"The family is deliberately left alone.","detail":"A pause is built into the process. Not an accident, not a gap while staff are busy elsewhere — a designed interval before donation is raised at all.\n\n**The principle:** silence and space are part of the method. If a formal clinical strategy schedules them, you can stop treating a pause in your own conversation as a failure to fill."},{"id":"f4","label":"Assessing understanding and acceptance of loss","summary":"Before donation is raised, someone checks what the family actually understands.","detail":"Not whether they were told. What they understood, and whether they accept it. Families sitting beside a warm body with a beating heart very often have not — and that is not stubbornness, it is the situation contradicting the information.\n\n**The principle:** never assume that being told is the same as understanding. Check, gently, before you build on anything."},{"id":"f5","label":"The consent conversation","summary":"Donation is introduced. Concerns are heard, questions answered.","detail":"Only now. The coordinator raises donation, then mostly listens — surfacing concerns, answering what is asked, giving accurate information in a supportive way. It is not a pitch.\n\n**The principle:** listening comes before informing, and information is offered rather than pushed. This is the step most people imagine the whole conversation to be, and it is one of eight."},{"id":"f6","label":"Time-out break","summary":"A second deliberate pause, so the family can talk among themselves.","detail":"The family is left to discuss it without a professional present. A decision that has to be made in front of the person asking for it is not a free one.\n\n**The principle:** people need to process without an audience. Do not stand there waiting for an answer."},{"id":"f7","label":"Final family discussion","summary":"The coordinator returns, asks for the decision, and respects it.","detail":"Remaining concerns are addressed and the family''s decision is taken as final. A no is accepted as an answer, not treated as an opening position.\n\n**The principle:** you are never obliged to win. A family who felt respected while declining is a better outcome than one who felt worked on."},{"id":"f8","label":"Family follow-up, feedback and support","summary":"Support continues after the decision, whatever it was.","detail":"Follow-up after recovery, ongoing support, and where appropriate information about what happened to the donated organs.\n\n**The principle:** the family is not a means to an organ. The relationship does not end when the answer is given — which is also the difference between advocacy and recruitment."}]}', '2026-08-18T19:36:16.810+00:00', '2026-08-18T19:36:16.810+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('xhv5dumo87nvvic2fvj8tbh5', 'auptjr9yc0gqtaxqy34509lv', 4, 'takeaways', 'Key takeaways', 'TAKEAWAYS', NULL, 'TakeawayList', '{"takeaways":[{"id":"t1","text":"You are not a counsellor. Knowing when to stop and refer is a skill, not a failure."},{"id":"t2","text":"Decouple. The death and the donation are separate conversations, and the second is not yours to start at the bedside."},{"id":"t3","text":"Do not rush a family. Taking longer than 48 hours was associated with higher consent, not lower."},{"id":"t4","text":"A clearly communicated ''no'' is a good outcome. A family left guessing is the failure."},{"id":"t5","text":"Mistrust grounded in real inequity is not a myth and cannot be corrected like one."},{"id":"t6","text":"Never put words in a dead or dying person''s mouth, and never negotiate around a stated conviction."},{"id":"t7","text":"Always date a statistic. \"2 416 kidney transplants between 2010 and 2019\" is useful; \"about 2 400 a year\" is wrong."},{"id":"t8","text":"Silence is a legitimate contribution. Sometimes it is the best one."},{"id":"t9","text":"FACTS is a coordinator''s strategy, not a volunteer''s script. Understanding why it is built that way is the point; performing it is not your role."}]}', '2026-08-18T19:36:16.811+00:00', '2026-08-18T19:36:16.811+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('vkhqkmqmy1ostgc3hmcl5z7v', 'auptjr9yc0gqtaxqy34509lv', 5, 'check', 'Check your understanding', 'CHECK', NULL, NULL, NULL, '2026-08-18T19:36:16.811+00:00', '2026-08-18T19:36:16.811+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('zx8w4accoykl37bq5riwfivp', 'auptjr9yc0gqtaxqy34509lv', 6, 'study-guide', 'Study guide', 'STUDY_GUIDE', NULL, NULL, '{"summary":"Difficult conversations, and what the evidence supports.","sections":[{"id":"s1","heading":"The five principles","bullets":["Decouple the diagnosis from the donation request","Do not rush — delay is not refusal, and may be associated with higher consent","Patience and empathy are the method; accommodation exists to give families time","Never assume someone''s background means donation should not be raised","The conversation helps families regardless of the decision they reach"]},{"id":"s2","heading":"On grief","body":"Routine grief counselling is generally not indicated. Most bereaved people are resilient, and acute grief is integrated through a natural adaptive process supported by family, friends and spiritual support. Counselling is valuable for complicated grief. Bereaved people, especially those who have lost children, often find it very difficult to speak about the loss."},{"id":"s3","heading":"The limits of your role","body":"An advocate acknowledges, listens, connects people to the right sources, and stops. Clinical explanation belongs to the clinical team; the donation request belongs to a coordinator; matters of faith belong to the person''s own faith leader."},{"id":"s4","heading":"FACTS — what it is, and what it is not","body":"FACTS stands for the **Family Approach to Consent for Transplant Strategy**. It was developed at Wits Transplant (Wits Donald Gordon Medical Centre, Johannesburg), adapted from the National Health Service Blood and Transplant model in the United Kingdom, and is described as a stepwise process guiding transplant procurement coordinators through initiating and following through the donation conversation — with particular attention to planning, choice of words and timing.\n\nIt is a professional procurement strategy. It is **not** a volunteer script, and completing this course does not make anyone a designated consent-requester. This module teaches the reasoning behind FACTS so that advocates understand why real donation conversations are structured as they are."},{"id":"s5","heading":"The eight steps","bullets":["1. Planning — who, when, where, in which language","2. Breaking bad news — the death, and only the death","3. Time-out break — a designed pause before donation is raised","4. Assessing understanding and acceptance of the loss","5. The consent conversation — introduce, listen, answer","6. Time-out break — the family discusses it privately","7. Final family discussion — ask, address, respect the decision","8. Family follow-up, feedback and support"],"pendingReview":true,"reviewSourceHint":"Verify the eight-step sequence and step names against the Organ and Tissue Donation Reference File (SATCS/Wits). The acronym, origin and purpose are confirmed by de Jager et al., SAMJ 2019;109(9) — that paper describes FACTS as a stepwise process but does not enumerate the steps, so the list itself is second-hand."},{"id":"s6","heading":"What an advocate takes from it","bullets":["Do not rush the family","Make sure they understand the death before anything else","Allow time for processing, and leave people alone to do it","Listen before responding","Acknowledge concerns rather than correcting them","Provide accurate information without pressure","Respect the decision that is reached","Follow up afterwards, whatever was decided"]}]}', '2026-08-18T19:36:16.812+00:00', '2026-08-18T19:36:16.812+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('ssy39quqp3rbdun64f5mkonw', 'auptjr9yc0gqtaxqy34509lv', 7, 'further-reading', 'Further reading', 'FURTHER_READING', NULL, 'ResourceList', '{"intro":"The evidence behind the principles above.","note":"The FACTS strategy is described in the Wits Transplant Procurement Model paper below. Its eight-step sequence is drawn from the Organ and Tissue Donation Reference File and is pending confirmation against that document."}', '2026-08-18T19:36:16.812+00:00', '2026-08-18T19:36:16.812+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('jurw3c345z829ubk9w9e7dzg', 'auptjr9yc0gqtaxqy34509lv', 8, 'complete', 'Complete module', 'COMPLETE', NULL, NULL, NULL, '2026-08-18T19:36:16.813+00:00', '2026-08-18T19:36:16.813+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('r04y0o5vkgucwn570zzeihaz', 'xz0cbqav6esbaiht4u74dsj6', 1, 'intro', 'Where you started, and where you are now', 'INTRO', 'At the beginning of this course, the goal was stated plainly: to leave feeling *I understand organ donation and transplantation well enough to confidently start a conversation about it.*
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('ztej3etl3fc1k8c63kx8yy3z', 'xz0cbqav6esbaiht4u74dsj6', 2, 'what-you-can-now-do', 'What you can now do', 'TAKEAWAYS', NULL, 'TakeawayList', '{"takeaways":[{"id":"t1","text":"Explain why people need donated organs and tissues, without medical jargon."},{"id":"t2","text":"Describe the South African donation pathway, and name the points where it breaks down."},{"id":"t3","text":"Explain brain death clearly, accurately and kindly — and distinguish it from a coma."},{"id":"t4","text":"Name who is involved in a donation, and which roles exist as safeguards."},{"id":"t5","text":"Answer the common legal questions: the Act, consent, unnatural deaths, and costs."},{"id":"t6","text":"Correct the six commonest myths without making anyone feel foolish."},{"id":"t7","text":"Avoid ruling anyone out — and know where firm criteria genuinely do exist."},{"id":"t8","text":"Describe life after transplantation honestly, including what it costs the recipient."},{"id":"t9","text":"Handle a hard conversation, and recognise when it is not yours to have."},{"id":"t10","text":"Date every statistic you quote."},{"id":"t11","text":"Encourage the people you love to tell each other what they want."}]}', '2026-08-18T19:36:16.815+00:00', '2026-08-18T19:36:16.815+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('x91bs50uy2a6li2x2mlzm73l', 'xz0cbqav6esbaiht4u74dsj6', 3, 'the-call-to-action', 'Start the conversation', 'PRIMARY', 'There is one thing left to do, and it is not a Save7 campaign.
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('h00vlfvz5pdvjofw9gajyso8', 'xz0cbqav6esbaiht4u74dsj6', 4, 'check', 'Check your understanding', 'CHECK', NULL, NULL, NULL, '2026-08-18T19:36:16.816+00:00', '2026-08-18T19:36:16.816+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('t6f4ovy8q5klflvmp0sipcx9', 'xz0cbqav6esbaiht4u74dsj6', 5, 'study-guide', 'Study guide', 'STUDY_GUIDE', NULL, NULL, '{"summary":"A single page to keep. Save7 may wish to produce a designed version of this as an advocate reference card.","sections":[{"id":"s1","heading":"The ten questions this course answered","bullets":["Who needs organs?","Why are organs being lost?","What is brain death?","How does donation work?","Who is involved?","What does South African law say?","Who can donate?","What happens after transplantation?","How do I talk about donation?","How can I become part of the solution?"]},{"id":"s2","heading":"The facts worth memorising","bullets":["One donor can give seven or more life-saving organs, and improve 65 or more lives through tissue and corneas","Consent from next of kin is always required","Two registered doctors certify brain death; neither may be on the transplant team; one must have five years'' HPCSA registration","Death is the irreversible loss of the capacity for consciousness and the capacity to breathe","There is no age restriction for solid organ donation","The body is restored to its original state after recovery, and anaesthesia is given during it","The family bears no costs once death is declared and consent obtained","The governing statute is Chapter 8 of the National Health Act No. 61 of 2003"]},{"id":"s3","heading":"The Save7 position","body":"Whether it is for awareness campaigns or a private conversation with family and friends, the most important part is simply starting the conversation."}]}', '2026-08-18T19:36:16.817+00:00', '2026-08-18T19:36:16.817+00:00');
INSERT INTO "Lesson" ("id", "moduleId", "order", "slug", "title", "kind", "bodyMarkdown", "componentKey", "payloadJson", "createdAt", "updatedAt") VALUES ('dlve0rbasow0tprep3b1ifeh', 'xz0cbqav6esbaiht4u74dsj6', 6, 'further-reading', 'Further reading', 'FURTHER_READING', NULL, 'ResourceList', '{"intro":"Where to go next.","note":"Save7 may wish to add volunteer pathways and contact details here."}', '2026-08-18T19:36:16.817+00:00', '2026-08-18T19:36:16.817+00:00');
