INSERT INTO "Resource" ("id", "authoringKey", "courseId", "moduleId", "title", "description", "type", "isRequired", "source", "author", "publishedOn", "externalUrl", "filePath", "licenceNote", "isStub", "order", "createdAt", "updatedAt") VALUES ('ykavkd41ecnmcj3uy3al4r75', 'organ-donor-foundation-of-south-africa', 'm35n2u60pubvs9t826p6l3fk', NULL, 'Organ Donor Foundation of South Africa', 'The national umbrella body for promoting awareness and managing the donor database. The right place to send anyone who wants to register, or who asks for current South African figures.', 'WEBSITE', 0, 'Organ Donor Foundation of South Africa', NULL, NULL, 'https://odf.org.za', NULL, NULL, 0, 1, '2026-08-18T19:36:16.819+00:00', '2026-08-18T19:36:16.819+00:00');
INSERT INTO "Resource" ("id", "authoringKey", "courseId", "moduleId", "title", "description", "type", "isRequired", "source", "author", "publishedOn", "externalUrl", "filePath", "licenceNote", "isStub", "order", "createdAt", "updatedAt") VALUES ('b6qv0wkhz1xce5dr3jphsov3', 'transplant-alchemy-101-study-guide', 'm35n2u60pubvs9t826p6l3fk', NULL, 'Transplant Alchemy 101 — Study Guide', 'Save7''s own study guide, structured around five learning objectives: who needs organs, where and why organs are lost, the transplant team, the legislation, and donor eligibility. This is the source of truth for the course.', 'PDF', 1, 'Save7', NULL, NULL, NULL, '/resources/transplant-alchemy-101-study-guide.pdf', NULL, 0, 2, '2026-08-18T19:36:16.819+00:00', '2026-08-18T19:36:16.819+00:00');
INSERT INTO "Resource" ("id", "authoringKey", "courseId", "moduleId", "title", "description", "type", "isRequired", "source", "author", "publishedOn", "externalUrl", "filePath", "licenceNote", "isStub", "order", "createdAt", "updatedAt") VALUES ('m9dm6fjrgrli8u6hg7gll7lq', 'amboss-transplantation', 'm35n2u60pubvs9t826p6l3fk', NULL, 'Transplantation — AMBOSS Knowledge Library', 'General clinical reference on transplantation, cited by the study guide.', 'WEBSITE', 0, 'AMBOSS GmbH', NULL, NULL, 'https://next.amboss.com/us/article/gn0Fsg', NULL, 'Cited by the Save7 study guide, accessed 10 February 2026. Requires an AMBOSS subscription.', 0, 3, '2026-08-18T19:36:16.820+00:00', '2026-08-18T19:36:16.820+00:00');
INSERT INTO "Resource" ("id", "authoringKey", "courseId", "moduleId", "title", "description", "type", "isRequired", "source", "author", "publishedOn", "externalUrl", "filePath", "licenceNote", "isStub", "order", "createdAt", "updatedAt") VALUES ('xgd0svc5cvo68wszlhx8ryzt', 'mehra-2016-ishlt-listing-criteria', 'm35n2u60pubvs9t826p6l3fk', 'o4uhyh92co3dakkj9jkz66ra', 'The 2016 International Society for Heart Lung Transplantation listing criteria for heart transplantation: A 10-year update', 'The international listing criteria for heart transplantation. Cited by the study guide for heart transplant indications.', 'ACADEMIC_PAPER', 0, 'The Journal of Heart and Lung Transplantation, 35(1), 1–23 (2016)', 'Mehra, M. R., Canter, C. E., Hannan, M. M., Semigran, M. J., Uber, P. A., Baran, D. A., Danziger-Isakov, L., Kirklin, J. K., Kirk, R., Kushwaha, S. S., Lund, L. H., Potena, L., Ross, H. J., Taylor, D. O., Verschuuren, E. A. M., & Zuckermann, A.', NULL, NULL, NULL, 'Cited in the Save7 study guide reference list. The full text was not among the supplied PDFs.', 0, 4, '2026-08-18T19:36:16.821+00:00', '2026-08-18T19:36:16.821+00:00');
INSERT INTO "Resource" ("id", "authoringKey", "courseId", "moduleId", "title", "description", "type", "isRequired", "source", "author", "publishedOn", "externalUrl", "filePath", "licenceNote", "isStub", "order", "createdAt", "updatedAt") VALUES ('vls8z48fk2f3tmhl5ka116g6', 'weill-2015-lung-candidate-selection', 'm35n2u60pubvs9t826p6l3fk', 'o4uhyh92co3dakkj9jkz66ra', 'A consensus document for the selection of lung transplant candidates: 2014 — An update from the Pulmonary Transplantation Council of the ISHLT', 'International consensus on which patients are considered for lung transplantation. Underpins the study guide''s statement that lung transplants are indicated for advanced lung disease with a risk of death exceeding 50% over two years.', 'ACADEMIC_PAPER', 0, 'The Journal of Heart and Lung Transplantation, 34(1), 1–15 (2015)', 'Weill, D., Benden, C., Corris, P. A., Dark, J. H., Davis, R. D., Keshavjee, S., Lederer, D. J., Mulligan, M. J., Patterson, G. A., Singer, L. G., Snell, G. I., Verleden, G. M., Zamora, M. R., & Glanville, A. R.', NULL, NULL, '/resources/weill-2015-lung-candidate-selection.pdf', NULL, 0, 5, '2026-08-18T19:36:16.821+00:00', '2026-08-18T19:36:16.821+00:00');
INSERT INTO "Resource" ("id", "authoringKey", "courseId", "moduleId", "title", "description", "type", "isRequired", "source", "author", "publishedOn", "externalUrl", "filePath", "licenceNote", "isStub", "order", "createdAt", "updatedAt") VALUES ('uwweob0xvzl1bghl67obh4g4', 'canter-2007-paediatric-heart-indications', 'm35n2u60pubvs9t826p6l3fk', 'o4uhyh92co3dakkj9jkz66ra', 'Indications for heart transplantation in pediatric heart disease: A scientific statement from the American Heart Association', 'Paediatric heart transplant indications. Cited by the study guide.', 'ACADEMIC_PAPER', 0, 'Circulation, 115(5), 658–676 (2007)', 'Canter, C. E., Shaddy, R. E., Bernstein, D., Hsu, D. T., Chrisant, M. R. K., Kirklin, J. K., Kanter, K. R., Higgins, R. S. D., Blume, E. D., Rosenthal, D. N., Boucek, M. M., Uzark, K. C., Friedman, A. H., & Young, J. K.', NULL, NULL, NULL, 'Cited in the Save7 study guide reference list. The full text was not among the supplied PDFs.', 0, 6, '2026-08-18T19:36:16.822+00:00', '2026-08-18T19:36:16.822+00:00');
INSERT INTO "Resource" ("id", "authoringKey", "courseId", "moduleId", "title", "description", "type", "isRequired", "source", "author", "publishedOn", "externalUrl", "filePath", "licenceNote", "isStub", "order", "createdAt", "updatedAt") VALUES ('tydk4ojgynh2fbzpunzjx7g4', 'han-2017-family-decision-delay', 'm35n2u60pubvs9t826p6l3fk', 'fy5gk5lj0glyc8cimfs0iamm', 'Factors associated with a family''s delay of decision for organ donation after brain death', 'A study of 107 brain-dead potential donors. Families who took longer than 48 hours to decide had a consent rate of 73%, compared with 55% for those deciding sooner — so a slower decision was not a worse one. The authors conclude that counselling should continue even when a family cannot decide immediately.', 'ACADEMIC_PAPER', 0, 'Annals of Transplantation, 22, 17–23 (2017). DOI: 10.12659/AOT.901616', 'Han, S. Y., Kim, J. I., Lee, E.-W., Jang, H.-Y., Han, K. H., Oh, S. W., & Roh, Y.-N.', NULL, NULL, '/resources/han-2017-family-decision-delay.pdf', NULL, 0, 7, '2026-08-18T19:36:16.822+00:00', '2026-08-18T19:36:16.822+00:00');
INSERT INTO "Resource" ("id", "authoringKey", "courseId", "moduleId", "title", "description", "type", "isRequired", "source", "author", "publishedOn", "externalUrl", "filePath", "licenceNote", "isStub", "order", "createdAt", "updatedAt") VALUES ('vhrsfmdzlcqj6s03xq5df6g5', 'satcs-red-file', 'm35n2u60pubvs9t826p6l3fk', 'utdb2izuy72czxajhg7r2o23', 'The Organ and Tissue Donation Reference File (the “Red File”)', 'SATCS''s reference file for transplant coordinators: the donation process end to end, consent, documentation and tissue criteria. The practical handbook behind much of this course.', 'PDF', 1, 'South African Transplant Coordinators Society (SATCS)', NULL, NULL, NULL, '/resources/satcs-red-file.pdf', NULL, 0, 8, '2026-08-18T19:36:16.823+00:00', '2026-08-18T19:36:16.823+00:00');
INSERT INTO "Resource" ("id", "authoringKey", "courseId", "moduleId", "title", "description", "type", "isRequired", "source", "author", "publishedOn", "externalUrl", "filePath", "licenceNote", "isStub", "order", "createdAt", "updatedAt") VALUES ('u3m3f8mlir14j8hlnhw64ctm', '7-lives-in-7-steps', 'm35n2u60pubvs9t826p6l3fk', 'q65o68xry6cy2gq2zuqz7aru', '7 Lives in 7 Steps', 'Save7''s own clinical referral pathway, as a flowchart and a seven-step checklist. Note step 7: the family is told the diagnosis of brain death and organ donation is deliberately not mentioned at that point — the two conversations are kept separate.', 'PDF', 1, 'Save7', NULL, NULL, NULL, '/resources/7-lives-in-7-steps.pdf', NULL, 0, 9, '2026-08-18T19:36:16.823+00:00', '2026-08-18T19:36:16.823+00:00');
INSERT INTO "Resource" ("id", "authoringKey", "courseId", "moduleId", "title", "description", "type", "isRequired", "source", "author", "publishedOn", "externalUrl", "filePath", "licenceNote", "isStub", "order", "createdAt", "updatedAt") VALUES ('wszy1sb8pzrj0k8se87qgk08', 'the-journey-of-a-gift', 'm35n2u60pubvs9t826p6l3fk', 'pn0m2s6lc0yqqeb8jvf9k3hn', 'The Journey of a Gift', 'Save7''s visual storytelling resource, following a donation from potential donor through to the recipient. 6 minutes 59 seconds. Module 5 is built around it.', 'VIDEO', 1, 'Save7', NULL, NULL, NULL, '/media/journey-of-a-gift.mp4', 'Still needed for launch: a WebVTT captions track and a text transcript (both accessibility requirements), and chapter timecodes so the chapter list beside the player becomes seekable.', 0, 10, '2026-08-18T19:36:16.824+00:00', '2026-08-18T19:36:16.824+00:00');
INSERT INTO "Resource" ("id", "authoringKey", "courseId", "moduleId", "title", "description", "type", "isRequired", "source", "author", "publishedOn", "externalUrl", "filePath", "licenceNote", "isStub", "order", "createdAt", "updatedAt") VALUES ('m856c7aw8rbyefu97624pp0s', 'excellence-in-deceased-donation-2025', 'm35n2u60pubvs9t826p6l3fk', 'pn0m2s6lc0yqqeb8jvf9k3hn', 'Excellence in Deceased Donation — Course Manual (updated 2025)', 'The clinical manual behind the donation pathway: Western Cape organ and tissue donation policy, brain death and circulatory death certification, apnoea testing, donor management (optimising organ function, haemodynamic and respiratory support), family support, and the HPCSA guidelines on informed consent and palliative care.', 'PDF', 1, 'Excellence in Deceased Donation course, updated 2025', NULL, NULL, NULL, '/resources/excellence-in-deceased-donation-2025.pdf', NULL, 0, 11, '2026-08-18T19:36:16.824+00:00', '2026-08-18T19:36:16.824+00:00');
INSERT INTO "Resource" ("id", "authoringKey", "courseId", "moduleId", "title", "description", "type", "isRequired", "source", "author", "publishedOn", "externalUrl", "filePath", "licenceNote", "isStub", "order", "createdAt", "updatedAt") VALUES ('efm9jrk959q8i3xnuaag8cbf', 'sa-guidelines-determination-of-death-ccssa', 'm35n2u60pubvs9t826p6l3fk', 'dupcdrukzkq2wdzrh2ehhee8', 'South African Guidelines on the Determination of Death', 'The authoritative South African source for Module 6. Defines death as the irreversible loss of the capacity for consciousness together with the irreversible loss of the capacity to breathe, sets the preconditions and clinical testing standards, and records that no person meeting the criteria for brain death has ever subsequently regained brain function.', 'PDF', 1, 'Critical Care Society of Southern Africa (2021) — CCSSA website version', 'Thomson, D., Joubert, I., De Vasconcellos, K., Paruk, F., Mokgokong, S., Mathivha, R., McCulloch, M., Morrow, B., Baker, D., Rossouw, B., Mdladla, N., Richards, G. A., Welkovics, N., Levy, B., Coetzee, I., Spruyt, M., Ahmed, N., & Gopalan, D.', NULL, NULL, '/resources/sa-guidelines-determination-of-death-ccssa.pdf', NULL, 0, 12, '2026-08-18T19:36:16.825+00:00', '2026-08-18T19:36:16.825+00:00');
INSERT INTO "Resource" ("id", "authoringKey", "courseId", "moduleId", "title", "description", "type", "isRequired", "source", "author", "publishedOn", "externalUrl", "filePath", "licenceNote", "isStub", "order", "createdAt", "updatedAt") VALUES ('k5anej5uy2ve81vwgguk0zs9', 'sa-guidelines-determination-of-death-sajcc', 'm35n2u60pubvs9t826p6l3fk', 'dupcdrukzkq2wdzrh2ehhee8', 'South African guidelines on the determination of death (published journal version)', 'The peer-reviewed publication of the same guidelines. Cite this version in written material.', 'ACADEMIC_PAPER', 1, 'South African Medical Journal, 111(4b), 367–380 (2021); also South African Journal of Critical Care, 37(1) Part 2, March 2021', 'Thomson, D., Joubert, I., De Vasconcellos, K., Paruk, F., Mokgokong, S., Mathivha, R., McCulloch, M., Morrow, B., Baker, D., Rossouw, B., Mdladla, N., Richards, G. A., Welkovics, N., Levy, B., Coetzee, I., Spruyt, M., Ahmed, N., & Gopalan, D.', NULL, NULL, '/resources/sa-guidelines-determination-of-death-sajcc.pdf', NULL, 0, 13, '2026-08-18T19:36:16.825+00:00', '2026-08-18T19:36:16.825+00:00');
INSERT INTO "Resource" ("id", "authoringKey", "courseId", "moduleId", "title", "description", "type", "isRequired", "source", "author", "publishedOn", "externalUrl", "filePath", "licenceNote", "isStub", "order", "createdAt", "updatedAt") VALUES ('c0umhb599ifgwrvsx8qdc1jw', 'satcs-organisation', 'm35n2u60pubvs9t826p6l3fk', 'igmbm623gsgsydnrkwvvht7l', 'South African Transplant Coordinators Society (SATCS)', 'The body that represents, unites and supports transplant coordinators in South Africa. Publisher of the Red File.', 'WEBSITE', 0, 'SATCS', NULL, NULL, NULL, NULL, 'Current URL still to be confirmed by Save7 — deliberately not guessed. The Red File itself is attached to Module 3.', 1, 14, '2026-08-18T19:36:16.826+00:00', '2026-08-18T19:36:16.826+00:00');
INSERT INTO "Resource" ("id", "authoringKey", "courseId", "moduleId", "title", "description", "type", "isRequired", "source", "author", "publishedOn", "externalUrl", "filePath", "licenceNote", "isStub", "order", "createdAt", "updatedAt") VALUES ('crrsafm4ec6uzum9ag6g5d77', 'national-health-act-chapter-8', 'm35n2u60pubvs9t826p6l3fk', 'tnvu4480yubmdf54pi8nhoie', 'National Health Act No. 61 of 2003 — Chapter 8', 'The primary legislation governing organ and tissue donation and transplantation in South Africa. Chapter 8 covers donation, post-mortem examination and related matters.', 'WEBSITE', 1, 'Republic of South Africa', NULL, NULL, NULL, NULL, 'Act and chapter confirmed from the Save7 study guide. Save7 should add a link to the current consolidated text including amendments in force, and have the module''s legal statements reviewed before launch.', 1, 15, '2026-08-18T19:36:16.826+00:00', '2026-08-18T19:36:16.826+00:00');
INSERT INTO "Resource" ("id", "authoringKey", "courseId", "moduleId", "title", "description", "type", "isRequired", "source", "author", "publishedOn", "externalUrl", "filePath", "licenceNote", "isStub", "order", "createdAt", "updatedAt") VALUES ('x2xht01eanlp3fo8z6le3j1g', 'hpcsa-informed-consent', 'm35n2u60pubvs9t826p6l3fk', 'tnvu4480yubmdf54pi8nhoie', 'Seeking patients'' informed consent: the ethical considerations (Booklet 4)', 'HPCSA guidance on informed consent — who may consent, capacity, voluntariness, and consent on behalf of others. Reproduced within the Excellence in Deceased Donation manual.', 'PDF', 0, 'Health Professions Council of South Africa, Guidelines for Good Practice in the Healthcare Professions, Booklet 4, revised December 2021', NULL, NULL, NULL, '/resources/excellence-in-deceased-donation-2025.pdf', 'Included within the Excellence in Deceased Donation manual.', 0, 16, '2026-08-18T19:36:16.827+00:00', '2026-08-18T19:36:16.827+00:00');
INSERT INTO "Resource" ("id", "authoringKey", "courseId", "moduleId", "title", "description", "type", "isRequired", "source", "author", "publishedOn", "externalUrl", "filePath", "licenceNote", "isStub", "order", "createdAt", "updatedAt") VALUES ('tlrd91flas7kprq5lgsaz0wz', 'hpcsa-palliative-care', 'm35n2u60pubvs9t826p6l3fk', 'tnvu4480yubmdf54pi8nhoie', 'Ethical guidelines on palliative care (Booklet 1)', 'HPCSA guidance on palliative care, including withholding and withdrawal of treatment — the context in which donation after circulatory death arises. Reproduced within the Excellence in Deceased Donation manual.', 'PDF', 0, 'Health Professions Council of South Africa, Guidelines for Good Practice in the Health Care Professions, Booklet 1', NULL, NULL, NULL, '/resources/excellence-in-deceased-donation-2025.pdf', 'Included within the Excellence in Deceased Donation manual.', 0, 17, '2026-08-18T19:36:16.827+00:00', '2026-08-18T19:36:16.827+00:00');
INSERT INTO "Resource" ("id", "authoringKey", "courseId", "moduleId", "title", "description", "type", "isRequired", "source", "author", "publishedOn", "externalUrl", "filePath", "licenceNote", "isStub", "order", "createdAt", "updatedAt") VALUES ('t4gr2u6lg6nzl124m2a76437', 'mancini-lietz-2010-cardiac-candidates', 'm35n2u60pubvs9t826p6l3fk', 'gkh2ea7yygxftemfrwmx9nac', 'Selection of cardiac transplantation candidates in 2010', 'How heart transplant candidates are actually selected: indications, prognostic assessment, mechanical circulatory support, and how contraindications such as age, diabetes, renal dysfunction and obesity are weighed rather than applied as absolute rules.', 'ACADEMIC_PAPER', 0, 'Circulation, 122(2), 173–183 (2010)', 'Mancini, D., & Lietz, K.', NULL, NULL, '/resources/mancini-lietz-2010-cardiac-candidates.pdf', NULL, 0, 18, '2026-08-18T19:36:16.828+00:00', '2026-08-18T19:36:16.828+00:00');
INSERT INTO "Resource" ("id", "authoringKey", "courseId", "moduleId", "title", "description", "type", "isRequired", "source", "author", "publishedOn", "externalUrl", "filePath", "licenceNote", "isStub", "order", "createdAt", "updatedAt") VALUES ('j8cyw36twz2ll4oj63cc5xcu', 'porrett-2009-liver-complications', 'm35n2u60pubvs9t826p6l3fk', 'rqbcwtid9j9vbik6cabq6v8p', 'Late surgical complications following liver transplantation', 'Advanced reading on what can go wrong months and years after a liver transplant — biliary, vascular and other late complications. Useful for understanding why transplantation is a lifelong medical relationship rather than a completed repair.', 'ACADEMIC_PAPER', 0, 'Liver Transplantation, 15(S2), S12–S18 (2009). AASLD/ILTS Syllabus', 'Porrett, P. M., Hsu, J., & Shaked, A.', NULL, NULL, '/resources/porrett-2009-liver-complications.pdf', NULL, 0, 19, '2026-08-18T19:36:16.828+00:00', '2026-08-18T19:36:16.828+00:00');
INSERT INTO "Resource" ("id", "authoringKey", "courseId", "moduleId", "title", "description", "type", "isRequired", "source", "author", "publishedOn", "externalUrl", "filePath", "licenceNote", "isStub", "order", "createdAt", "updatedAt") VALUES ('yb1cdraj8fu0v5wal3hekpa0', 'de-jager-2019-wits-transplant-procurement-model', 'm35n2u60pubvs9t826p6l3fk', 'auptjr9yc0gqtaxqy34509lv', 'Increasing deceased organ donor numbers in Johannesburg, South Africa: 18-month results of the Wits Transplant Procurement Model', 'The primary source for FACTS — the Family Approach to Consent for Transplant Strategy. Describes FACTS as a stepwise process guiding transplant procurement coordinators through the donation conversation, adapted for South Africa from the UK NHS Blood and Transplant model. Read this to understand that FACTS is a clinical procurement strategy, not a volunteer script.', 'ACADEMIC_PAPER', 1, 'South African Medical Journal, 109(9) (2019). doi:10.7196/samj.2019.v109i9.14313', 'de Jager, M., Wilmans, C., Fabian, J., Botha, J. F., & Etheredge, H. R.', NULL, 'https://scielo.org.za/scielo.php?pid=S0256-95742019000900006&script=sci_arttext', NULL, NULL, 0, 20, '2026-08-18T19:36:16.829+00:00', '2026-08-18T19:36:16.829+00:00');
INSERT INTO "Resource" ("id", "authoringKey", "courseId", "moduleId", "title", "description", "type", "isRequired", "source", "author", "publishedOn", "externalUrl", "filePath", "licenceNote", "isStub", "order", "createdAt", "updatedAt") VALUES ('dx55dbocmc0x79v6iciwcan6', 'satcs-organ-and-tissue-donation-reference-file', 'm35n2u60pubvs9t826p6l3fk', 'auptjr9yc0gqtaxqy34509lv', 'Organ and Tissue Donation Reference File', 'The reference file distributed to South African public and private facilities. Save7 identifies this as the document that sets out the eight steps of the FACTS process in full. It was not accessible when this module was written, so the step list in the study guide is flagged for verification against it.', 'PDF', 0, 'South African Transplant Coordinators Society', NULL, NULL, NULL, NULL, 'Citation incomplete: authors, year and a stable public link are still needed. Save7 to supply the file so the eight-step sequence can be verified and this stub completed.', 1, 21, '2026-08-18T19:36:16.830+00:00', '2026-08-18T19:36:16.830+00:00');
INSERT INTO "Resource" ("id", "authoringKey", "courseId", "moduleId", "title", "description", "type", "isRequired", "source", "author", "publishedOn", "externalUrl", "filePath", "licenceNote", "isStub", "order", "createdAt", "updatedAt") VALUES ('e0mzibiteybksmq1e49bvgse', 'register-as-an-organ-donor', 'm35n2u60pubvs9t826p6l3fk', 'xz0cbqav6esbaiht4u74dsj6', 'Register as an organ donor', 'Registration takes under a minute and is free. Remember that registering records your wishes — telling your family is what makes them actionable, because consent from next of kin is always required.', 'WEBSITE', 0, 'Save7', NULL, NULL, 'https://save7.org/register', NULL, NULL, 0, 22, '2026-08-18T19:36:16.830+00:00', '2026-08-18T19:36:16.830+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('i0cq56gvr1cq5t4p4fcj2gle', 'pre-01', 'm35n2u60pubvs9t826p6l3fk', NULL, NULL, 'PRE', 'SINGLE', 'Why do people need organ transplants?', NULL, 'Transplantation is not an enhancement or an optional upgrade. When an organ fails completely, treatment can often buy time, but for some conditions a transplant is the only remaining option.', 'who-needs-organs', 1, 'need-organs', 0, '2026-08-18T19:36:16.831+00:00', '2026-08-18T19:36:16.831+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('ew0kwpq1walqoqrjjq9o90i9', 'pre-02', 'm35n2u60pubvs9t826p6l3fk', NULL, NULL, 'PRE', 'MULTI', 'Which of these can be donated and transplanted? Select all that apply.', NULL, 'Donation covers far more than the organs people usually picture. Tissue donation — corneas, bone, skin, heart valves — helps a large number of people and is routinely left out of public conversation.', 'what-can-be-donated', 1, 'tissue-donation', 1, '2026-08-18T19:36:16.833+00:00', '2026-08-18T19:36:16.833+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('gc5v8wumuzbp4p5i883tkhnw', 'pre-03', 'm35n2u60pubvs9t826p6l3fk', NULL, NULL, 'PRE', 'SINGLE', 'South Africa has many people waiting for organs but relatively few transplants. What is the main reason?', NULL, 'The shortage is a pathway problem. A donation can be lost at any point between a potential donor and a recipient, and most of those loss points are human — awareness, myths, fear, and families never having discussed donation — rather than medical or surgical.', 'loss-points', 1, 'loss-points', 2, '2026-08-18T19:36:16.834+00:00', '2026-08-18T19:36:16.834+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('i4wbtaxmx2yxyxu508f0a9l6', 'pre-04', 'm35n2u60pubvs9t826p6l3fk', NULL, NULL, 'PRE', 'SINGLE', 'You have registered as an organ donor. What else most improves the chance that your wishes are followed?', NULL, 'Registering signals your wishes. Telling your family is what makes those wishes actionable, because a family that has never heard them is being asked to guess at the worst moment of their lives.', 'family-conversation', 1, 'family-conversation', 3, '2026-08-18T19:36:16.836+00:00', '2026-08-18T19:36:16.836+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('i1ujm2hgjh4htv6u3beez53s', 'pre-05', 'm35n2u60pubvs9t826p6l3fk', NULL, NULL, 'PRE', 'TRUE_FALSE', 'Brain death and a coma are essentially the same thing.', NULL, 'They are fundamentally different. Brain death is death, determined by neurological criteria. A coma is a state of profound unconsciousness from which recovery is possible. Conflating the two is the most common and most damaging misunderstanding in organ donation.', 'brain-death', 2, 'brain-death-vs-coma', 4, '2026-08-18T19:36:16.838+00:00', '2026-08-18T19:36:16.838+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('ird92twae93b1u3y4mz5mf16', 'pre-06', 'm35n2u60pubvs9t826p6l3fk', NULL, NULL, 'PRE', 'SINGLE', 'How can someone be declared dead while their heart is still beating?', NULL, 'Mechanical ventilation supplies oxygen the person can no longer obtain for themselves, which allows the heart to continue beating for a period after death has been determined by neurological criteria. This is why a family at the bedside sees a warm body and a beating heart — and why their disbelief is a reasonable human response rather than ignorance.', 'brain-death', 2, 'brain-death-heart-beating', 5, '2026-08-18T19:36:16.840+00:00', '2026-08-18T19:36:16.840+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('k3lnfqggi4euuhmnofpstrm8', 'pre-07', 'm35n2u60pubvs9t826p6l3fk', NULL, NULL, 'PRE', 'SINGLE', 'A friend says: "If I''m registered as a donor, doctors won''t try as hard to save me." What is the strongest factual reassurance?', NULL, 'The clinicians who determine death are independent of the transplant team. That separation is a designed structural safeguard, and it is the direct answer to this specific fear.', 'myths', 2, 'independent-teams', 6, '2026-08-18T19:36:16.841+00:00', '2026-08-18T19:36:16.841+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('qx7cpqwv1wq23ufsfk9ab0du', 'pre-08', 'm35n2u60pubvs9t826p6l3fk', NULL, NULL, 'PRE', 'SINGLE', 'Someone in their late sixties asks whether they are "too old" to be a donor. What is the accurate answer?', NULL, 'Do not assume anyone cannot donate. Suitability is determined through appropriate medical assessment at the time — it is not something a member of the public, or the potential donor, can decide in advance.', 'eligibility', 1, 'eligibility-age', 7, '2026-08-18T19:36:16.842+00:00', '2026-08-18T19:36:16.842+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('fcn3kz2rx5ttfjlvxsfil07n', 'pre-09', 'm35n2u60pubvs9t826p6l3fk', NULL, NULL, 'PRE', 'SINGLE', 'Which statement about donor eligibility is most accurate?', NULL, 'Suitability is assessed individually, and can be organ-specific: being unsuitable for one donation does not mean being unsuitable for all. Simple exclusion rules are frequently wrong and change as clinical practice changes.', 'eligibility', 2, 'eligibility-comorbidity', 8, '2026-08-18T19:36:16.844+00:00', '2026-08-18T19:36:16.844+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('tlf3t8c1b6pcpqdy3fbm5skw', 'pre-10', 'm35n2u60pubvs9t826p6l3fk', NULL, NULL, 'PRE', 'SINGLE', 'Why do translators matter in the donation process?', NULL, 'Consent that is not understood is not consent. Translators are part of the safeguards around a genuinely informed decision, not merely a courtesy for the family''s comfort.', 'who-is-involved', 2, 'team-safeguards', 9, '2026-08-18T19:36:16.846+00:00', '2026-08-18T19:36:16.846+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('ts6d2ma7se0z7hx3by1jq4d1', 'pre-11', 'm35n2u60pubvs9t826p6l3fk', NULL, NULL, 'PRE', 'SINGLE', 'What best describes life for someone after a successful transplant?', NULL, 'Transplantation is the start of a lifelong medical journey, not a cure. Describing it honestly is more persuasive than a happy ending, and it respects recipients'' actual experience.', 'after-transplant', 2, 'after-transplant', 10, '2026-08-18T19:36:16.848+00:00', '2026-08-18T19:36:16.848+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('rx1ba729kgnkt4gz9ztflb7r', 'pre-12', 'm35n2u60pubvs9t826p6l3fk', NULL, NULL, 'PRE', 'SCENARIO', 'What is the best response?', 'At a community event, someone tells you their religion does not allow organ donation.', 'Never tell someone what their own faith permits — that oversteps your competence and costs you their trust. Accept their position, and remember that Save7''s goal is a family that has talked, not a converted donor. A clearly communicated ''no'' is a good outcome.', 'conversation', 2, 'responding-to-religion', 11, '2026-08-18T19:36:16.850+00:00', '2026-08-18T19:36:16.850+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('r7pnqr0uhl8pvynu1zwmusr8', 'post-b-01', 'm35n2u60pubvs9t826p6l3fk', 'r2c3xtv3fjygs84lo5odbkv7', NULL, 'POST', 'SINGLE', 'Why do people need organ transplants?', NULL, 'Transplantation treats organs that have failed completely. For some conditions it is the only remaining option once other treatment can no longer sustain the organ''s function.', 'who-needs-organs', 1, 'need-organs', 12, '2026-08-18T19:36:16.851+00:00', '2026-08-18T19:36:16.851+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('qgtsvo1tjt9s94o7d0sktd9v', 'post-b-02', 'm35n2u60pubvs9t826p6l3fk', 'r2c3xtv3fjygs84lo5odbkv7', NULL, 'POST', 'MULTI', 'Which of these are transplanted as tissue rather than as solid organs? Select all that apply.', NULL, 'Corneas, bone and ligaments, skin and heart valves are tissue donations. Tissue donation helps a large number of people and is routinely missing from public conversation about donation.', 'what-can-be-donated', 1, 'tissue-donation', 13, '2026-08-18T19:36:16.852+00:00', '2026-08-18T19:36:16.852+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('o1wlaqal9suh49rjsfz4t9ir', 'post-b-03', 'm35n2u60pubvs9t826p6l3fk', 'r2c3xtv3fjygs84lo5odbkv7', NULL, 'POST', 'SINGLE', 'Which best describes why so few organs reach the people who need them in South Africa?', NULL, 'The pathway from a potential donor to a recipient has many points at which it can quietly break, and most of them are human rather than medical.', 'loss-points', 1, 'loss-points', 14, '2026-08-18T19:36:16.854+00:00', '2026-08-18T19:36:16.854+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('ijx3hl5ptbo078tdbot1cll6', 'post-b-04', 'm35n2u60pubvs9t826p6l3fk', 'r2c3xtv3fjygs84lo5odbkv7', NULL, 'POST', 'SINGLE', 'Which loss point in the donation pathway is most directly changed by someone having had a conversation with their family years earlier?', NULL, 'Family refusal is the largest preventable loss point. A family that has heard the person''s wishes is not being asked to guess during acute grief, which is exactly what a prior conversation prevents.', 'loss-points', 2, 'loss-points-largest', 15, '2026-08-18T19:36:16.856+00:00', '2026-08-18T19:36:16.856+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('mo17y61xa3k6yvebgyhlmmhk', 'post-b-05', 'm35n2u60pubvs9t826p6l3fk', 'r2c3xtv3fjygs84lo5odbkv7', NULL, 'POST', 'TRUE_FALSE', 'Brain death and a coma are essentially the same thing.', NULL, 'Brain death is death, determined by neurological criteria. A coma is profound unconsciousness from which recovery is possible. Conflating them is the most damaging misunderstanding in organ donation.', 'brain-death', 2, 'brain-death-vs-coma', 16, '2026-08-18T19:36:16.857+00:00', '2026-08-18T19:36:16.857+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('y71m4v47dz2n3cp7dzetk5nz', 'post-b-06', 'm35n2u60pubvs9t826p6l3fk', 'r2c3xtv3fjygs84lo5odbkv7', NULL, 'POST', 'SINGLE', 'A colleague says: "I''m in my sixties and on blood pressure medication — I''d be turned down anyway." What is the best response?', NULL, 'Do not rule anyone out, and do not overcorrect by claiming the factor is irrelevant. Suitability is determined by medical assessment at the time.', 'eligibility', 1, 'eligibility-age', 17, '2026-08-18T19:36:16.858+00:00', '2026-08-18T19:36:16.858+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('voiw1tanx6cuu9on5apz6ovo', 'post-b-07', 'm35n2u60pubvs9t826p6l3fk', 'r2c3xtv3fjygs84lo5odbkv7', NULL, 'POST', 'SINGLE', 'What actually addresses the fear that "doctors won''t try as hard to save a registered donor"?', NULL, 'The clinicians who determine death are independent of the transplant team. Pointing to that structural separation is far stronger than an assurance about professional character.', 'myths', 2, 'independent-teams', 18, '2026-08-18T19:36:16.860+00:00', '2026-08-18T19:36:16.860+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('criu18nbx9xn9rw4g3i8mlss', 'post-b-08', 'm35n2u60pubvs9t826p6l3fk', 'r2c3xtv3fjygs84lo5odbkv7', NULL, 'POST', 'SCENARIO', 'What is the best response?', 'Someone tells you their religion does not allow organ donation.', 'Accept their position and stay inside your competence. Save7''s goal is a family that has talked — a clearly communicated ''no'' is a good outcome, not a failure.', 'conversation', 2, 'responding-to-religion', 19, '2026-08-18T19:36:16.862+00:00', '2026-08-18T19:36:16.862+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('jaxy7ekwv8xdvnhchatgffea', 'post-b-09', 'm35n2u60pubvs9t826p6l3fk', 'r2c3xtv3fjygs84lo5odbkv7', NULL, 'POST', 'SCENARIO', 'What is the most useful thing to do first?', 'A family member says, quietly: "I don''t want doctors cutting me up after I''m dead."', 'This is almost never a factual objection — it is about dignity. Acknowledge the concern and find out what specifically worries them before offering any information. People who feel dismissed stop listening.', 'conversation', 2, 'conversation-emotion-first', 20, '2026-08-18T19:36:16.863+00:00', '2026-08-18T19:36:16.863+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('fje6xi8fh8p5qilkmo7c36k5', 'post-b-10', 'm35n2u60pubvs9t826p6l3fk', 'r2c3xtv3fjygs84lo5odbkv7', NULL, 'POST', 'SINGLE', 'According to Save7, what is the most important part of advocating for organ donation?', NULL, 'Whether it is for awareness campaigns or a private conversation with family and friends, the most important part is simply starting the conversation.', 'conversation', 1, 'family-conversation', 21, '2026-08-18T19:36:16.865+00:00', '2026-08-18T19:36:16.865+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('qxw1of5p61zifyq1ndos5ycl', 'post-i-01', 'm35n2u60pubvs9t826p6l3fk', 'kgbnni0rydlpooi38l348tp4', NULL, 'POST', 'SINGLE', 'Can this person be considered deceased?', 'A patient has been declared brain dead. Their heart is still beating because they are mechanically ventilated.', 'Yes. Brain death is death, determined by neurological criteria. The ventilator supplies oxygen the person can no longer obtain for themselves, which allows the heart to keep beating for a period after death has been determined.', 'brain-death', 2, 'brain-death-heart-beating', 22, '2026-08-18T19:36:16.866+00:00', '2026-08-18T19:36:16.866+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('f4e3i601i3ioi2p9kb1bvcgj', 'post-i-02', 'm35n2u60pubvs9t826p6l3fk', 'kgbnni0rydlpooi38l348tp4', NULL, 'POST', 'TRUE_FALSE', 'A person who is brain dead may later recover, as sometimes happens with a coma.', NULL, 'No. This is the distinction the module exists to establish. Recovery is possible from a coma; brain death is death.', 'brain-death', 2, 'brain-death-vs-coma', 23, '2026-08-18T19:36:16.867+00:00', '2026-08-18T19:36:16.867+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('ifivnsou94y3zm3n4hq01p0j', 'post-i-03', 'm35n2u60pubvs9t826p6l3fk', 'kgbnni0rydlpooi38l348tp4', NULL, 'POST', 'SINGLE', 'Why is independent medical assessment part of determining death?', NULL, 'It is a deliberate safeguard. The clinicians who determine death are independent of the transplant team, which removes any conflict of interest and is the direct answer to the most common public fear about donation.', 'determination-of-death', 2, 'independent-teams', 24, '2026-08-18T19:36:16.868+00:00', '2026-08-18T19:36:16.868+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('kxrrmrq6dh6nouymyj4awvtn', 'post-i-04', 'm35n2u60pubvs9t826p6l3fk', 'kgbnni0rydlpooi38l348tp4', NULL, 'POST', 'SINGLE', 'In the donation pathway, what comes immediately after consent?', NULL, 'Donor management follows consent: the donor is cared for so that the gift remains viable, before organ and tissue recovery takes place.', 'journey', 2, 'pathway-order', 25, '2026-08-18T19:36:16.871+00:00', '2026-08-18T19:36:16.871+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('bv4d0qe3a2q1onhovl5uvspt', 'post-i-05', 'm35n2u60pubvs9t826p6l3fk', 'kgbnni0rydlpooi38l348tp4', NULL, 'POST', 'SINGLE', 'Which best describes allocation?', NULL, 'Allocation is a matching process rather than a queue. It is not simply first-come-first-served, and prognostic assessment forms part of it.', 'journey', 2, 'allocation', 26, '2026-08-18T19:36:16.873+00:00', '2026-08-18T19:36:16.873+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('iwp9dfuxhlcitcpgmk15x2a3', 'post-i-06', 'm35n2u60pubvs9t826p6l3fk', 'kgbnni0rydlpooi38l348tp4', NULL, 'POST', 'SINGLE', 'Which of these roles exists primarily as a safeguard rather than to provide treatment?', NULL, 'The clinicians who determine death are independent of the transplant team specifically so that no conflict of interest can arise. Several other roles — translators, counsellors, faith representatives — exist to support the family and to protect the validity of consent.', 'who-is-involved', 2, 'team-safeguards', 27, '2026-08-18T19:36:16.874+00:00', '2026-08-18T19:36:16.874+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('nc6wdm4suua0qk65dyqlf3ol', 'post-i-07', 'm35n2u60pubvs9t826p6l3fk', 'kgbnni0rydlpooi38l348tp4', NULL, 'POST', 'SINGLE', 'Why is a translator''s role part of the consent safeguards rather than a courtesy?', NULL, 'Consent that is not understood is not consent. In a country with many languages, translation is often what makes a consent conversation genuinely informed.', 'who-is-involved', 2, 'consent-understood', 28, '2026-08-18T19:36:16.876+00:00', '2026-08-18T19:36:16.876+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('z9jyij6s1peb7eefpgf36yd4', 'post-i-08', 'm35n2u60pubvs9t826p6l3fk', 'kgbnni0rydlpooi38l348tp4', NULL, 'POST', 'SINGLE', 'Does this automatically exclude donation?', 'A potential donor has hypertension.', 'No. Suitability is determined through appropriate medical assessment at the time. Neither a confident exclusion nor a claim that the condition is irrelevant is accurate.', 'eligibility', 2, 'eligibility-comorbidity', 29, '2026-08-18T19:36:16.877+00:00', '2026-08-18T19:36:16.877+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('dwgfqhkgeqifzyqsvtujrdow', 'post-i-09', 'm35n2u60pubvs9t826p6l3fk', 'kgbnni0rydlpooi38l348tp4', NULL, 'POST', 'SINGLE', 'Someone is found to be unsuitable to donate one particular organ. What follows?', NULL, 'Assessment can be organ-specific. Being unsuitable for one donation does not mean being unsuitable for all of them.', 'eligibility', 2, 'eligibility-organ-specific', 30, '2026-08-18T19:36:16.878+00:00', '2026-08-18T19:36:16.878+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('tqipcs9try76gdn2wii0pi11', 'post-i-10', 'm35n2u60pubvs9t826p6l3fk', 'kgbnni0rydlpooi38l348tp4', NULL, 'POST', 'SINGLE', 'What single message about eligibility should an advocate always carry?', NULL, 'Do not automatically assume that someone cannot donate. Suitability is determined through appropriate medical assessment.', 'eligibility', 1, 'eligibility-age', 31, '2026-08-18T19:36:16.880+00:00', '2026-08-18T19:36:16.880+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('qlg7jnry1yli48hvkks2lsu3', 'post-i-11', 'm35n2u60pubvs9t826p6l3fk', 'kgbnni0rydlpooi38l348tp4', NULL, 'POST', 'SINGLE', 'Which is the most accurate description of organ and tissue recovery?', NULL, 'Recovery is a surgical procedure, carried out with the same care and respect as any other operation. Saying so directly answers the dignity concern that underlies many refusals.', 'journey', 1, 'recovery-respect', 32, '2026-08-18T19:36:16.881+00:00', '2026-08-18T19:36:16.881+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('s7pkuxxw2qnjum8nzthzsded', 'post-i-12', 'm35n2u60pubvs9t826p6l3fk', 'kgbnni0rydlpooi38l348tp4', NULL, 'POST', 'SCENARIO', 'What is the best way to respond?', 'A friend, upset, asks you how a hospital could say someone had died when the family could see the heart monitor beeping.', 'Acknowledge that the contradiction is a completely reasonable response to an unusual situation, then explain plainly what the ventilator is doing. Treating disbelief as ignorance loses the conversation immediately.', 'conversation', 3, 'explaining-brain-death', 33, '2026-08-18T19:36:16.883+00:00', '2026-08-18T19:36:16.883+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('g3airo0yuuvpf8yfp52gm4te', 'post-i-13', 'm35n2u60pubvs9t826p6l3fk', 'kgbnni0rydlpooi38l348tp4', NULL, 'POST', 'SINGLE', 'What best describes what a transplant means for the recipient?', NULL, 'The start of a lifelong medical journey involving ongoing medication and monitoring — not a cure. Describing it honestly is more persuasive than a happy ending.', 'after-transplant', 2, 'after-transplant', 34, '2026-08-18T19:36:16.884+00:00', '2026-08-18T19:36:16.884+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('u29m63tw5w9zfk2p97hirgyx', 'post-a-01', 'm35n2u60pubvs9t826p6l3fk', 'ddtjesv8e0f2lou2i4jbf81t', NULL, 'POST', 'SINGLE', 'Which statute is the primary legal framework for organ donation and transplantation in South Africa?', NULL, 'The National Health Act. Note that specific requirements under it must always be checked against current authoritative sources rather than an older study guide.', 'law', 2, 'law-primary-statute', 35, '2026-08-18T19:36:16.885+00:00', '2026-08-18T19:36:16.885+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('fqnhk79aqhi5d0napatjm9qa', 'post-a-02', 'm35n2u60pubvs9t826p6l3fk', 'ddtjesv8e0f2lou2i4jbf81t', NULL, 'POST', 'SINGLE', 'An advocate is asked whether a particular consent arrangement is allowed. Which distinction matters most in answering?', NULL, 'Educational explanation, legal requirement and clinical guidance are three different kinds of statement. An advocate who cannot separate them will eventually mislead someone — so say which one you are giving, and refer what you do not know.', 'advocacy-integrity', 3, 'separate-claim-types', 36, '2026-08-18T19:36:16.887+00:00', '2026-08-18T19:36:16.887+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('gb0ujlt43sd5ikuz0cnw7z3i', 'post-a-03', 'm35n2u60pubvs9t826p6l3fk', 'ddtjesv8e0f2lou2i4jbf81t', NULL, 'POST', 'SINGLE', 'Why do unnatural deaths add complexity to a potential donation?', NULL, 'They bring additional legal requirements and additional people into the process, including forensic authorities such as the state pathologist or district surgeon. The specific requirements must be verified against current sources.', 'law', 2, 'law-unnatural-death', 37, '2026-08-18T19:36:16.888+00:00', '2026-08-18T19:36:16.888+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('jfdf0hn9xdx10id3y0civ6c1', 'post-a-04', 'm35n2u60pubvs9t826p6l3fk', 'ddtjesv8e0f2lou2i4jbf81t', NULL, 'POST', 'SINGLE', 'Which statement about contraindications to heart transplantation is most accurate?', NULL, 'Most are relative rather than absolute, and several have changed substantially as evidence and practice have moved. This is the strongest reason for advocates to avoid stating exclusion rules confidently in public.', 'transplant-landscape', 3, 'eligibility-comorbidity', 38, '2026-08-18T19:36:16.890+00:00', '2026-08-18T19:36:16.890+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('jdyfybovgai4kbk301c070ja', 'post-a-05', 'm35n2u60pubvs9t826p6l3fk', 'ddtjesv8e0f2lou2i4jbf81t', NULL, 'POST', 'SINGLE', 'Why does mechanical circulatory support matter when discussing advanced heart failure?', NULL, 'It means transplantation is not always the only option in advanced heart failure, which complicates any simple framing of transplant as the single available answer.', 'transplant-landscape', 3, 'mcs-alternative', 39, '2026-08-18T19:36:16.891+00:00', '2026-08-18T19:36:16.891+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('sfifmkz5ny8e80nohkcxar82', 'post-a-06', 'm35n2u60pubvs9t826p6l3fk', 'ddtjesv8e0f2lou2i4jbf81t', NULL, 'POST', 'SINGLE', 'Why is "the sickest patient goes first" an inadequate description of allocation?', NULL, 'Prognostic assessment forms part of allocation: the question is not only how ill someone is now, but what outcome a transplant is likely to achieve. It is a matching process, not a queue ordered by severity.', 'transplant-landscape', 3, 'allocation', 40, '2026-08-18T19:36:16.893+00:00', '2026-08-18T19:36:16.893+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('vs5a2tt118q37xc0rne2wdxt', 'post-a-07', 'm35n2u60pubvs9t826p6l3fk', 'ddtjesv8e0f2lou2i4jbf81t', NULL, 'POST', 'SINGLE', 'Which best describes immunosuppression after transplantation?', NULL, 'It prevents rejection but carries its own risks. It is a trade-off rather than a fix, and describing it that way is more honest than presenting a transplant as a clean solution.', 'after-transplant', 2, 'immunosuppression-tradeoff', 41, '2026-08-18T19:36:16.894+00:00', '2026-08-18T19:36:16.894+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('f8io3lxx4m5p1365r2e11gaf', 'post-a-08', 'm35n2u60pubvs9t826p6l3fk', 'ddtjesv8e0f2lou2i4jbf81t', NULL, 'POST', 'TRUE_FALSE', 'An episode of rejection always means the recipient will lose the transplanted organ.', NULL, 'No. Rejection is monitored for and is often treatable. It does not automatically mean losing the graft.', 'after-transplant', 2, 'rejection-treatable', 42, '2026-08-18T19:36:16.895+00:00', '2026-08-18T19:36:16.895+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('d3msxm6g3xw2ymd8k5o050uj', 'post-a-09', 'm35n2u60pubvs9t826p6l3fk', 'ddtjesv8e0f2lou2i4jbf81t', NULL, 'POST', 'SINGLE', 'Why does the course insist on describing transplantation honestly rather than optimistically?', NULL, 'Overselling transplantation damages credibility and misrepresents recipients'' actual lives. A transplant trades one serious medical situation for another, usually far better, one — and saying so plainly is more persuasive than a happy ending.', 'after-transplant', 2, 'after-transplant', 43, '2026-08-18T19:36:16.896+00:00', '2026-08-18T19:36:16.896+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('q87hk9593cp9iasr4br2v24w', 'post-a-10', 'm35n2u60pubvs9t826p6l3fk', 'ddtjesv8e0f2lou2i4jbf81t', NULL, 'POST', 'SCENARIO', 'As a Save7 advocate, what is the best thing you can do?', 'At a bedside, a family says: "She''s still warm. Her heart is beating. You''re asking us to give up on her."', 'Acknowledge the reality of what they are experiencing, reject the framing of ''giving up'', then make space — and connect them to the clinical team or their own faith community. This is a clinical and counselling conversation, not an advocacy one.', 'conversation', 3, 'family-bedside-grief', 44, '2026-08-18T19:36:16.898+00:00', '2026-08-18T19:36:16.898+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('cj12h6povq85x9o1crge5sm3', 'post-a-11', 'm35n2u60pubvs9t826p6l3fk', 'ddtjesv8e0f2lou2i4jbf81t', NULL, 'POST', 'SCENARIO', 'What is the best response?', 'A community member says: "People like us don''t get organs. We only give them."', 'Mistrust grounded in real inequity is not a myth and cannot be corrected like one. Take the concern seriously, listen to what they have actually seen, and be honest that inequity in healthcare access is a real problem. Conceding that is what makes anything else you say believable.', 'conversation', 3, 'mistrust-equity', 45, '2026-08-18T19:36:16.899+00:00', '2026-08-18T19:36:16.899+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('v31d9th3bdmqr8sbtnbpe4n8', 'post-a-12', 'm35n2u60pubvs9t826p6l3fk', 'ddtjesv8e0f2lou2i4jbf81t', NULL, 'POST', 'SCENARIO', 'What is the best response?', 'An older relative says: "My body needs to be whole when it''s buried. That''s not negotiable for me."', 'Accept the settled position gracefully, and ask whether they have told the family so nobody has to guess. A clearly communicated ''no'' is a good outcome for Save7 — the failure mode is a family left guessing.', 'conversation', 3, 'responding-to-religion', 46, '2026-08-18T19:36:16.901+00:00', '2026-08-18T19:36:16.901+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('dn295a036j81no6bwec7vpdf', 'post-a-13', 'm35n2u60pubvs9t826p6l3fk', 'ddtjesv8e0f2lou2i4jbf81t', NULL, 'POST', 'SCENARIO', 'What should you do?', 'At a Save7 event, someone asks: "How many organs actually get transplanted in South Africa each year?" You are not certain of the current figure.', 'Say you would rather not give a number you are not sure of, and offer to get the current figure from an authoritative source. A half-remembered statistic becomes the thing they repeat — and the caveat does not travel with it.', 'advocacy-integrity', 2, 'dont-guess-statistics', 47, '2026-08-18T19:36:16.903+00:00', '2026-08-18T19:36:16.903+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('xvx590uaf9f8d277hvrmp1tt', 'post-a-14', 'm35n2u60pubvs9t826p6l3fk', 'ddtjesv8e0f2lou2i4jbf81t', NULL, 'POST', 'SCENARIO', 'What is the best thing you can do?', 'Two siblings begin arguing in front of you about whether their late father ever said he wanted to donate.', 'Refuse to arbitrate, remove any time pressure you have no business applying, and offer a shared source of information so both siblings hear the same thing. Taking a side inside a grieving family fractures the conversation entirely.', 'conversation', 3, 'not-a-counsellor', 48, '2026-08-18T19:36:16.905+00:00', '2026-08-18T19:36:16.905+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('a8gdhiap5zycforxyml8hxnz', 'post-a-15', 'm35n2u60pubvs9t826p6l3fk', 'ddtjesv8e0f2lou2i4jbf81t', NULL, 'POST', 'SINGLE', 'Which best describes the limits of a Save7 advocate''s role?', NULL, 'You are not a counsellor and not a clinician. Recognising when a conversation has moved beyond your role — and stopping, or referring — is a skill rather than a failure.', 'advocacy-integrity', 2, 'limits-of-role', 49, '2026-08-18T19:36:16.906+00:00', '2026-08-18T19:36:16.906+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('xzp0astk7a5fsoovgsi3ex80', 'chk-m1-01', 'm35n2u60pubvs9t826p6l3fk', NULL, 'o4uhyh92co3dakkj9jkz66ra', 'CHECK', 'SINGLE', 'What does end-stage organ failure mean?', NULL, 'The organ has failed to the point where it can no longer sustain its function, and cannot be repaired. For some conditions, transplantation is the only remaining option.', 'who-needs-organs', 1, NULL, 50, '2026-08-18T19:36:16.908+00:00', '2026-08-18T19:36:16.908+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('d0ys9mv5ln7d0ooytlk7n9kp', 'chk-m1-02', 'm35n2u60pubvs9t826p6l3fk', NULL, 'o4uhyh92co3dakkj9jkz66ra', 'CHECK', 'MULTI', 'Which of these are tissue donations? Select all that apply.', NULL, 'Corneas, skin, bone and ligaments, and heart valves are all transplanted as tissue.', 'what-can-be-donated', 1, NULL, 51, '2026-08-18T19:36:16.909+00:00', '2026-08-18T19:36:16.909+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('vd3u8iwcwcl2raz47kc47xfe', 'chk-m1-03', 'm35n2u60pubvs9t826p6l3fk', NULL, 'o4uhyh92co3dakkj9jkz66ra', 'CHECK', 'SINGLE', 'Where does Save7''s name come from?', NULL, 'One donor can help several people — one decision can save seven lives.', 'what-can-be-donated', 1, NULL, 52, '2026-08-18T19:36:16.910+00:00', '2026-08-18T19:36:16.910+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('f9g13zfwq763buqetz6fdcnf', 'chk-m2-01', 'm35n2u60pubvs9t826p6l3fk', NULL, 'fy5gk5lj0glyc8cimfs0iamm', 'CHECK', 'SINGLE', 'Which is the largest preventable loss point in the donation pathway?', NULL, 'Family refusal, and it is the loss point most directly changed by a family having discussed donation in advance.', 'loss-points', 1, NULL, 53, '2026-08-18T19:36:16.911+00:00', '2026-08-18T19:36:16.911+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('hykneun9oeskan9z9ouvnpus', 'chk-m2-02', 'm35n2u60pubvs9t826p6l3fk', NULL, 'fy5gk5lj0glyc8cimfs0iamm', 'CHECK', 'SINGLE', 'Why is it useful to understand why a myth persists, rather than just knowing it is false?', NULL, 'Understanding why a belief is persuasive is what lets you respond to it well. People who feel dismissed stop listening.', 'loss-points', 2, NULL, 54, '2026-08-18T19:36:16.912+00:00', '2026-08-18T19:36:16.912+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('s0q7b17owbzeqzagjxoc71ej', 'chk-m2-03', 'm35n2u60pubvs9t826p6l3fk', NULL, 'fy5gk5lj0glyc8cimfs0iamm', 'CHECK', 'TRUE_FALSE', 'Most points at which donations are lost are medical or surgical rather than human.', NULL, 'The opposite. Most loss points are human — awareness, myths, fear, and families never having discussed donation.', 'loss-points', 1, NULL, 55, '2026-08-18T19:36:16.914+00:00', '2026-08-18T19:36:16.914+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('oualy7r7n7lzl2s8uejn064o', 'chk-m3-01', 'm35n2u60pubvs9t826p6l3fk', NULL, 'utdb2izuy72czxajhg7r2o23', 'CHECK', 'SINGLE', 'What are the two main routes to deceased donation?', NULL, 'Donation after brain death, and donation after circulatory death. Each has its own requirements.', 'routes-to-donation', 1, NULL, 56, '2026-08-18T19:36:16.915+00:00', '2026-08-18T19:36:16.915+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('yvetgouvqelri6yl6r9hbwgt', 'chk-m3-02', 'm35n2u60pubvs9t826p6l3fk', NULL, 'utdb2izuy72czxajhg7r2o23', 'CHECK', 'SINGLE', 'Which organ is most commonly donated by a living donor?', NULL, 'A kidney. Living donation is possible for some organs, most commonly a kidney.', 'routes-to-donation', 1, NULL, 57, '2026-08-18T19:36:16.916+00:00', '2026-08-18T19:36:16.916+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('r2722bfblh6gcigwyu2snfwc', 'chk-m3-03', 'm35n2u60pubvs9t826p6l3fk', NULL, 'utdb2izuy72czxajhg7r2o23', 'CHECK', 'SINGLE', 'What makes a registered wish actionable in practice?', NULL, 'Registration signals your wishes; telling your family is what makes them actionable.', 'family-conversation', 1, NULL, 58, '2026-08-18T19:36:16.918+00:00', '2026-08-18T19:36:16.918+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('r71pteltkylv6vegsxa2k1wi', 'chk-m4-01', 'm35n2u60pubvs9t826p6l3fk', NULL, 'q65o68xry6cy2gq2zuqz7aru', 'CHECK', 'SINGLE', 'What is the purpose of this module?', NULL, 'Not to teach you to win arguments. People who feel argued with dig in; people who feel heard reconsider.', 'conversation', 1, NULL, 59, '2026-08-18T19:36:16.919+00:00', '2026-08-18T19:36:16.919+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('u7nms702gd4810qitngi1m0q', 'chk-m4-02', 'm35n2u60pubvs9t826p6l3fk', NULL, 'q65o68xry6cy2gq2zuqz7aru', 'CHECK', 'SINGLE', 'Why is asking permission before offering information effective?', NULL, 'It turns a correction into a conversation, and it stops the other person feeling talked down to.', 'conversation', 2, NULL, 60, '2026-08-18T19:36:16.920+00:00', '2026-08-18T19:36:16.920+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('t8k9vo1j87gvojv8um9qofed', 'chk-m4-03', 'm35n2u60pubvs9t826p6l3fk', NULL, 'q65o68xry6cy2gq2zuqz7aru', 'CHECK', 'SINGLE', 'Why is "I don''t know, let me find out" a good answer?', NULL, 'It protects your credibility and the possibility of the next conversation. A confident guess does the opposite.', 'conversation', 2, NULL, 61, '2026-08-18T19:36:16.922+00:00', '2026-08-18T19:36:16.922+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('zhqa1bu9rlnifcucjt7jbpr2', 'chk-m4-04', 'm35n2u60pubvs9t826p6l3fk', NULL, 'q65o68xry6cy2gq2zuqz7aru', 'CHECK', 'SINGLE', 'Someone decides against donation but tells their family clearly. From Save7''s perspective, what is this?', NULL, 'A good outcome. The goal is a family that has talked, not a converted donor. The failure mode is a family left guessing.', 'conversation', 2, NULL, 62, '2026-08-18T19:36:16.923+00:00', '2026-08-18T19:36:16.923+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('h4yit2sa79dqbly087yhw0ua', 'chk-m5-01', 'm35n2u60pubvs9t826p6l3fk', NULL, 'pn0m2s6lc0yqqeb8jvf9k3hn', 'CHECK', 'SINGLE', 'What happens during donor management?', NULL, 'The donor is cared for so that the gift remains viable — a real and skilled stage of care between consent and recovery.', 'journey', 2, NULL, 63, '2026-08-18T19:36:16.924+00:00', '2026-08-18T19:36:16.924+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('ao6nx9o1y5xjbu2ynocq69nx', 'chk-m5-02', 'm35n2u60pubvs9t826p6l3fk', NULL, 'pn0m2s6lc0yqqeb8jvf9k3hn', 'CHECK', 'SINGLE', 'Which stage comes last in the pathway?', NULL, 'Life after transplant — for the recipient, the beginning of a lifelong medical journey.', 'journey', 2, NULL, 64, '2026-08-18T19:36:16.926+00:00', '2026-08-18T19:36:16.926+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('dndxudg8qs1zpxhwfoj9z6dz', 'chk-m5-03', 'm35n2u60pubvs9t826p6l3fk', NULL, 'pn0m2s6lc0yqqeb8jvf9k3hn', 'CHECK', 'TRUE_FALSE', 'A donation is best understood as a single event at one moment in time.', NULL, 'It is a coordinated chain of events running over hours and involving many people, most of whom never meet each other.', 'journey', 1, NULL, 65, '2026-08-18T19:36:16.927+00:00', '2026-08-18T19:36:16.927+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('ecrt87dnp2ie7pph3r1caa4q', 'chk-m6-01', 'm35n2u60pubvs9t826p6l3fk', NULL, 'dupcdrukzkq2wdzrh2ehhee8', 'CHECK', 'SINGLE', 'What is the single most important distinction in this module?', NULL, 'Brain death is not a coma, and not simply being unconscious. It is death, determined by neurological criteria.', 'brain-death', 2, NULL, 66, '2026-08-18T19:36:16.928+00:00', '2026-08-18T19:36:16.928+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('nxwxokcqjobufsa2zzufxd3p', 'chk-m6-02', 'm35n2u60pubvs9t826p6l3fk', NULL, 'dupcdrukzkq2wdzrh2ehhee8', 'CHECK', 'SINGLE', 'Why are the clinicians who determine death independent of the transplant team?', NULL, 'It is a designed safeguard against any conflict of interest, and it is the direct answer to the fear that doctors might not try as hard to save a registered donor.', 'determination-of-death', 2, NULL, 67, '2026-08-18T19:36:16.929+00:00', '2026-08-18T19:36:16.929+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('lzmym1apzx9owdnlstm6kijf', 'chk-m6-03', 'm35n2u60pubvs9t826p6l3fk', NULL, 'dupcdrukzkq2wdzrh2ehhee8', 'CHECK', 'SINGLE', 'A family at the bedside cannot accept that their relative has died. How should you regard that?', NULL, 'As a reasonable human response to an unusual situation, not as ignorance. Treating it as ignorance loses the conversation immediately.', 'conversation', 2, NULL, 68, '2026-08-18T19:36:16.931+00:00', '2026-08-18T19:36:16.931+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('f4o3dk8k5kdziidbjq1eoc5e', 'chk-m7-01', 'm35n2u60pubvs9t826p6l3fk', NULL, 'igmbm623gsgsydnrkwvvht7l', 'CHECK', 'SINGLE', 'Who coordinates the donation process as a whole?', NULL, 'The transplant coordinator, from referral through to recovery.', 'who-is-involved', 1, NULL, 69, '2026-08-18T19:36:16.932+00:00', '2026-08-18T19:36:16.932+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('ztvxnseycnaq6i1ek71lxhen', 'chk-m7-02', 'm35n2u60pubvs9t826p6l3fk', NULL, 'igmbm623gsgsydnrkwvvht7l', 'CHECK', 'MULTI', 'Which roles exist primarily to support the family? Select all that apply.', NULL, 'Counsellors, translators and faith representatives all exist to support the family and, in the case of translators, to protect the validity of consent.', 'who-is-involved', 2, NULL, 70, '2026-08-18T19:36:16.933+00:00', '2026-08-18T19:36:16.933+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('ajno0wqag1b244jaotvoc2zv', 'chk-m7-03', 'm35n2u60pubvs9t826p6l3fk', NULL, 'igmbm623gsgsydnrkwvvht7l', 'CHECK', 'SINGLE', 'Which organisation is South Africa''s professional body for transplant coordinators?', NULL, 'The South African Transplant Coordinators Society (SATCS).', 'who-is-involved', 1, NULL, 71, '2026-08-18T19:36:16.935+00:00', '2026-08-18T19:36:16.935+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('qhi4fnzpvc4f52ffinai9n9h', 'chk-m8-01', 'm35n2u60pubvs9t826p6l3fk', NULL, 'fdyb9a50o4n2x8pqvks17blp', 'CHECK', 'SINGLE', 'What is this module''s central message?', NULL, 'Do not assume someone cannot donate. Suitability is determined through appropriate medical assessment at the time.', 'eligibility', 1, NULL, 72, '2026-08-18T19:36:16.936+00:00', '2026-08-18T19:36:16.936+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('sc1pcypxw1hk8swqtqp2yf7a', 'chk-m8-02', 'm35n2u60pubvs9t826p6l3fk', NULL, 'fdyb9a50o4n2x8pqvks17blp', 'CHECK', 'SINGLE', 'Why does the course avoid giving advocates a list of exclusion criteria?', NULL, 'Simple exclusion rules are frequently wrong and change as practice changes, and a confident wrong answer from an advocate can permanently remove a potential donor.', 'eligibility', 2, NULL, 73, '2026-08-18T19:36:16.937+00:00', '2026-08-18T19:36:16.937+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('fhy3rrgejmmi1ow4li8fhf1p', 'chk-m8-03', 'm35n2u60pubvs9t826p6l3fk', NULL, 'fdyb9a50o4n2x8pqvks17blp', 'CHECK', 'SINGLE', 'Why is "that condition makes no difference at all" a poor answer?', NULL, 'It is an overcorrection. Claiming a factor is irrelevant is as inaccurate as claiming it disqualifies, and it damages credibility when someone checks.', 'eligibility', 2, NULL, 74, '2026-08-18T19:36:16.939+00:00', '2026-08-18T19:36:16.939+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('a2qqu1fbrgw4sn2l3rad6skm', 'chk-m9-01', 'm35n2u60pubvs9t826p6l3fk', NULL, 'tnvu4480yubmdf54pi8nhoie', 'CHECK', 'SINGLE', 'Which three kinds of statement must an advocate keep distinct?', NULL, 'Educational explanation, legal requirement and clinical guidance. Tangling them is how advocates end up misleading people.', 'law', 2, NULL, 75, '2026-08-18T19:36:16.940+00:00', '2026-08-18T19:36:16.940+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('mx1zmu3jpxztd9qxprgmsh8t', 'chk-m9-02', 'm35n2u60pubvs9t826p6l3fk', NULL, 'tnvu4480yubmdf54pi8nhoie', 'CHECK', 'SINGLE', 'Why should an old study guide not be treated as legally current?', NULL, 'Legal requirements change. Anything legal must be verified against current authoritative sources before it is presented as fact.', 'law', 2, NULL, 76, '2026-08-18T19:36:16.942+00:00', '2026-08-18T19:36:16.942+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('kyym9ak8so9km63h6cgh758b', 'chk-m9-03', 'm35n2u60pubvs9t826p6l3fk', NULL, 'tnvu4480yubmdf54pi8nhoie', 'CHECK', 'SINGLE', 'What additional element does an unnatural death introduce?', NULL, 'Additional legal requirements, and forensic authorities such as the state pathologist or district surgeon.', 'law', 2, NULL, 77, '2026-08-18T19:36:16.943+00:00', '2026-08-18T19:36:16.943+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('bxzw0z1d65t1ovm01n0t06pr', 'chk-m10-01', 'm35n2u60pubvs9t826p6l3fk', NULL, 'gkh2ea7yygxftemfrwmx9nac', 'CHECK', 'SINGLE', 'Who decides whether someone is a transplant candidate?', NULL, 'A specialist multidisciplinary team, applying judgement rather than a checklist.', 'transplant-landscape', 3, NULL, 78, '2026-08-18T19:36:16.944+00:00', '2026-08-18T19:36:16.944+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('s7t7846kaxv9ojuefdcwbitn', 'chk-m10-02', 'm35n2u60pubvs9t826p6l3fk', NULL, 'gkh2ea7yygxftemfrwmx9nac', 'CHECK', 'TRUE_FALSE', 'Contraindications to transplantation are fixed and have not changed over time.', NULL, 'They are largely relative rather than absolute, and several have changed substantially as evidence and practice have moved.', 'transplant-landscape', 3, NULL, 79, '2026-08-18T19:36:16.946+00:00', '2026-08-18T19:36:16.946+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('fv7bqe53w74fqydj2scx6l2q', 'chk-m10-03', 'm35n2u60pubvs9t826p6l3fk', NULL, 'gkh2ea7yygxftemfrwmx9nac', 'CHECK', 'SINGLE', 'What practical lesson should an advocate draw from this module?', NULL, 'Because selection is complex and changing, avoid stating exclusion rules confidently in public. Understanding the shape of the decision is enough.', 'advocacy-integrity', 2, NULL, 80, '2026-08-18T19:36:16.947+00:00', '2026-08-18T19:36:16.947+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('xw1bpzjftxwvh0vb0l17sokl', 'chk-m11-01', 'm35n2u60pubvs9t826p6l3fk', NULL, 'rqbcwtid9j9vbik6cabq6v8p', 'CHECK', 'SINGLE', 'What does immunosuppression do?', NULL, 'It reduces the risk of the body rejecting the graft, at the cost of its own risks. A trade-off rather than a fix.', 'after-transplant', 2, NULL, 81, '2026-08-18T19:36:16.948+00:00', '2026-08-18T19:36:16.948+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('te3mg8d87xx4rzakuhk42lll', 'chk-m11-02', 'm35n2u60pubvs9t826p6l3fk', NULL, 'rqbcwtid9j9vbik6cabq6v8p', 'CHECK', 'SINGLE', 'Why is follow-up lifelong after a transplant?', NULL, 'Because a transplant is an ongoing medical situation requiring continued medication and monitoring, not a completed repair.', 'after-transplant', 2, NULL, 82, '2026-08-18T19:36:16.949+00:00', '2026-08-18T19:36:16.949+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('mv85dolaleb9wd7cxy7smdhs', 'chk-m11-03', 'm35n2u60pubvs9t826p6l3fk', NULL, 'rqbcwtid9j9vbik6cabq6v8p', 'CHECK', 'SINGLE', 'How should an advocate describe transplantation?', NULL, 'Honestly. A transplant trades one serious medical situation for another, usually far better, one — and saying so is more persuasive than a happy ending.', 'advocacy-integrity', 2, NULL, 83, '2026-08-18T19:36:16.951+00:00', '2026-08-18T19:36:16.951+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('jojxorjo7y081fntedp6nvy4', 'chk-m12-01', 'm35n2u60pubvs9t826p6l3fk', NULL, 'auptjr9yc0gqtaxqy34509lv', 'CHECK', 'SINGLE', 'What is the most valuable thing an advocate can do at a grieving bedside?', NULL, 'Not make it worse. This is a clinical and counselling conversation; acknowledgement and silence are legitimate contributions.', 'conversation', 3, NULL, 84, '2026-08-18T19:36:16.952+00:00', '2026-08-18T19:36:16.952+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('khoii652oioaiebbyybjxp3m', 'chk-m12-02', 'm35n2u60pubvs9t826p6l3fk', NULL, 'auptjr9yc0gqtaxqy34509lv', 'CHECK', 'SINGLE', 'Why can mistrust rooted in inequity not be handled like a myth?', NULL, 'Because it may be grounded in real experience. Labelling it a misconception dismisses that experience and ends the conversation.', 'conversation', 3, NULL, 85, '2026-08-18T19:36:16.953+00:00', '2026-08-18T19:36:16.953+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('jauxjmh0kj1oijsnpdkqjtnh', 'chk-m12-03', 'm35n2u60pubvs9t826p6l3fk', NULL, 'auptjr9yc0gqtaxqy34509lv', 'CHECK', 'SINGLE', 'Why should you never negotiate around a stated conviction?', NULL, 'It signals you did not accept their answer the first time, and it costs you the relationship that makes any future conversation possible.', 'conversation', 2, NULL, 86, '2026-08-18T19:36:16.955+00:00', '2026-08-18T19:36:16.955+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('ysgy4jj0j2eocfccpl4zd0z5', 'chk-m12-04', 'm35n2u60pubvs9t826p6l3fk', NULL, 'auptjr9yc0gqtaxqy34509lv', 'CHECK', 'SINGLE', 'Having completed this module, what does the FACTS strategy qualify you to do?', NULL, 'Nothing operational. FACTS is a clinical strategy for transplant procurement coordinators. Understanding why it is structured as it is makes you a better advocate; it does not make you a consent-requester, and approaching a donor family is not an advocate''s role.', 'conversation', 2, NULL, 87, '2026-08-18T19:36:16.956+00:00', '2026-08-18T19:36:16.956+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('kd1zky8c63a2raan514z07ll', 'chk-m12-05', 'm35n2u60pubvs9t826p6l3fk', NULL, 'auptjr9yc0gqtaxqy34509lv', 'CHECK', 'SINGLE', 'FACTS builds in two deliberate time-out breaks. Why?', NULL, 'Processing a death, and then deciding as a family, both take time and neither happens well under observation. The pauses are part of the method rather than gaps in it.', 'conversation', 3, NULL, 88, '2026-08-18T19:36:16.957+00:00', '2026-08-18T19:36:16.957+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('uzmcxmav3kbvy83yuwzmjsnp', 'chk-m13-01', 'm35n2u60pubvs9t826p6l3fk', NULL, 'xz0cbqav6esbaiht4u74dsj6', 'CHECK', 'SINGLE', 'What is the one action this course asks you to take?', NULL, 'Talk to your own family, and tell them what you would want. Every module exists to make that sentence possible.', 'conversation', 1, NULL, 89, '2026-08-18T19:36:16.959+00:00', '2026-08-18T19:36:16.959+00:00');
INSERT INTO "Question" ("id", "authoringKey", "courseId", "levelId", "moduleId", "scope", "kind", "prompt", "scenario", "explanation", "topicTag", "difficulty", "pairKey", "order", "createdAt", "updatedAt") VALUES ('id6dq1y6qt3mvftqrkhr82h8', 'chk-m13-02', 'm35n2u60pubvs9t826p6l3fk', NULL, 'xz0cbqav6esbaiht4u74dsj6', 'CHECK', 'SINGLE', 'Complete the Save7 position: whether for campaigns or a private conversation, the most important part is…', NULL, '…simply starting the conversation.', 'conversation', 1, NULL, 90, '2026-08-18T19:36:16.960+00:00', '2026-08-18T19:36:16.960+00:00');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('c3jgsn3dlu3hgijbv9ebd60c', 'i0cq56gvr1cq5t4p4fcj2gle', 0, 'Their organ has failed completely and cannot be repaired', 1, 'Correct. This is what end-stage organ failure means.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('nuimr8m4j0w9175baj1wijku', 'i0cq56gvr1cq5t4p4fcj2gle', 1, 'To improve the performance of a healthy organ', 0, 'Transplantation is not an enhancement — it treats organs that have failed.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('g7wwwyn79tio6ge8ipjfpis2', 'i0cq56gvr1cq5t4p4fcj2gle', 2, 'Because they have chosen a transplant over medication', 0, 'Transplantation is not usually an alternative someone simply prefers; it is what remains when other treatment cannot sustain the organ''s function.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('esz17cghzs46p7cdw41dgim3', 'i0cq56gvr1cq5t4p4fcj2gle', 3, 'Only after a serious accident', 0, 'Accidents are one route to organ failure, but most transplant recipients have a chronic disease.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('xslloe2f271p8lkqmugnlxn8', 'ew0kwpq1walqoqrjjq9o90i9', 0, 'Kidneys', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('nky77fplza5cske207x6e83a', 'ew0kwpq1walqoqrjjq9o90i9', 1, 'Corneas', 1, 'Corneal donation restores sight and is one of the most commonly performed tissue transplants.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('f463fcg3yh69toyzmya3q94s', 'ew0kwpq1walqoqrjjq9o90i9', 2, 'Skin', 1, 'Donated skin is used in the treatment of severe burns.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('ofcbh29127hnt9rfrqsyeik7', 'ew0kwpq1walqoqrjjq9o90i9', 3, 'Heart valves', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('nsj9il7mlijpb5r3n37rtyym', 'ew0kwpq1walqoqrjjq9o90i9', 4, 'Brain tissue', 0, 'The brain is not transplanted.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('we3jcv54nug9n46opzfzb0h6', 'gc5v8wumuzbp4p5i883tkhnw', 0, 'Donations are lost at several human points along the pathway, especially family refusal and never having discussed donation', 1, 'Correct. This is the central argument of the course.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('t6raknyz80ge8gnjite2lqo5', 'gc5v8wumuzbp4p5i883tkhnw', 1, 'South Africa lacks the surgical skill to perform transplants', 0, 'South Africa has a long and distinguished transplant history. Surgical capability is not the primary constraint.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('pipf9ev7xj6h23jby986jq6h', 'gc5v8wumuzbp4p5i883tkhnw', 2, 'There are very few people who die in circumstances where donation is possible', 0, 'Potential donors exist. The problem is that potential donations are lost along the pathway.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('keg31p7ukvz98hr8fux41352', 'gc5v8wumuzbp4p5i883tkhnw', 3, 'The law prohibits most organ donation', 0, 'Donation is lawful in South Africa. Module 9 covers the legal framework.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('ub23e1th4f8z7y7qpdp5ql97', 'i4wbtaxmx2yxyxu508f0a9l6', 0, 'Telling your family what you want', 1, 'Correct. This single act is what Save7 exists to encourage.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('p7ck1lx979ggx2b4l4i6n6x0', 'i4wbtaxmx2yxyxu508f0a9l6', 1, 'Carrying a donor card at all times', 0, 'Helpful, but a card cannot have a conversation with your family on your behalf.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('zbkbqgv40evh4b7e378maeew', 'i4wbtaxmx2yxyxu508f0a9l6', 2, 'Registering a second time to be sure', 0, 'Registering again adds nothing. Talking to your family does.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('a1rpdfgn83kpkd907cpdvugh', 'i4wbtaxmx2yxyxu508f0a9l6', 3, 'Nothing — registration is legally sufficient on its own', 0, 'In practice families are involved, and a family that does not know your wishes has to guess.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('jrn69qhlhx2p4urbb8tdpnur', 'i1ujm2hgjh4htv6u3beez53s', 0, 'True', 0, 'This is the misconception the course works hardest to correct. Module 6 covers the distinction in detail.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('eyk6k5mxa6zls4sogl5sfuko', 'i1ujm2hgjh4htv6u3beez53s', 1, 'False', 1, 'Correct. Brain death is death; a coma is not.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('iwi21fn4agjfoin7qbhof3r8', 'ird92twae93b1u3y4mz5mf16', 0, 'A ventilator is supplying oxygen the person can no longer obtain for themselves', 1, 'Correct, and this is the explanation you will most often be asked to give.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('f1rx2n91jkvwwo8dg0p3evrb', 'ird92twae93b1u3y4mz5mf16', 1, 'The declaration is provisional and may be reversed', 0, 'Determination of death is not provisional. It follows a defined process with deliberate safeguards.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('nuhvq4pqcfjny150il0ersvp', 'ird92twae93b1u3y4mz5mf16', 2, 'The heart has its own separate brain', 0, 'No.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('q7utmor9z3t7h69pg7sjwhr3', 'ird92twae93b1u3y4mz5mf16', 3, 'It cannot — a beating heart always means the person is alive', 0, 'This is precisely the misconception that stops donation conversations. Module 6 addresses it.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('gm78mvh4ba3rmnqhbgo1gg7a', 'k3lnfqggi4euuhmnofpstrm8', 0, 'The clinicians who determine death are independent of the transplant team', 1, 'Correct. A structural safeguard is far more reassuring than an assurance about good intentions.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('x6oaw1cd37les7lim0de58bo', 'k3lnfqggi4euuhmnofpstrm8', 1, 'Doctors take an oath, so they would never do that', 0, 'An appeal to professional character. It does not explain what actually prevents the conflict, and it invites argument.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('vwoy64nxsn71w0wvmuhowgvk', 'k3lnfqggi4euuhmnofpstrm8', 2, 'Hospitals are not told who is a registered donor', 0, 'Do not offer reassurance you cannot support. The honest answer is the independence of the teams.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('qk7hm6tpw1mw4h7vgmzph2si', 'k3lnfqggi4euuhmnofpstrm8', 3, 'It is illegal, so it does not happen', 0, 'Legality alone does not explain the safeguard, and it sidesteps the fear being expressed.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('gv0vaxq5324t51eyfaixrkjy', 'qx7cpqwv1wq23ufsfk9ab0du', 0, 'Don''t rule yourself out — suitability is assessed individually by medical teams', 1, 'Correct. This is the accurate answer and the one Save7 asks advocates to use.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('ugvdd3i4dvgy9w7t8oe2iuwp', 'qx7cpqwv1wq23ufsfk9ab0du', 1, 'Yes, there is an upper age limit for donation', 0, 'Stating a confident exclusion rule can permanently remove a potential donor. Suitability is assessed individually.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('nnjg3g77pq2g9f3fu71k3nkx', 'qx7cpqwv1wq23ufsfk9ab0du', 2, 'No, age is completely irrelevant to donation', 0, 'Overcorrection. Claiming a factor is irrelevant is as inaccurate as claiming it disqualifies, and it damages credibility.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('d7i4q4tvh2w6oa8r5vpy97ot', 'qx7cpqwv1wq23ufsfk9ab0du', 3, 'Only for tissue donation, not organs', 0, 'This invents a rule. The honest answer is that suitability is individually assessed.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('cpqigtu98fz59k04hv1rw0rp', 'fcn3kz2rx5ttfjlvxsfil07n', 0, 'Suitability is assessed individually at the time, and can differ between organs', 1, 'Correct.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('zd9kd24runmu0tybgh7z8z1k', 'fcn3kz2rx5ttfjlvxsfil07n', 1, 'A fixed list of medical conditions permanently excludes donation', 0, 'Exclusion rules are frequently wrong and change as practice changes. This is why the course avoids teaching them.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('oqf7qny5p58iienqkcmovv3h', 'fcn3kz2rx5ttfjlvxsfil07n', 2, 'Anyone who has ever taken chronic medication is excluded', 0, 'Not so. This is exactly the kind of assumption that causes self-exclusion.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('qisuvlyq57dxmo26h3qshe3d', 'fcn3kz2rx5ttfjlvxsfil07n', 3, 'Eligibility is decided by the donor when they register', 0, 'Registration records wishes. Suitability is a medical assessment made at the time.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('uf5ul7ue7xnxf64hg1dmex1k', 'tlf3t8c1b6pcpqdy3fbm5skw', 0, 'Consent that is not understood is not genuinely informed consent', 1, 'Correct — translators are a consent safeguard, not a convenience.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('qsrunkj7t5ox21dkfrc0kozj', 'tlf3t8c1b6pcpqdy3fbm5skw', 1, 'They speed the process up', 0, 'Their purpose is the validity of consent, not efficiency.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('cso65zdkqobcjh34hmddejaw', 'tlf3t8c1b6pcpqdy3fbm5skw', 2, 'They are only needed for international patients', 0, 'South Africa has many languages. Translation is routinely relevant.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('kvp57qkfq06cwhwhnowa2ilf', 'tlf3t8c1b6pcpqdy3fbm5skw', 3, 'They are optional if a family member can interpret', 0, 'Relying on a grieving relative to interpret a consent conversation is not a safeguard.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('lmdlgvzfbdd3bo21wkptn7iv', 'ts6d2ma7se0z7hx3by1jq4d1', 0, 'The beginning of a lifelong medical journey involving ongoing medication and monitoring', 1, 'Correct. Overselling transplantation damages credibility.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('rn8vavjr8baq7q1r8b4xshai', 'ts6d2ma7se0z7hx3by1jq4d1', 1, 'A complete cure, with no further medical involvement', 0, 'A transplant is not a cure. Presenting it as one misrepresents recipients'' lives.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('ij8jr8dhp9yw620jw045ql75', 'ts6d2ma7se0z7hx3by1jq4d1', 2, 'A short recovery, then a return to exactly how things were before', 0, 'Recovery is real but the medical relationship continues indefinitely.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('zujth79z6btn3fkidsnb7nzy', 'ts6d2ma7se0z7hx3by1jq4d1', 3, 'A temporary fix that always fails within a few years', 0, 'Unduly pessimistic. Graft survival varies by organ and by person.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('eht73rvxkntdei9q6qfe3ln1', 'rx1ba729kgnkt4gz9ztflb7r', 0, 'Accept their position, and ask whether they would still tell their family what they want so nobody has to guess', 1, 'Correct. It fully respects their belief and still achieves the actual goal.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('ilu5e9ujigxypgb10sj48vwd', 'rx1ba729kgnkt4gz9ztflb7r', 1, 'Explain that most major religions do in fact permit organ donation', 0, 'Even where broadly true, telling someone what their own faith permits is overstepping, and you will lose their trust.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('urcw0m02v43n8fj0qelrq0s1', 'rx1ba729kgnkt4gz9ztflb7r', 2, 'Ask which religion, so you can look up its position for them', 0, 'Well-intentioned, but it puts you in the position of interpreting their faith to them.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('b3n94onzxhzwflrpgc5f7gun', 'rx1ba729kgnkt4gz9ztflb7r', 3, 'Move on to someone more likely to register', 0, 'This treats the person as a target rather than a participant in a conversation.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('eyznvo6xmmzj9dkid8jehnxp', 'r7pnqr0uhl8pvynu1zwmusr8', 0, 'Their organ has failed completely and cannot be repaired', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('f61xkc3bgue2vtgvt1e05avd', 'r7pnqr0uhl8pvynu1zwmusr8', 1, 'To improve the performance of a healthy organ', 0, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('kh0x6y4a0n8qfgbz34lgd22w', 'r7pnqr0uhl8pvynu1zwmusr8', 2, 'Because they have chosen a transplant over medication', 0, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('v7naezdkiqwao5fqz43q4sut', 'r7pnqr0uhl8pvynu1zwmusr8', 3, 'Only after a serious accident', 0, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('hegtpd9pu4qiupa2subs4xqy', 'qgtsvo1tjt9s94o7d0sktd9v', 0, 'Corneas', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('gm5ds50isk7kucn0io9xtdz5', 'qgtsvo1tjt9s94o7d0sktd9v', 1, 'Bone and ligaments', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('jn7evblsi6e1rwl533wdho7e', 'qgtsvo1tjt9s94o7d0sktd9v', 2, 'Skin', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('uanogiq9jcgqxek9e8vg9wvu', 'qgtsvo1tjt9s94o7d0sktd9v', 3, 'Kidneys', 0, 'A kidney is a solid organ.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('syvpszj5ulsdvhzhqv7ct288', 'qgtsvo1tjt9s94o7d0sktd9v', 4, 'Lungs', 0, 'Lungs are solid organs.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('cnskgjmklv1bz57vz1oa5g5t', 'o1wlaqal9suh49rjsfz4t9ir', 0, 'Donations are lost at several human points along the pathway, especially family refusal and never having discussed donation', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('oaztbyroyuhb4nle2a9z7y0r', 'o1wlaqal9suh49rjsfz4t9ir', 1, 'South Africa lacks the surgical skill to perform transplants', 0, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('gqhbw47f9otezl8syftmk1ii', 'o1wlaqal9suh49rjsfz4t9ir', 2, 'There are very few people who die in circumstances where donation is possible', 0, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('cft61teocfl3g6gn4qjjywow', 'o1wlaqal9suh49rjsfz4t9ir', 3, 'The law prohibits most organ donation', 0, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('v9nm5xe6apvt61d6o8endu70', 'ijx3hl5ptbo078tdbot1cll6', 0, 'Family refusal at the consent stage', 1, 'Correct — and this is why Save7''s entire premise is the conversation.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('hbq9679dam4yktt8w78l08tw', 'ijx3hl5ptbo078tdbot1cll6', 1, 'Failure to identify a potential donor in hospital', 0, 'A real loss point, but it is a clinical process issue rather than one a family conversation changes.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('qdib5vlzykpguqy1sbj5g0hs', 'ijx3hl5ptbo078tdbot1cll6', 2, 'Logistical constraints during recovery', 0, 'Not something a prior family conversation affects.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('gvieg87u4f68eyh8xrz46yu5', 'ijx3hl5ptbo078tdbot1cll6', 3, 'Allocation of the organ to a recipient', 0, 'Allocation happens after consent and is not affected by the family conversation.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('ejeoh3nrlhxuk3b6n9marcp3', 'mo17y61xa3k6yvebgyhlmmhk', 0, 'True', 0, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('ctaqbo3ld3x2hktgoeyoy9fe', 'mo17y61xa3k6yvebgyhlmmhk', 1, 'False', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('emsvghhd7qowbpvydqslqtwy', 'y71m4v47dz2n3cp7dzetk5nz', 0, 'Don''t rule yourself out — suitability is assessed individually by medical teams at the time', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('o9vkvm8tkhvuskv62xkqiiw2', 'y71m4v47dz2n3cp7dzetk5nz', 1, 'You''re right, that combination would exclude you', 0, 'A confident exclusion can permanently remove a potential donor.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('phzgmupotkbphs029bfp1oob', 'y71m4v47dz2n3cp7dzetk5nz', 2, 'Age and blood pressure make no difference at all to donation', 0, 'Overcorrection, and it damages your credibility when someone checks.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('jwt33pjzp3gyy4wytptgdrwh', 'y71m4v47dz2n3cp7dzetk5nz', 3, 'You could only donate corneas', 0, 'Speculating about a specific medical outcome. Keep the framing general.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('z0rsh18ydxeltdc1knn4lpoy', 'voiw1tanx6cuu9on5apz6ovo', 0, 'The clinicians who determine death are independent of the transplant team', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('q87wz4x0ez2m4swrkq85vyys', 'voiw1tanx6cuu9on5apz6ovo', 1, 'Doctors take an oath, so they would never do that', 0, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('y16w0xq0x7aaw49k50kk5euo', 'voiw1tanx6cuu9on5apz6ovo', 2, 'Hospitals are not told who is a registered donor', 0, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('oxvptzis06d076428j7ywhu8', 'voiw1tanx6cuu9on5apz6ovo', 3, 'It is illegal, so it does not happen', 0, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('kfzgl8fpwfulauvill1mivuy', 'criu18nbx9xn9rw4g3i8mlss', 0, 'Accept their position, and ask whether they would still tell their family what they want', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('moe6wr17ruelm5kidqwr0xn2', 'criu18nbx9xn9rw4g3i8mlss', 1, 'Explain that most major religions do in fact permit organ donation', 0, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('yqxrfyi2vkjaz28cu5p41k0p', 'criu18nbx9xn9rw4g3i8mlss', 2, 'Ask which religion, so you can look up its position for them', 0, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('t1tskhzkq0he42f7s5i440xu', 'criu18nbx9xn9rw4g3i8mlss', 3, 'Move on to someone more likely to register', 0, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('eqy6fuuy5i717zp2djmayw2h', 'jaxy7ekwv8xdvnhchatgffea', 0, 'Acknowledge the concern, and ask what worries them most about it', 1, 'Correct. You do not yet know whether this is about an open casket, religious rites, or something else.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('t4olmu9j2k3w15gcpsxx7i7q', 'jaxy7ekwv8xdvnhchatgffea', 1, 'Explain that they won''t feel anything because they''ll be dead', 0, 'Technically responsive and emotionally tone-deaf. The objection was never about pain.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('zf7emrey780donbjhegf2ldl', 'jaxy7ekwv8xdvnhchatgffea', 2, 'Point out that seven other people could benefit', 0, 'The reframe is true, but leading with it before acknowledging the concern feels like being sold to.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('u3cm7dk5kvge0a423annn6t3', 'jaxy7ekwv8xdvnhchatgffea', 3, 'Give them a leaflet about the recovery procedure', 0, 'Information without acknowledgement rarely resolves a concern about dignity.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('qamm957afpz9e7z025qn916r', 'fje6xi8fh8p5qilkmo7c36k5', 0, 'Simply starting the conversation', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('dudm19wye0fh81ct3abg83ac', 'fje6xi8fh8p5qilkmo7c36k5', 1, 'Persuading as many people as possible to register', 0, 'Registration matters, but the conversation is what makes wishes actionable.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('sqn5igxwamew29zehnl7r7ug', 'fje6xi8fh8p5qilkmo7c36k5', 2, 'Correcting every myth you hear', 0, 'Correction matters less than being someone people will talk to.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('kkxjbuxeapphmnw28vo6y2qy', 'fje6xi8fh8p5qilkmo7c36k5', 3, 'Being able to answer any medical question', 0, '"I''ll find out" is a perfectly good answer, and often the better one.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('ig8hpok8beepea9nk5sncp74', 'qxw1of5p61zifyq1ndos5ycl', 0, 'Yes — death has been determined by neurological criteria, and ventilation is what allows the heart to continue', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('g6hb93gjukpmkwrvtcqida9o', 'qxw1of5p61zifyq1ndos5ycl', 1, 'No — a beating heart means the person is still alive', 0, 'This is the misconception at the heart of the module. Brain death is death.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('un5lv9mp6h8qv4f1yn9nxxov', 'qxw1of5p61zifyq1ndos5ycl', 2, 'Only once the ventilator has been switched off', 0, 'Death has already been determined. Withdrawal of ventilation does not constitute the determination.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('v573wccuyryc3g1axpaubq1p', 'qxw1of5p61zifyq1ndos5ycl', 3, 'It depends on whether the family agrees', 0, 'Determination of death is a clinical and legal process, not a family decision. Consent for donation is a separate question.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('ucgfi6kp7zvldrf2e7a4006x', 'f4e3i601i3ioi2p9kb1bvcgj', 0, 'True', 0, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('mpyk35zixsrkkhfx2uixwyr7', 'f4e3i601i3ioi2p9kb1bvcgj', 1, 'False', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('gcj9rc8y4kmx6gx4z4cynojn', 'ifivnsou94y3zm3n4hq01p0j', 0, 'It is a deliberate safeguard: those determining death are independent of the transplant team', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('rt0yac0ir0744z0ztgucmhtb', 'ifivnsou94y3zm3n4hq01p0j', 1, 'It speeds up the donation process', 0, 'Safeguards are not there for efficiency.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('mqs5977lmsss93c93e13asfm', 'ifivnsou94y3zm3n4hq01p0j', 2, 'It is required only when the family requests it', 0, 'It is part of the process, not an optional extra.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('uilru3anfulbysx3qta7joch', 'ifivnsou94y3zm3n4hq01p0j', 3, 'It allows the transplant team to select suitable donors earlier', 0, 'This describes exactly the conflict of interest the separation exists to prevent.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('yiuh8fj4oiv40cdf1lhpt65s', 'kxrrmrq6dh6nouymyj4awvtn', 0, 'Donor management', 1, 'Correct — a real and skilled stage of care that public conversation usually omits.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('a1j506smwsaz76nzz8ufj7uy', 'kxrrmrq6dh6nouymyj4awvtn', 1, 'Allocation', 0, 'Allocation comes later, after recovery.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('oio2xalnekmgd7pucsk5b2u5', 'kxrrmrq6dh6nouymyj4awvtn', 2, 'Determination of death', 0, 'Death is determined before the family is approached for consent.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('jvqidikx5jimst2ns2j3iz9k', 'kxrrmrq6dh6nouymyj4awvtn', 3, 'Transplantation', 0, 'Several stages come between consent and transplantation.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('pqvcwrnsferznnhe2uuf7jzd', 'bv4d0qe3a2q1onhovl5uvspt', 0, 'A matching process between donor organs and recipients', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('phhbilyukjt0l4zl7c1scwx5', 'bv4d0qe3a2q1onhovl5uvspt', 1, 'First come, first served from a waiting list', 0, 'Allocation is a matching process, not a simple queue.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('jsd8sb66q1xb8yaar0qxw7le', 'bv4d0qe3a2q1onhovl5uvspt', 2, 'Decided by the donor''s family', 0, 'Families consent to donation; they do not allocate organs.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('d23xmmciesftj8cgrqiic5v4', 'bv4d0qe3a2q1onhovl5uvspt', 3, 'Decided by whichever hospital recovers the organ', 0, 'Allocation follows a matching process rather than institutional convenience.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('j1un93fopsakuz9fjywusaur', 'iwp9dfuxhlcitcpgmk15x2a3', 0, 'The doctors who determine death, who are independent of the transplant team', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('du2knr53uoxpelprbguc6t1d', 'iwp9dfuxhlcitcpgmk15x2a3', 1, 'The tissue recovery technician', 0, 'An essential clinical role, but not a safeguard against conflict of interest.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('rmupx38gh2oic969rv4hajvz', 'iwp9dfuxhlcitcpgmk15x2a3', 2, 'The primary treating team', 0, 'They provide treatment, long before donation is considered.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('yry4775o9975kajg0mjp6nez', 'iwp9dfuxhlcitcpgmk15x2a3', 3, 'The transplant surgeon', 0, 'A treating role, and precisely the one the independence safeguard separates from determining death.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('qzkfbhls837v314wzix4v2fb', 'nc6wdm4suua0qk65dyqlf3ol', 0, 'Consent that is not understood is not genuinely informed consent', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('h3v9c6fyhgd0a0mgsuo6plu2', 'nc6wdm4suua0qk65dyqlf3ol', 1, 'It makes the family feel more comfortable', 0, 'True but incidental. The point is the validity of consent.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('junatdrzfa94pumjg6nws8bc', 'nc6wdm4suua0qk65dyqlf3ol', 2, 'It is only needed for patients from other countries', 0, 'South Africa has many languages spoken by its own citizens.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('d2bo7j7ig2a73add657zx19a', 'nc6wdm4suua0qk65dyqlf3ol', 3, 'A family member can always do it instead', 0, 'Relying on a grieving relative to interpret a consent conversation is not a safeguard.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('fo4desyhvrpmq4bv3xalge9m', 'z9jyij6s1peb7eefpgf36yd4', 0, 'No — suitability is assessed individually by medical teams at the time', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('gz7yoqfdiv7gzip2vkrfnexp', 'z9jyij6s1peb7eefpgf36yd4', 1, 'Yes, hypertension is an absolute exclusion', 0, 'Simple exclusion rules are frequently wrong and change as practice changes.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('g1zu4vywlotmg4df6b5sk8rw', 'z9jyij6s1peb7eefpgf36yd4', 2, 'No, because hypertension has no bearing on donation at all', 0, 'Overcorrection. The honest answer is that it is assessed, not that it is irrelevant.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('qq67xjkrhpp187qnc3ojrvs6', 'z9jyij6s1peb7eefpgf36yd4', 3, 'Only tissue donation would be possible', 0, 'This invents a rule rather than describing the assessment.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('e3vw6ndksccgidvaw7rbv26i', 'dwgfqhkgeqifzyqsvtujrdow', 0, 'Nothing automatically — suitability can differ between organs and tissues', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('pabx4guag7hova3p6yxeiahq', 'dwgfqhkgeqifzyqsvtujrdow', 1, 'They are excluded from donating anything', 0, 'Assessment can be organ-specific.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('ctsvdsdjkm4psv6ptv8f5hmn', 'dwgfqhkgeqifzyqsvtujrdow', 2, 'They must be re-registered before anything else can be considered', 0, 'Registration is not the constraint here.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('nb1ratsmznbrhxivknxahtc5', 'dwgfqhkgeqifzyqsvtujrdow', 3, 'Their family must consent a second time', 0, 'Not how consent operates.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('jirjzswxoljk1xtcvyvt7cb2', 'tqipcs9try76gdn2wii0pi11', 0, 'Do not assume anyone cannot donate — suitability is medically assessed', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('jiro44ufe561bzjv0cr90bec', 'tqipcs9try76gdn2wii0pi11', 1, 'Most people over sixty are unsuitable', 0, 'An invented exclusion rule.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('p00s5eq0v7aj82wlgy06cevl', 'tqipcs9try76gdn2wii0pi11', 2, 'Healthy people are the only realistic donors', 0, 'This drives exactly the self-exclusion the module warns about.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('evl0dh1xe0z6dzmip6ulknn4', 'tqipcs9try76gdn2wii0pi11', 3, 'Eligibility can be worked out from a checklist', 0, 'The course deliberately avoids teaching exclusion checklists.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('sdqidq5hbfleqo4zfzip81qw', 'qlg7jnry1yli48hvkks2lsu3', 0, 'A surgical procedure carried out with the same care as any other operation', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('o9sollhb1ye3beroj6iw209u', 'qlg7jnry1yli48hvkks2lsu3', 1, 'A rapid procedure where appearance is not a consideration', 0, 'This feeds precisely the fear that causes refusals.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('hdcnvl34r5w8p3chcooiyt77', 'qlg7jnry1yli48hvkks2lsu3', 2, 'A post-mortem examination', 0, 'Recovery is not a post-mortem, though a forensic examination may be separately required in some deaths.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('kgydkrfpuf9b0ilqipl85s3i', 'qlg7jnry1yli48hvkks2lsu3', 3, 'Something performed by the primary treating team', 0, 'Recovery is performed by recovery teams, separate from those who determined death.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('ny26aiqcaand36eqn6lgtbh4', 's7pkuxxw2qnjum8nzthzsded', 0, 'Acknowledge that it genuinely looks impossible, then explain simply what the ventilator is doing', 1, 'Correct — the acknowledgement is what makes the explanation land.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('mbivdkk0x6rig7erjg8zq4nf', 's7pkuxxw2qnjum8nzthzsded', 1, 'Explain that brain death is legally death and the family were mistaken', 0, 'Accurate and useless. It corrects the family rather than helping your friend understand.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('d4hi2cndw3jadnbrgqbksivl', 's7pkuxxw2qnjum8nzthzsded', 2, 'Say that monitors can be misleading and leave it there', 0, 'Vague, and it implies the equipment was at fault rather than explaining anything.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('tf7pgaeqeous27kmb6dr0n2q', 's7pkuxxw2qnjum8nzthzsded', 3, 'Avoid the question, since it is a clinical matter', 0, 'This is exactly the question the course prepares you to answer, kindly and accurately.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('cea64f8vh84gdtrbbe8i5n65', 'g3airo0yuuvpf8yfp52gm4te', 0, 'The beginning of a lifelong medical journey', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('nwq84ad2dj04k6dux2lac7ow', 'g3airo0yuuvpf8yfp52gm4te', 1, 'A complete cure', 0, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('qbi8u1sx29pdq01v49arvz0d', 'g3airo0yuuvpf8yfp52gm4te', 2, 'A short recovery, then life exactly as before', 0, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('re13iprkcrebmjtktwunk6pu', 'g3airo0yuuvpf8yfp52gm4te', 3, 'A temporary fix that always fails within a few years', 0, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('td0t7lzjxl02yflwzn4fny1p', 'u29m63tw5w9zfk2p97hirgyx', 0, 'The National Health Act', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('sech18ntbrlx9z4scns7vrib', 'u29m63tw5w9zfk2p97hirgyx', 1, 'The Human Tissue Act, which remains the current governing statute', 0, 'Earlier legislation governed this area historically. Always verify which provisions are currently in force.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('vfa2zyqyfcs2swpjw2c0p8lp', 'u29m63tw5w9zfk2p97hirgyx', 2, 'The Consumer Protection Act', 0, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('y43lwouggps0vyct3ys08525', 'u29m63tw5w9zfk2p97hirgyx', 3, 'There is no specific statute; it is governed by common law alone', 0, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('fquxrxdmb9on5ep2gsprcg9h', 'fqnhk79aqhi5d0napatjm9qa', 0, 'Whether they are giving an educational explanation, stating a legal requirement, or relaying clinical guidance', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('gerbxv0wr6j804fuavps5o5j', 'fqnhk79aqhi5d0napatjm9qa', 1, 'Whether the questioner is a medical professional', 0, 'Your accuracy obligation does not change with the audience.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('t197zfpw9qcyhvs4jvntvbnz', 'fqnhk79aqhi5d0napatjm9qa', 2, 'Whether the answer is likely to encourage registration', 0, 'Advocacy must never shape the accuracy of an answer.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('nwh2jxbid6y3lt7uumukd1kr', 'fqnhk79aqhi5d0napatjm9qa', 3, 'Whether the question relates to organs or tissue', 0, 'Relevant to the content, but not the distinction that protects against misleading someone.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('s3ft1vh6xrocjzx9eak0g25t', 'gb0ujlt43sd5ikuz0cnw7z3i', 0, 'They bring additional legal requirements and forensic authorities into the process', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('wel5yxhjhng9yywzivdz2ugp', 'gb0ujlt43sd5ikuz0cnw7z3i', 1, 'Donation is never possible after an unnatural death', 0, 'An overstatement. Additional requirements apply rather than an absolute bar.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('x8k4umlj06ernk8958bz968j', 'gb0ujlt43sd5ikuz0cnw7z3i', 2, 'The family loses the right to consent', 0, 'Not an accurate description of how consent operates.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('suummomrbi5698h7xzwsxij8', 'gb0ujlt43sd5ikuz0cnw7z3i', 3, 'Only tissue may be donated in such cases', 0, 'This invents a rule.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('uns9ykffdsuarpxd5zb10giw', 'jfdf0hn9xdx10id3y0civ6c1', 0, 'Most are relative rather than absolute, and several have changed over time', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('cjvynubhyd33flp5xiz56oyu', 'jfdf0hn9xdx10id3y0civ6c1', 1, 'They are fixed and universally agreed', 0, 'They are neither fixed nor universally agreed.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('jywsbkbnhjm0qtzer9emyg8r', 'jfdf0hn9xdx10id3y0civ6c1', 2, 'They are decided by the patient''s own doctor alone', 0, 'Candidate selection is a specialist multidisciplinary judgement.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('suzmt0pkzzj0jop2eeomftoh', 'jfdf0hn9xdx10id3y0civ6c1', 3, 'Age is the only meaningful contraindication', 0, 'Age is one factor among many, and rarely an absolute one.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('z575e6dohi4sz60twengd2m1', 'jdyfybovgai4kbk301c070ja', 0, 'It means transplantation is not always the only option', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('j7w9lr1nbzjhy34ekoexjw54', 'jdyfybovgai4kbk301c070ja', 1, 'It replaces transplantation entirely', 0, 'It does not replace transplantation.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('gn5lywughory4vf7yi9zlfr9', 'jdyfybovgai4kbk301c070ja', 2, 'It is only used after a transplant has failed', 0, 'Too narrow a description of its role.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('u4zc34proouy01hyt6wdj7h8', 'jdyfybovgai4kbk301c070ja', 3, 'It removes the need for donor organs nationally', 0, 'The need for donated organs remains.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('agkrzofrob561f6g834bt3nq', 'sfifmkz5ny8e80nohkcxar82', 0, 'Prognostic assessment forms part of allocation, alongside matching', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('wm973l3galw710rwijwgscw1', 'sfifmkz5ny8e80nohkcxar82', 1, 'Because allocation is random', 0, 'It is not random.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('cmuajwjj6f7hzeg397z5yyvn', 'sfifmkz5ny8e80nohkcxar82', 2, 'Because the wealthiest patients are prioritised', 0, 'This describes an inequity concern, not how allocation is designed to work.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('n4gnb75gz2w6ifj93npst573', 'sfifmkz5ny8e80nohkcxar82', 3, 'Because allocation is decided by the donor family', 0, 'Families consent; they do not allocate.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('ufvczaxxthv2e1c70o0n5rce', 'vs5a2tt118q37xc0rne2wdxt', 0, 'It prevents rejection but carries its own risks — a trade-off', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('w5pepf44tfmh2seikd2cqy3k', 'vs5a2tt118q37xc0rne2wdxt', 1, 'A short course of medication after the operation', 0, 'It is generally ongoing rather than a short course.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('i3meybc82vqxnq4ti2wa83sw', 'vs5a2tt118q37xc0rne2wdxt', 2, 'A cure for rejection', 0, 'It reduces the risk of rejection; it does not cure it.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('kkqmiclersd8imuzof1onyj7', 'vs5a2tt118q37xc0rne2wdxt', 3, 'Optional, depending on the recipient''s preference', 0, 'Not a matter of preference.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('yp1jds5uwnpnihvbv82dgajj', 'f8io3lxx4m5p1365r2e11gaf', 0, 'True', 0, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('q79ngx182vl5crgrw4bkjqvn', 'f8io3lxx4m5p1365r2e11gaf', 1, 'False', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('df28ak0t9j21l2fw0lta8lwm', 'd3msxm6g3xw2ymd8k5o050uj', 0, 'Overselling damages credibility and misrepresents recipients'' experience', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('htiid06ggao119vy893kesv8', 'd3msxm6g3xw2ymd8k5o050uj', 1, 'Because transplantation usually fails', 0, 'Not the reason, and not accurate.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('sj3sl0tbr4k6fo1r92ly5mag', 'd3msxm6g3xw2ymd8k5o050uj', 2, 'Because optimism is unprofessional', 0, 'Honesty is the point, not the absence of hope.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('hsh6tuvcbjqz7zcf8886o9m2', 'd3msxm6g3xw2ymd8k5o050uj', 3, 'To discourage unsuitable candidates from applying', 0, 'Not the purpose of honest advocacy.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('ileqastncgfp5j6yb4twu7t3', 'q87hk9593cp9iasr4br2v24w', 0, 'Acknowledge how impossible it feels, make clear nobody is asking them to give up, and then stop talking', 1, 'Correct. Silence is a legitimate and often the best contribution here.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('wq0zfdg106ez9n31dkv4190i', 'q87hk9593cp9iasr4br2v24w', 1, 'Explain that brain death is legally and medically death, and that the ventilator keeps the heart beating', 0, 'The facts are right and the timing is wrong. This explanation belongs to the clinical team, not to you, and not now.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('wbwlp3sl5fw1m0orce8mlj8g', 'q87hk9593cp9iasr4br2v24w', 2, 'Gently point out that she would have wanted to help others', 0, 'This puts words in the patient''s mouth and will be experienced as pressure. It can permanently damage trust.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('q4vjkylojvj68fc53xmbjolj', 'q87hk9593cp9iasr4br2v24w', 3, 'Ask whether they have considered how many people could be helped', 0, 'Applying pressure during acute grief. Harmful.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('a23587a66yz9gp4vl3x4btmb', 'cj12h6povq85x9o1crge5sm3', 0, 'Take the concern seriously, ask what they have seen, and be honest that inequity in access is a real problem', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('wmir668d7xnmxzcyw280rcu5', 'cj12h6povq85x9o1crge5sm3', 1, 'Reassure them immediately that allocation is based on medical criteria only', 0, 'It may be accurate, but as a first response it sounds like a denial of their experience. Trust has to precede information.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('x2gjs47v58hv6uq6he9rl58o', 'cj12h6povq85x9o1crge5sm3', 2, 'Point out that they might need a transplant themselves one day', 0, 'Self-interest framing on top of an equity concern lands as manipulative.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('ywp86yx7f9x16ejjtgbde4zo', 'cj12h6povq85x9o1crge5sm3', 3, 'Explain that this is a misconception about the allocation system', 0, 'Labelling a structural concern a misconception ends the conversation.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('inm082u0tbosq16ezau5pwkq', 'v31d9th3bdmqr8sbtnbpe4n8', 0, 'Accept their position, and ask whether they have told the family so nobody has to guess', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('q35mwuhstsajt0jfbmedqldc', 'v31d9th3bdmqr8sbtnbpe4n8', 1, 'Explain that recovery is surgical and would not usually affect burial', 0, 'Sometimes useful information, but offered unprompted against a stated conviction it reads as trying to talk them out of it.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('bg3lh2li4od73mhgh3kr3s6z', 'v31d9th3bdmqr8sbtnbpe4n8', 2, 'Ask whether tissue donation might be more acceptable', 0, 'Negotiating around a stated conviction. It signals you did not accept their answer.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('rpbpbw4eydfrt1mbe91p70fn', 'v31d9th3bdmqr8sbtnbpe4n8', 3, 'Explain how many people a single donor can help', 0, 'Applying pressure to a settled belief.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('socfsrbjcng3y601bebbenpk', 'dn295a036j81no6bwec7vpdf', 0, 'Say you don''t want to give an uncertain number, and offer to find the current figure from an authoritative source', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('s6fd4weepfz0qq8rb7fkrnc9', 'dn295a036j81no6bwec7vpdf', 1, 'Give your best recollection with a caveat that you''re not certain', 0, 'The caveat does not travel with the number once they repeat it.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('fd0wzn4ud6yspx3nq96e045i', 'dn295a036j81no6bwec7vpdf', 2, 'Give a round approximation to keep the conversation moving', 0, 'Inventing a figure damages Save7''s credibility as well as your own.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('nx4gorb0q3v37en6dpqyb7xj', 'dn295a036j81no6bwec7vpdf', 3, 'Say that statistics are unreliable and change the subject', 0, 'Sounds evasive, and does not answer a fair question.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('orwayjmvhp3wjotqwt4vv5w8', 'xvx590uaf9f8d277hvrmp1tt', 0, 'Decline to take a side, remove any sense of rush, and offer to have the team explain the options to them together', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('kxwh1ejc3q8igof2a6pjy5yj', 'xvx590uaf9f8d277hvrmp1tt', 1, 'Support the sibling who says he wanted to donate, since they have the relevant information', 0, 'Taking a side inside a grieving family is not your role.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('fp1ztp2jmt2krsks99cbyrst', 'xvx590uaf9f8d277hvrmp1tt', 2, 'Explain who is legally entitled to consent so they know where they stand', 0, 'It may be relevant, but from an advocate in a live family dispute it reads as picking a winner. Better from the coordinator.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('e4b3vk12zpf1wr2on6lt6yzu', 'xvx590uaf9f8d277hvrmp1tt', 3, 'Suggest they decide quickly, since donation is time-sensitive', 0, 'Applying time pressure to a grieving family is not yours to do.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('ig02nh1b69pbzmqvzjs7c5i8', 'a8gdhiap5zycforxyml8hxnz', 0, 'Recognising when a conversation has moved beyond your role, and referring it', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('c60ldkoetspg5fyn0bxtob81', 'a8gdhiap5zycforxyml8hxnz', 1, 'Answering every question asked of you', 0, '"I''ll find out" is often the better answer.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('zgseq1kpfhyqmfmblxpxdvun', 'a8gdhiap5zycforxyml8hxnz', 2, 'Persuading everyone you speak to', 0, 'The goal is a conversation, not a conversion.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('m6hkcz8i2zy2a0znkvjdmmsw', 'a8gdhiap5zycforxyml8hxnz', 3, 'Providing emotional counselling to bereaved families', 0, 'That is not an advocate''s role, and attempting it can do harm.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('n6c3myqarmsb1mlxzrpuraq1', 'xzp0astk7a5fsoovgsi3ex80', 0, 'The organ can no longer sustain its function and cannot be repaired', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('znihr3uzi8gbgjanhrx91cs9', 'xzp0astk7a5fsoovgsi3ex80', 1, 'The organ is working at reduced capacity but is stable', 0, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('fnd9fyh72h9ydr53rfcdai5z', 'xzp0astk7a5fsoovgsi3ex80', 2, 'The organ has been surgically removed', 0, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('ya4auzk44osjxo5bj36b6dfy', 'xzp0astk7a5fsoovgsi3ex80', 3, 'The organ is failing but will recover with medication', 0, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('x1ouemyzdlr9xnwxo3u130ug', 'd0ys9mv5ln7d0ooytlk7n9kp', 0, 'Corneas', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('bu8t9bqn2ktwvzurr6udkum1', 'd0ys9mv5ln7d0ooytlk7n9kp', 1, 'Skin', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('jkthhzd6qqxy6zn9dbr1d6o8', 'd0ys9mv5ln7d0ooytlk7n9kp', 2, 'Heart valves', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('z15tlqf3tgui8ujex6walj99', 'd0ys9mv5ln7d0ooytlk7n9kp', 3, 'Pancreas', 0, 'The pancreas is a solid organ.');
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('d71nfe53dcawul2yrwafu18t', 'vd3u8iwcwcl2raz47kc47xfe', 0, 'One decision can save seven lives', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('re8hvhapm98swbzuc9abo0ze', 'vd3u8iwcwcl2raz47kc47xfe', 1, 'Seven organs are transplanted in every donation', 0, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('mp4qtlbtil15edxzx234k11i', 'vd3u8iwcwcl2raz47kc47xfe', 2, 'The organisation was founded by seven people', 0, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('u1e4aoh9nvj74d2yjqo7vjk4', 'vd3u8iwcwcl2raz47kc47xfe', 3, 'Seven hospitals perform transplants in South Africa', 0, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('ybge0xxqzj05f6j8ccoxgtjd', 'f9g13zfwq763buqetz6fdcnf', 0, 'Family refusal at the consent stage', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('f9e5i8qnwrs6s988ta1hy96z', 'f9g13zfwq763buqetz6fdcnf', 1, 'Surgical complications during recovery', 0, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('w8tnmtpvjtmh86th7gwygw6b', 'f9g13zfwq763buqetz6fdcnf', 2, 'A shortage of transplant surgeons', 0, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('fvwohbzchyp96lsshvxtkabd', 'f9g13zfwq763buqetz6fdcnf', 3, 'Organs being damaged in transit', 0, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('rxq6gx67mvt1hfhr5oxyri5a', 'hykneun9oeskan9z9ouvnpus', 0, 'It lets you respond to the real concern instead of dismissing the person', 1, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('sdf58uhviw8qcbh6qk8c3mev', 'hykneun9oeskan9z9ouvnpus', 1, 'It makes the myth easier to remember', 0, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('uqy82odzlra8hf24buggammi', 'hykneun9oeskan9z9ouvnpus', 2, 'It proves the person is being unreasonable', 0, NULL);
INSERT INTO "Choice" ("id", "questionId", "order", "text", "isCorrect", "feedback") VALUES ('n4k395atl1tj4idzhkjw83bk', 'hykneun9oeskan9z9ouvnpus', 3, 'It is not useful — correcting the fact is enough', 0, NULL);
